INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('itsmostafa/aws-agent-skills/iam', 'iam', 'itsmostafa', 'aws-agent-skills', 'community', 'iam itsmostafa aws-agent-skills community The iam skill enables secure access control to AWS services and resources, providing foundational security for every AWS API call. This skill benefits AI agents and developers working with AWS. AWS IAM 提供安全的访问控制和身份管理，实现对 AWS 服务和资源的安全访问 AWS IAM は、AIエージェントのセキュリティを強化するための基礎となる機能です AWS IAM은 보안 및 접근 관리를 위한 핵심 기능을 제공합니다 IAM es un servicio de AWS que permite el control de acceso seguro a los servicios y recursos de AWS. Aprende a utilizar IAM para gestionar el acceso y mejorar la seguridad. IAM est un service AWS qui permet le contrôle d''accès sécurisé aux services et ressources AWS. Apprenez à utiliser IAM pour gérer l''accès et améliorer la sécurité. IAM ist ein AWS-Dienst, der den sicheren Zugriff auf AWS-Dienste und -Ressourcen ermöglicht. Erfahren Sie, wie Sie IAM verwenden können, um den Zugriff zu verwalten und die Sicherheit zu verbessern. O IAM é um serviço de gerenciamento de identidade e acesso da AWS que permite controle de acesso seguro aos serviços e recursos da AWS. IAM — это служба управления идентификацией и доступом AWS, обеспечивающая безопасный контроль доступа к сервисам и ресурсам AWS. IAM هو خدمة إدارة الهوية والوصول من AWS التي تمكن التحكم في الوصول الآمن إلى خدمات و موارد AWS. how to use iam what is iam iam alternative iam vs aws security iam install iam setup guide aws identity and access management iam best practices iam troubleshooting AWS IAM 身份和访问管理 安全访问控制 AWS 服务 CLI Reference Best Practices Troubleshooting AIエージェント アイデンティティおよびアクセス管理 Enables secure access control to AWS services and resources Authenticates and authorizes every AWS API call Supports core concepts such as principals and entities Provides best practices for secure access control Includes troubleshooting guides for common issues References CLI commands for easy implementation iam is AWS Identity and Access Management, a service that enables secure access control to AWS services and resources through authentication and authorization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chanhee-kang/oh-my-gemini/learner', 'community', 'chanhee-kang', 'oh-my-gemini', 'chanhee-kang/oh-my-gemini', 'learner', 0, 0, 42, '2026-03-08T01:57:15.658Z', '2026-03-08T02:14:00.367Z', '86e1f983d05459ae518657f517e15301ed509d9e5e310ec0fba82e4335a7ba66', '{"id":"chanhee-kang/oh-my-gemini/learner","name":"learner","description":{"en":"The Learner skill enables developers to create reusable principles and decision-making heuristics for AI agents, teaching them how to think about complex problems. This skill benefits developers working with async network code.","zh":"Learner 技能提供异步网络代码错误处理和可重用原则，帮助开发者创建更强大的 AI 工具","ja":"Learner スキルは、AIエージェントの開発を強化するための再利用可能な原則と、非同期ネットワークコードのエラーハンドリングを提供します","ko":"Learner 스킬은 비동기 네트워크 코드 오류 처리와 재사용 가능한 원칙을 제공하여 개발자가 더 강력한 AI 툴을 개발할 수 있도록 합니다","es":"El Skill Learner enseña a Claude cómo pensar en una clase de problemas mediante principios y heurísticas reutilizables. Mejora la toma de decisiones en tus Agentes de IA","fr":"Le Skill Learner enseigne à Claude comment réfléchir à une classe de problèmes grâce à des principes et des heuristiques réutilisables. Améliorez la prise de décision dans vos Outils d''IA","de":"Das Learner-Skill lehrt Claude, wie man an eine Klasse von Problemen denkt, indem man Prinzipien und Heuristiken wiederholt. Verbessern Sie die Entscheidungsfindung in Ihren KI-Tools","pt":"O Learner é um skill que ensina princípios e heurísticas de tomada de decisão para desenvolver soluções de IA robustas.","ru":"Learner - это навык, который учит принципам и евристикам принятия решений для разработки устойчивых решений ИИ.","ar":"Learner هو مهارة تعليمية تدرس مبادئ وآليات اتخاذ القرارات لتطوير حلول ذكية قوية"},"seo":{"title":{"en":"Learner: Reusable Skill Development for AI Agents | AI Ag...","zh":"Learner 技能最佳实践：异步网络代码错误处理","ja":"Learner スキルセットアップガイド：AIエージェントのための再利用可能な原則","ko":"Learner 스킬 설정 가이드: 비동기 네트워크 코드 오류 처리를 위한 원칙","es":"Guía de configuración del Skill Learner para Agentes de IA","fr":"Guide de mise en place du Skill Learner pour Outils d''IA","de":"Einrichtungsleitfaden für das Learner-Skill für KI-Tools","pt":"Guia de Configuração do Learner: Melhores Práticas para D...","ru":"Настройка навыка Learner: Руководство для разработчиков И...","ar":"دليل إعداد Learner: أفضل ممارسات لمركز تطوير الأدوات الذكية"},"description":{"en":"Unlock the power of reusable skills with Learner. Discover how to teach Claude problem-solving principles and heuristics. Get started with Learner today!","zh":"了解 Learner 技能的技术细节，包括异步网络代码错误处理和可重用原则，开发更强大的 AI 工具","ja":"Learner スキルの技術的な詳細を学び、AIエージェントの開発を強化するための再利用可能な原則を理解しましょう","ko":"Learner 스킬의 기술적인 세부 정보를 학습하고, 비동기 네트워크 코드 오류 처리를 위한 원칙을 적용하여 더 강력한 AI 툴을 개발하세요","es":"Aprende a configurar el Skill Learner para mejorar la toma de decisiones en tus Agentes de IA. Descubre los principios y heurísticas detrás de este skill","fr":"Découvrez comment configurer le Skill Learner pour améliorer la prise de décision dans vos Outils d''IA. Comprenez les principes et les heuristiques qui se ca...","de":"Erfahren Sie, wie Sie das Learner-Skill für KI-Tools einrichten, um die Entscheidungsfindung zu verbessern. Lernen Sie die Prinzipien und Heuristiken hinter ...","pt":"Aprenda a configurar o Learner para desenvolver soluções de IA robustas e escaláveis. Descubra as melhores práticas para implementar princípios e heurísticas...","ru":"Узнайте, как настроить навык Learner для разработки устойчивых и масштабируемых решений ИИ. Откройте для себя лучшие практики для реализации принципов и еври...","ar":"تعلم كيفية إعداد Learner لتطوير حلول ذكية قوية ومتناسقة. اكتشف أفضل الممارسات لتطبيق مبادئ وآليات اتخاذ القرارات"},"definition":{"en":"Learner is a skill that teaches AI agents reusable principles and decision-making heuristics for solving complex problems, focusing on async network code and I/O operation failures.","zh":"Learner 技能是一种提供异步网络代码错误处理和可重用原则的技术，用于开发更强大的 AI 工具","ja":"Learner スキルとは、AIエージェントの開発を強化するための、再利用可能な原則と非同期ネットワークコードのエラーハンドリングを提供する技術です","ko":"Learner 스킬은 비동기 네트워크 코드 오류 처리와 재사용 가능한 원칙을 제공하여 더 강력한 AI 툴을 개발할 수 있는 기술입니다","es":"El Skill Learner es un conjunto de principios y heurísticas que enseñan a los Agentes de IA cómo pensar en una clase de problemas de manera reutilizable","fr":"Le Skill Learner est un ensemble de principes et d''heuristiques qui enseignent aux Outils d''IA comment réfléchir à une classe de problèmes de manière réutilisable","de":"Das Learner-Skill ist eine Sammlung von Prinzipien und Heuristiken, die KI-Tools lehren, wie man an eine Klasse von Problemen denkt, indem man wiederholt","pt":"O que é Learner? Um skill de IA que ensina desenvolvedores a pensar em problemas de rede assíncrona.","ru":"Что такое Learner? Навык ИИ, который учит разработчиков мыслить о проблемах асинхронной сети.","ar":"ما هو Learner؟ مهارة ذكية تعليمية تعلم المطورين التفكير في مشاكل الشبكة غير المتزامنة"},"features":{"en":["Teaches Claude problem-solving principles for async network code","Enables wrapping of I/O operations to handle independent failures","Applies decision-making heuristics for client/server lifecycle mismatches","Develops reusable skills for AI agents, beyond code snippets","Handles ConnectionResetError and other I/O operation failures","Improves AI agent resilience in distributed systems"],"zh":["异步网络代码错误处理","可重用原则","独立的 I/O 操作失败处理","客户端/服务器生命周期不匹配处理","非阻塞式的网络编程"],"ja":["非同期ネットワークコードのエラーハンドリング","再利用可能な原則","独立した I/O 操作の失敗処理","クライアント/サーバーのライフサイクル不一致処理","ノンブロッキングなネットワークプログラミング"],"ko":["비동기 네트워크 코드 오류 처리","재사용 가능한 원칙","독립적인 I/O 操作 실패 처리","클라이언트/서버 생명주기 불일치 처리","논블로킹 네트워크 프로그래밍"],"es":["Principios reutilizables para la toma de decisiones","Heurísticas para la gestión de errores en operaciones de I/O","Capacidad para wraps de operaciones de I/O de forma independiente","Mejora de la estabilidad en código de red asíncrono","Integración con tecnologías de programación asíncrona","Optimización de la gestión de errores en entornos de cliente/servidor"],"fr":["Principes réutilisables pour la prise de décision","Heuristiques pour la gestion des erreurs dans les opérations de I/O","Capacité à envelopper les opérations de I/O de manière indépendante","Amélioration de la stabilité dans le code de réseau asynchrone","Intégration avec les technologies de programmation asynchrone","Optimisation de la gestion des erreurs dans les environnements client/serveur"],"de":["Wiederverwendbare Prinzipien für die Entscheidungsfindung","Heuristiken für die Fehlerbehandlung in I/O-Operationen","Fähigkeit, I/O-Operationen unabhängig zu kapseln","Verbesserung der Stabilität in asynchronem Netzwerkcode","Integration mit asynchroner Programmiertechnologie","Optimierung der Fehlerbehandlung in Client/Server-Umgebungen"],"pt":["Princípios de programação assíncrona","Heurísticas de tomada de decisão para I/O operations","Tratamento de erros em operações de rede","Desenvolvimento de soluções escaláveis e robustas","Integração com tecnologias de IA e machine learning"],"ru":["Принципы асинхронного программирования","Евристики принятия решений для операций ввода/вывода","Обработка ошибок в операциях сети","Разработка масштабируемых и устойчивых решений","Интеграция с технологиями ИИ и машинного обучения"],"ar":["مبادئ البرمجة غير المتزامنة","آليات اتخاذ القرارات لعمليات الإدخال/الإخراج","معالجة الأخطاء في عمليات الشبكة","تطوير حلول قابلة للتوسيع والمتينة","التكامل مع تكنولوجيا الذكاء الاصطناعي والتعلم الآلي"]},"keywords":{"en":["how to use learner skill","what is learner in AI","learner alternative for AI agents","learner vs other AI skills","learner setup guide for developers","installing learner for AI development","learner skill for async network code","reusable skills for AI agents","learner for problem-solving principles"],"zh":["Learner 技能","异步网络代码错误处理","可重用原则","AI 工具开发","Python 编程","非阻塞式网络编程"],"ja":["Learner スキル","非同期ネットワークコードのエラーハンドリング","再利用可能な原則","AIエージェント開発","Python プログラミング","ノンブロッキングなネットワークプログラミング"],"ko":["Learner 스킬","비동기 네트워크 코드 오류 처리","재사용 가능한 원칙","AI 툴 개발","Python 프로그래밍","논블로킹 네트워크 프로그래밍"],"es":["Agentes de IA","Skill Learner","principios reutilizables","heurísticas para errores","operaciones de I/O","código de red asíncrono","gestión de errores","programación asíncrona","entornos de cliente/servidor"],"fr":["Outils d''IA","Skill Learner","principes réutilisables","heuristiques pour erreurs","opérations de I/O","code de réseau asynchrone","gestion des erreurs","programmation asynchrone","environnements client/serveur"],"de":["KI-Tools","Learner-Skill","wiederverwendbare Prinzipien","Heuristiken für Fehler","I/O-Operationen","asynchroner Netzwerkcode","Fehlerbehandlung","asynchrone Programmierung","Client/Server-Umgebungen"],"pt":["Learner skill","desenvolvimento de IA","programação assíncrona","heurísticas de tomada de decisão","tratamento de erros em rede","soluções escaláveis","tecnologias de IA","machine learning"],"ru":["Навык Learner","разработка ИИ","асинхронное программирование","евристики принятия решений","обработка ошибок в сети","масштабируемые решения","технологии ИИ","машинное обучение"],"ar":["مهارة Learner","تطوير الذكاء الاصطناعي","برمجة غير متزامنة","آليات اتخاذ القرارات","معالجة الأخطاء في الشبكة","حلول قابلة للتوسيع","تكنولوجيا الذكاء الاصطناعي","التعلم الآلي"]}},"owner":"chanhee-kang","repo":"oh-my-gemini","repoPath":"chanhee-kang/oh-my-gemini","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.658Z","topics":[],"category":"community","skillMd":{"name":"learner","description":"Extract a learned skill from the current conversation","bodyPreview":"# Learner Skill\n\n## The Insight\n\nReusable skills are not code snippets to copy-paste, but **principles and decision-making heuristics** that teach Claude HOW TO THINK about a class of problems.\n\n**The difference:**\n- BAD (mimicking): \"When you see ConnectionResetError, add this try/except block\"\n- GOOD (reusable skill): \"In async network code, any I/O operation can fail independently due to client/server lifecycle mismatches. The principle: wrap each I/O operation separately, because failure bet","body":"# Learner Skill\n\n## The Insight\n\nReusable skills are not code snippets to copy-paste, but **principles and decision-making heuristics** that teach Claude HOW TO THINK about a class of problems.\n\n**The difference:**\n- BAD (mimicking): \"When you see ConnectionResetError, add this try/except block\"\n- GOOD (reusable skill): \"In async network code, any I/O operation can fail independently due to client/server lifecycle mismatches. The principle: wrap each I/O operation separately, because failure between operations is the common case, not the exception.\"\n\nA good skill changes how Claude APPROACHES problems, not just what code it produces.\n\n## Why This Matters\n\nBefore extracting a skill, ask yourself:\n- \"Could someone Google this in 5 minutes?\" → If yes, STOP. Don''t extract.\n- \"Is this specific to THIS codebase?\" → If no, STOP. Don''t extract.\n- \"Did this take real debugging effort to discover?\" → If no, STOP. Don''t extract.\n\nIf a potential skill fails any of these questions, it''s not worth saving.\n\n## Recognition Pattern\n\nUse /oh-my-gemini:learner ONLY after:\n- Solving a tricky bug that required deep investigation\n- Discovering a non-obvious workaround specific to this codebase\n- Finding a hidden gotcha that wastes time when forgotten\n- Uncovering undocumented behavior that affects this project\n\n## The Approach\n\n### Extraction Process\n\n**Step 1: Gather Required Information**\n\n- **Problem Statement**: The SPECIFIC error, symptom, or confusion that occurred\n  - Include actual error messages, file paths, line numbers\n  - Example: \"TypeError in src/hooks/session.ts:45 when sessionId is undefined after restart\"\n\n- **Solution**: The EXACT fix, not general advice\n  - Include code snippets, file paths, configuration changes\n  - Example: \"Add null check before accessing session.user, regenerate session on 401\"\n\n- **Triggers**: Keywords that would appear when hitting this problem again\n  - Use error message fragments, file names, symptom descriptions\n  - Example: [\"sessionId undefined\", \"session.ts TypeError\", \"401 session\"]\n\n- **Scope**: Almost always Project-level unless it''s a truly universal insight\n\n**Step 2: Quality Validation**\n\nThe system REJECTS skills that are:\n- Too generic (no file paths, line numbers, or specific error messages)\n- Easily Googleable (standard patterns, library usage)\n- Vague solutions (no code snippets or precise instructions)\n- Poor triggers (generic words that match everything)\n\n**Step 3: Save Location**\n\n- **User-level**: ~/.gemini-cli/skills/omc-learned/ - Rare. Only for truly portable insights.\n- **Project-level**: .omc/skills/ - Default. Version-controlled with repo.\n\n### What Makes a USEFUL Skill\n\n**CRITICAL**: Not every solution is worth saving. A good skill is:\n\n1. **Non-Googleable**: Something you couldn''t easily find via search\n   - BAD: \"How to read files in TypeScript\" ❌\n   - GOOD: \"This codebase uses custom path resolution in ESM that requires fileURLToPath + specific relative paths\" ✓\n\n2. **Context-Specific**: References actual files, error messages, or patterns from THIS codebase\n   - BAD: \"Use try/catch for error handling\" ❌\n   - GOOD: \"The aiohttp proxy in server.py:42 crashes on ClientDisconnectedError - wrap StreamResponse in try/except\" ✓\n\n3. **Actionable with Precision**: Tells you exactly WHAT to do and WHERE\n   - BAD: \"Handle edge cases\" ❌\n   - GOOD: \"When seeing ''Cannot find module'' in dist/, check tsconfig.json moduleResolution matches package.json type field\" ✓\n\n4. **Hard-Won**: Took significant debugging effort to discover\n   - BAD: Generic programming patterns ❌\n   - GOOD: \"Race condition in worker.ts - the Promise.all at line 89 needs await before the map callback returns\" ✓\n\n### Anti-Patterns (DO NOT EXTRACT)\n\n- Generic programming patterns (use documentation instead)\n- Refactoring techniques (these are universal)\n- Library usage examples (use library docs)\n- Type definitions or boilerplate\n- Anything a junior dev could Google in 5 minutes\n\n## Skill Format\n\nSkills are saved as markdown with this structure:\n\n### YAML Frontmatter\n\nStandard metadata fields:\n- id, name, description, source, triggers, quality\n\n### Body Structure (Required)\n\n```markdown\n# [Skill Name]\n\n## The Insight\nWhat is the underlying PRINCIPLE you discovered? Not the code, but the mental model.\nExample: \"Async I/O operations are independently failable. Client lifecycle != server lifecycle.\"\n\n## Why This Matters\nWhat goes wrong if you don''t know this? What symptom led you here?\nExample: \"Proxy server crashes on client disconnect, taking down other requests.\"\n\n## Recognition Pattern\nHow do you know when this skill applies? What are the signs?\nExample: \"Building any long-lived connection handler (proxy, websocket, SSE)\"\n\n## The Approach\nThe decision-making heuristic, not just code. How should Claude THINK about this?\nExample: \"For each I/O operation, ask: what if this fails right now? Handle it locally.\"\n\n## Example (Optional)\nIf code helps, show it - but as illustration of the principle, not copy-paste material.\n```\n\n**Key**: A skill is REUSABLE if Claude can apply it to NEW situations, not just identical ones.\n\n## Related Commands\n\n- /oh-my-gemini:note - Save quick notes that survive compaction (less formal than skills)\n- /oh-my-gemini:ralph - Start a development loop with learning capture\n"},"lastSynced":"2026-03-08T02:14:00.367Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents needing reusable principles and decision-making heuristics for complex problem-solving.","zh":"适用于需要可重用原则和决策启发式的复杂问题解决的高级 AI 代理。","ja":"再利用可能な原則と意思決定のヒューリスティックが必要な高度な AI エージェントに適しています。","ko":"재사용 가능한 원칙과 결정적启发법이 필요한 고급 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA Avanzados que necesitan principios y heurísticas de toma de decisiones reutilizables para la resolución de problemas complejos.","fr":"Parfait pour les Agents IA Avancés ayant besoin de principes et d''heuristiques de prise de décision réutilisables pour la résolution de problèmes complexes.","de":"Perfekt für fortschrittliche KI-Agents, die wiederverwendbare Prinzipien und Entscheidungsheuristiken für die Lösung komplexer Probleme benötigen.","pt":"Perfeito para Agentes de IA Avançados que precisam de princípios reutilizáveis e heurísticas de tomada de decisão para resolução de problemas complexos.","ru":"Идеально подходит для Продвинутых Агентов ИИ, которым необходимы многократно используемые принципы и эвристические методы принятия решений для решения сложных проблем.","ar":"مثالي لعميل الذكاء الاصطناعي المتقدم الذين يحتاجون إلى مبادئ قابلة لإعادة الاستخدام وقياسات تصمیمات لتحليل المشكلات المعقدة."},"recommendation":{"en":"Empowers agents to think critically about async network code using principles like wrapping each I/O operation separately to handle client/server lifecycle mismatches, leveraging try/except blocks for robust error handling in protocols like TCP/IP.","zh":"赋予代理能够批判性地思考异步网络代码，使用像为每个 I/O 操作包裹单独的处理客户端/服务器生命周期不匹配的原则，利用 try/except 块来处理像 TCP/IP 这样的协议的强健错误处理。","ja":"エージェントが、I/O 操作ごとに個別にラッピングしてクライアント/サーバーのライフサイクル不一致を処理するような原則を使用して、非同期ネットワークコードについて批判的に考えることができるようにします。さらに、try/except ブロックを使用して、TCP/IP のようなプロトコルでの強力なエラー処理を実現します。","ko":"에이전트가 비동기 네트워크 코드에 대해 비판적으로 생각할 수 있도록 하여, I/O操作 각각을 개별적으로 래핑하여 클라이언트/서버 라이프사이클 불일치를 처리하는 原則을 사용하고, try/except 블록을 사용하여 TCP/IP 와 같은 프로토콜의 강력한 에러 처리를 구현합니다.","es":"Habilita a los agentes a pensar críticamente sobre el código de red asíncrono utilizando principios como envolver cada operación de E/S por separado para manejar las discrepancias del ciclo de vida del cliente/servidor, aprovechando bloques try/except para un control de errores robusto en protocolos como TCP/IP.","fr":"Permet aux agents de réfléchir de manière critique au code réseau asynchrone en utilisant des principes tels que l''encapsulation de chaque opération d''E/S séparément pour gérer les discordances du cycle de vie client/serveur, en exploitant des blocs try/except pour une gestion robuste des erreurs dans des protocoles comme TCP/IP.","de":"Ermöglicht es Agenten, kritisch über asynchrone Netzwerkcodedenken zu denken, indem Prinzipien wie das separate Einwickeln jeder E/S-Operation zur Behandlung von Client-Server-Lebenszyklus-Übereinstimmungen verwendet werden, indem try/except-Blöcke für eine robuste Fehlerbehandlung in Protokollen wie TCP/IP genutzt werden.","pt":"Habilita os agentes a pensar criticamente sobre o código de rede assíncrono usando princípios como embrulhar cada operação de E/S separadamente para lidar com discrepâncias de ciclo de vida do cliente/servidor, aproveitando blocos try/except para tratamento de erros robusto em protocolos como TCP/IP.","ru":"Наделяет агентов способностью критически мыслить о коде асинхронной сети, используя принципы, такие как оборачивание каждой операции ввода/вывода отдельно для обработки несоответствий цикла жизни клиента/сервера, используя блоки try/except для устойчивого xử lý ошибок в протоколах, таких как TCP/IP.","ar":"تمكن الوكيل من التفكير النقدي حول شفرة الشبكة غير المتزامنة باستخدام مبادئ مثل تغليف كل عملية إدخال/إخراج بشكل منفصل لمعالجة اختلافات دورة حياة العميل/الخادم، واستخدام كتل try/except للتحكم في الأخطاء بشكل متين في بروتوكولات مثل TCP/IP."},"useCases":{"en":["Debugging ConnectionResetError in async network code","Implementing reusable error handling mechanisms for I/O operations","Developing decision-making heuristics for complex network protocols"],"zh":["调试异步网络代码中的 ConnectionResetError","为 I/O 操作实现可重用的错误处理机制","为复杂网络协议开发决策启发式"],"ja":["非同期ネットワークコードでの ConnectionResetError のデバッグ","I/O 操作用の再利用可能なエラー処理メカニズムの実装","複雑なネットワークプロトコル用の意思決定ヒューリスティックの開発"],"ko":["비동기 네트워크 코드의 ConnectionResetError 디버깅","I/O 연산을 위한 재사용 가능한 에러 처리 메커니즘 구현","복잡한 네트워크 프로토콜을 위한 결정적启发법 개발"],"es":["Depuración de ConnectionResetError en código de red asíncrono","Implementación de mecanismos de manejo de errores reutilizables para operaciones de E/S","Desarrollo de heurísticas de toma de decisiones para protocolos de red complejos"],"fr":["Débogage de ConnectionResetError dans le code réseau asynchrone","Mise en œuvre de mécanismes de gestion d''erreurs réutilisables pour les opérations d''E/S","Développement d''heuristiques de prise de décision pour les protocoles de réseau complexes"],"de":["Debuggen von ConnectionResetError in asynchronem Netzwerkcodedenken","Implementierung wiederverwendbarer Fehlerbehandlungsmechanismen für E/S-Operationen","Entwicklung von Entscheidungsheuristiken für komplexe Netzwerkprotokolle"],"pt":["Depuração do ConnectionResetError no código de rede assíncrono","Implementação de mecanismos de tratamento de erros reutilizáveis para operações de E/S","Desenvolvimento de heurísticas de tomada de decisão para protocolos de rede complexos"],"ru":["Отладка ConnectionResetError в коде асинхронной сети","Реализация многократно используемых механизмов обработки ошибок для операций ввода/вывода","Разработка эвристических методов принятия решений для сложных сетевых протоколов"],"ar":["تصحيح الخطأ ConnectionResetError في شفرة الشبكة غير المتزامنة","تنفيذ آليات التحكم في الأخطاء القابلة لإعادة الاستخدام للعمليات إدخال/إخراج","تطوير قياسات تصمیمات للبروتوكولات الشبكية المعقدة"]},"limitations":{"en":["Requires understanding of async network code principles","Limited to async network code applications"],"zh":["需要了解异步网络代码原则","仅限于异步网络代码应用"],"ja":["非同期ネットワークコードの原則の理解が必要","非同期ネットワークコードアプリケーションに限定される"],"ko":["비동기 네트워크 코드 원칙에 대한 이해가 필요","비동기 네트워크 코드 애플리케이션에만 제한"],"es":["Requiere comprensión de los principios del código de red asíncrono","Limitado a aplicaciones de código de red asíncrono"],"fr":["Nécessite une compréhension des principes du code réseau asynchrone","Limité aux applications de code réseau asynchrone"],"de":["Erfordert das Verständnis der Prinzipien des asynchronen Netzwerkcodedenken","Begrenzt auf asynchrone Netzwerkcodedenken-Anwendungen"],"pt":["Exige compreensão dos princípios do código de rede assíncrono","Limitado a aplicações de código de rede assíncrono"],"ru":["Требует понимания принципов кода асинхронной сети","Ограничен применением кода асинхронной сети"],"ar":["يتطلب فهم مبادئ شفرة الشبكة غير المتزامنة","محدود للتطبيقات شفرة الشبكة غير المتزامنة"]},"version":4},"contentHash":"86e1f983d05459ae518657f517e15301ed509d9e5e310ec0fba82e4335a7ba66","qualityScore":42}');
