INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chanhee-kang/oh-my-gemini/learner', 'learner', 'chanhee-kang', 'oh-my-gemini', 'community', 'learner chanhee-kang oh-my-gemini community The Learner skill enables developers to create reusable principles and decision-making heuristics for AI agents, teaching them how to think about complex problems. This skill benefits developers working with async network code. Learner 技能提供异步网络代码错误处理和可重用原则，帮助开发者创建更强大的 AI 工具 Learner スキルは、AIエージェントの開発を強化するための再利用可能な原則と、非同期ネットワークコードのエラーハンドリングを提供します Learner 스킬은 비동기 네트워크 코드 오류 처리와 재사용 가능한 원칙을 제공하여 개발자가 더 강력한 AI 툴을 개발할 수 있도록 합니다 El Skill Learner enseña a Claude cómo pensar en una clase de problemas mediante principios y heurísticas reutilizables. Mejora la toma de decisiones en tus Agentes de IA Le Skill Learner enseigne à Claude comment réfléchir à une classe de problèmes grâce à des principes et des heuristiques réutilisables. Améliorez la prise de décision dans vos Outils d''IA Das Learner-Skill lehrt Claude, wie man an eine Klasse von Problemen denkt, indem man Prinzipien und Heuristiken wiederholt. Verbessern Sie die Entscheidungsfindung in Ihren KI-Tools O Learner é um skill que ensina princípios e heurísticas de tomada de decisão para desenvolver soluções de IA robustas. Learner - это навык, который учит принципам и евристикам принятия решений для разработки устойчивых решений ИИ. Learner هو مهارة تعليمية تدرس مبادئ وآليات اتخاذ القرارات لتطوير حلول ذكية قوية how to use learner skill what is learner in AI learner alternative for AI agents learner vs other AI skills learner setup guide for developers installing learner for AI development learner skill for async network code reusable skills for AI agents learner for problem-solving principles Learner 技能 异步网络代码错误处理 可重用原则 AI 工具开发 Python 编程 非阻塞式网络编程 Teaches Claude problem-solving principles for async network code Enables wrapping of I/O operations to handle independent failures Applies decision-making heuristics for client/server lifecycle mismatches Develops reusable skills for AI agents, beyond code snippets Handles ConnectionResetError and other I/O operation failures Improves AI agent resilience in distributed systems Learner is a skill that teaches AI agents reusable principles and decision-making heuristics for solving complex problems, focusing on async network code and I/O operation failures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Darkbluelr/dev-playbooks-cn/devbooks-docs-consistency', 'community', 'Darkbluelr', 'dev-playbooks-cn', 'Darkbluelr/dev-playbooks-cn', 'devbooks-docs-consistency', 0, 0, 42, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:01.029Z', '97ebb49548aeaaf0a3f4ec7ca901bc86ea230cbdc24494150fd86534596a23f9', '{"id":"Darkbluelr/dev-playbooks-cn/devbooks-docs-consistency","name":"devbooks-docs-consistency","description":{"en":"devbooks-docs-consistency enables reliable software development by ensuring documentation consistency. It benefits developers working on large AI projects by providing a single source of truth (SSOT) and quality gates.","zh":"DevBooks文档一致性技能帮助您在不可靠的AI之上构建可靠的软件，通过SSOT、Knife切片、质量闸门与证据闭环","ja":"DevBooks ドキュメント一致性スキルは、信頼性のないAIの上に信頼性の高いソフトウェアを構築するのに役立ち、SSOT、Knife切片、品質ゲート、証拠クローズループを通じて","ko":"DevBooks 문서 일관성 스킬은 불안정한 AI 위에 안정적인 소프트웨어를 구축하는 데 도움이 됩니다. SSOT, Knife 切片, 품질 게이트 및 증거 폐쇄 ループ를 통해","es":"DevBooks es una herramienta para mantener la consistencia de documentos con SSOT y Knife. Configura DevBooks para mejorar la calidad de tus proyectos","fr":"DevBooks est un outil pour maintenir la cohérence des documents avec SSOT et Knife. Configurez DevBooks pour améliorer la qualité de vos projets","de":"DevBooks ist ein Tool, um die Konsistenz von Dokumenten mit SSOT und Knife zu gewährleisten. Konfigurieren Sie DevBooks, um die Qualität Ihrer Projekte zu verbessern","pt":"devbooks-docs-consistency é uma habilidade que ajuda a manter a consistência dos documentos em projetos de IA. Ela utiliza SSOT, Knife e qualidade de gate para garantir a precisão e a confiabilidade dos documentos","ru":"devbooks-docs-consistency - это навык, который помогает поддерживать согласованность документов в проектах ИИ. Он использует SSOT, Knife и контроль качества для обеспечения точности и надежности документов","ar":"devbooks-docs-consistency هو مهارة تساعد على الحفاظ على الاتساق في وثائق مشاريع الذكاء الاصطناعي. انها تستخدم SSOT و Knife و جودة البوابة لضمان الدقة و الموثوقية الوثائق"},"seo":{"title":{"en":"devbooks-docs-consistency: Setup Guide for AI Agents","zh":"DevBooks 文档一致性设置指南","ja":"AIエージェントのためのDevBooks ドキュメント一致性ガイド","ko":"DevBooks 문서 일관성 설정 가이드","es":"Guía de Configuración de DevBooks para Consistencia de Do...","fr":"Guide de Configuration de DevBooks pour la Cohérence des ...","de":"Konfigurationsleitfaden für DevBooks-Dokumenten Konsistenz","pt":"Guia de Configuração devbooks-docs-consistency para Desen...","ru":"Настройка devbooks-docs-consistency для ИИ Агентов и Разр...","ar":"دليل إعداد devbooks-docs-consistency للوكلاء الذكاء الاصط..."},"description":{"en":"Unlock consistent documentation with devbooks-docs-consistency. Discover how to configure and utilize this AI agent skill for reliable software development.","zh":"了解DevBooks文档一致性技能的设置和使用方法，实现可靠的软件构建","ja":"AIエージェントのためのDevBooks ドキュメント一致性を設定して、信頼性の高いソフトウェアを構築する","ko":"DevBooks 문서 일관성 설정과 사용 방법을 알아보세요. 안정적인 소프트웨어 구축을 실현합니다.","es":"Aprende a configurar DevBooks para mantener la consistencia de tus documentos con SSOT, Knife y calidad de código","fr":"Découvrez comment configurer DevBooks pour maintenir la cohérence de vos documents avec SSOT, Knife et qualité de code","de":"Erfahren Sie, wie Sie DevBooks konfigurieren, um die Konsistenz Ihrer Dokumente mit SSOT, Knife und Code-Qualität zu gewährleisten","pt":"Aprenda a configurar devbooks-docs-consistency para melhorar a consistência dos documentos em projetos de IA com SSOT, Knife e qualidade de gate","ru":"Узнайте, как настроить devbooks-docs-consistency для улучшения согласованности документов в проектах ИИ с помощью SSOT, Knife и контроля качества","ar":"تعلم كيفية تنظیم devbooks-docs-consistency لتحسين الاتساق في وثائق مشاريع الذكاء الاصطناعي باستخدام SSOT و Knife و جودة البوابة"},"definition":{"en":"devbooks-docs-consistency is a skill that ensures documentation consistency in AI-powered software development, utilizing techniques like SSOT and quality gates.","zh":"DevBooks文档一致性是指通过单源真实、Knife切片、质量闸门与证据闭环等手段，确保软件文档的一致性和可靠性","ja":"DevBooks ドキュメント一致性とは、単一の情報源、Knife切片、品質ゲート、証拠クローズループなどの手段を通じて、ソフトウェア ドキュメントの一貫性と信頼性を確保すること","ko":"DevBooks 문서 일관성은 단일 정보원, Knife 切片, 품질 게이트 및 증거 폐쇄 ループ 등의 手段을 통해 소프트웨어 문서의 일관성과 안정성을 보장하는 것입니다","es":"DevBooks es una herramienta de consistencia de documentos que utiliza SSOT y Knife para mejorar la calidad del código","fr":"DevBooks est un outil de cohérence de documents qui utilise SSOT et Knife pour améliorer la qualité du code","de":"DevBooks ist ein Tool für die Dokumenten Konsistenz, das SSOT und Knife verwendet, um die Code-Qualität zu verbessern","pt":"devbooks-docs-consistency é uma habilidade que garante a consistência dos documentos em projetos de IA","ru":"devbooks-docs-consistency - это навык, который обеспечивает согласованность документов в проектах ИИ","ar":"devbooks-docs-consistency هو مهارة تضمن الاتساق في وثائق مشاريع الذكاء الاصطناعي"},"features":{"en":["Utilizes Single Source of Truth (SSOT) for consistent documentation","Employs Knife cuts and quality gates for reliable software development","Supports configuration discovery via .devbooks/config.yaml and dev-playbooks/project.md","Provides evidence-based outputs and execution records","Integrates with external systems and tools for expanded functionality"],"zh":["单源真实（SSOT）","Knife切片","质量闸门","证据闭环","代码检索（code-search）","引用追踪（reference-tracking）"],"ja":["単一の情報源（SSOT）","Knife切片","品質ゲート","証拠クローズループ","コード検索（code-search）","参照追跡（reference-tracking）"],"ko":["단일 정보원（SSOT）","Knife 切片","품질 게이트","증거 폐쇄 ループ","코드 검색（code-search）","참조 추적（reference-tracking）"],"es":["Utiliza SSOT (Single Source of Truth) para mantener la consistencia de los documentos","Integración con Knife para analizar la calidad del código","Soporte para configuración de proyectos con dev-playbooks y project.md","Compatibilidad con protocolos de configuración como .devbooks/config.yaml","Análisis de impacto y referencia para mejorar la calidad del código","Soporte para búsqueda de código y seguimiento de referencias"],"fr":["Utilise SSOT (Single Source of Truth) pour maintenir la cohérence des documents","Intégration avec Knife pour analyser la qualité du code","Prise en charge de la configuration de projets avec dev-playbooks et project.md","Compatibilité avec les protocoles de configuration tels que .devbooks/config.yaml","Analyse d''impact et de référence pour améliorer la qualité du code","Prise en charge de la recherche de code et du suivi des références"],"de":["Verwenden von SSOT (Single Source of Truth), um die Konsistenz von Dokumenten zu gewährleisten","Integration mit Knife, um die Code-Qualität zu analysieren","Unterstützung für die Konfiguration von Projekten mit dev-playbooks und project.md","Kompatibilität mit Konfigurationsprotokollen wie .devbooks/config.yaml","Auswirkungs- und Referenzanalyse, um die Code-Qualität zu verbessern","Unterstützung für Code-Suche und Referenz-Verfolgung"],"pt":["Utiliza SSOT (Single Source of Truth) para garantir a precisão dos documentos","Implementa Knife para automatizar a verificação de consistência","Fornece qualidade de gate para garantir a confiabilidade dos documentos","Suporta configuração personalizada com .devbooks/config.yaml","Permite integração com Dev-Playbooks e project.md"],"ru":["Использует SSOT (Single Source of Truth) для обеспечения точности документов","Реализует Knife для автоматизации проверки согласованности","Предоставляет контроль качества для обеспечения надежности документов","Поддерживает настраиваемую конфигурацию с .devbooks/config.yaml","Позволяет интеграцию с Dev-Playbooks и project.md"],"ar":["تستخدم SSOT (مصدر وحيد للtruth) لضمان الدقة من الوثائق","تطبيق Knife لأتمتة فحص الاتساق","توفر جودة البوابة لضمان موثوقية الوثائق","تدعم التكوين المخصص مع .devbooks/config.yaml","السماح للتكامل مع Dev-Playbooks و project.md"]},"keywords":{"en":["how to use devbooks-docs-consistency","devbooks-docs-consistency setup guide","what is devbooks-docs-consistency","devbooks-docs-consistency alternative","devbooks-docs-consistency vs knife","devbooks-docs-consistency install","devbooks-docs-consistency configuration","AI agent skills for software development","documentation consistency in AI development"],"zh":["DevBooks","文档一致性","AIエージェント","软件构建","SSOT","Knife切片","代码检索","引用追踪"],"ja":["DevBooks","ドキュメント一致性","AIエージェント","ソフトウェア構築","SSOT","Knife切片","コード検索","参照追跡"],"ko":["DevBooks","문서 일관성","AI 에이전트","소프트웨어 구축","SSOT","Knife 切片","코드 검색","참조 추적"],"es":["herramientas de AI","DevBooks","consistencia de documentos","SSOT","Knife","calidad de código","configuración de proyectos","dev-playbooks","project.md","búsqueda de código"],"fr":["outils d''IA","DevBooks","cohérence des documents","SSOT","Knife","qualité de code","configuration de projets","dev-playbooks","project.md","recherche de code"],"de":["AI-Tools","DevBooks","Dokumenten Konsistenz","SSOT","Knife","Code-Qualität","Projekt-Konfiguration","dev-playbooks","project.md","Code-Suche"],"pt":["devbooks-docs-consistency","IA","Documentação","SSOT","Knife","Qualidade de gate","Desenvolvedores","Projetos de IA"],"ru":["devbooks-docs-consistency","ИИ","Документация","SSOT","Knife","Контроль качества","Разработчики","Проекты ИИ"],"ar":["devbooks-docs-consistency","الذكاء الاصطناعي","توثيق","SSOT","Knife","جودة البوابة","المطورون","مشاريع الذكاء الاصطناعي"]}},"owner":"Darkbluelr","repo":"dev-playbooks-cn","repoPath":"Darkbluelr/dev-playbooks-cn","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"devbooks-docs-consistency","description":"devbooks-docs-consistency：检查并维护项目文档与代码的一致性，支持增量扫描、自定义规则与完备性检查。可在变更包内按需运行或全局检查。旧名称 devbooks-docs-sync 保留为别名并输出弃用提示。","bodyPreview":"# DevBooks：文档一致性（Docs Consistency）\n\n## 渐进披露\n### 基础层（必读）\n目标：明确本 Skill 的核心产出与使用范围。\n输入：用户目标、现有文档、变更包上下文或项目路径。\n输出：可执行产物、下一步指引或记录路径。\n边界：不替代其他角色职责，不触碰 tests/。\n证据：引用产出物路径或执行记录。\n\n### 进阶层（可选）\n适用：需要细化策略、边界或风险提示时补充。\n\n### 扩展层（可选）\n适用：需要与外部系统或可选工具协同时补充。\n\n## 推荐 MCP 能力类型\n- 代码检索（code-search）\n- 引用追踪（reference-tracking）\n- 影响分析（impact-analysis）\n\n## 前置：配置发现（协议无关）\n\n执行前**必须**按以下顺序查找配置（找到后停止）：\n1. `.devbooks/config.yaml`（如存在）→ 解析并使用其中的映射\n2. `dev-playbooks/project.md`（如存在）→ Dev-Playbooks 协议，使用默认映射\n3. `project.md`（如存在）→ t","body":"# DevBooks：文档一致性（Docs Consistency）\n\n## 渐进披露\n### 基础层（必读）\n目标：明确本 Skill 的核心产出与使用范围。\n输入：用户目标、现有文档、变更包上下文或项目路径。\n输出：可执行产物、下一步指引或记录路径。\n边界：不替代其他角色职责，不触碰 tests/。\n证据：引用产出物路径或执行记录。\n\n### 进阶层（可选）\n适用：需要细化策略、边界或风险提示时补充。\n\n### 扩展层（可选）\n适用：需要与外部系统或可选工具协同时补充。\n\n## 推荐 MCP 能力类型\n- 代码检索（code-search）\n- 引用追踪（reference-tracking）\n- 影响分析（impact-analysis）\n\n## 前置：配置发现（协议无关）\n\n执行前**必须**按以下顺序查找配置（找到后停止）：\n1. `.devbooks/config.yaml`（如存在）→ 解析并使用其中的映射\n2. `dev-playbooks/project.md`（如存在）→ Dev-Playbooks 协议，使用默认映射\n3. `project.md`（如存在）→ template 协议，使用默认映射\n4. 若仍无法确定 → **停止并询问用户**\n\n---\n\n## 兼容与弃用\n\n- 旧名称：`devbooks-docs-sync`\n- 当前名称：`devbooks-docs-consistency`\n- 行为：旧名称作为别名继续可用，并输出弃用提示。\n- 运行提示：别名通过软链接指向新目录，可执行 `scripts/alias.sh` 输出提示。\n\n弃用提示示例：\n\n```\ndevbooks-docs-sync 已弃用，请使用 devbooks-docs-consistency。\n```\n\n---\n\n## 角色定义\n\n**docs-consistency** 是 DevBooks Apply 阶段的文档一致性检查角色，负责识别文档与代码之间的偏差并生成报告，不直接修改代码。\n\n### 文档分类\n\n| 文档类型 | 目标受众 | 是否由本 Skill 检查 | 示例 |\n|----------|----------|:-------------------:|------|\n| **活体文档** | 最终用户 | ✅ | README.md, docs/*.md, API.md |\n| **历史文档** | 最终用户 | ⚠️（只做最低限度检查） | CHANGELOG.md |\n| **概念性文档** | 设计/架构 | ✅（结构性检查） | architecture/*.md |\n\n分类规则可配置，默认规则见 `references/doc-classification.yaml`。\n\n---\n\n## 运行模式\n\n### 模式一：增量扫描（Change-Scoped）\n\n**触发条件**：在变更包上下文中运行。\n\n**行为**：\n1. 读取变更范围\n2. 仅扫描变更文件\n3. 记录 token 消耗与扫描时间\n4. 输出检查报告\n\n### 模式二：全量扫描（Global Check）\n\n**触发条件**：用户显式请求全局检查（如 `devbooks-docs-consistency --global`）。\n\n**行为**：\n1. 扫描所有用户文档\n2. 生成差异报告\n3. 输出改进建议\n\n### 模式三：检查模式（Check Only）\n\n**触发条件**：用户使用 `--check` 参数。\n\n**行为**：只检查、不修改，输出报告。\n\n---\n\n## 命令示例\n\n```\n# 规则引擎：持续规则\nbash scripts/rules-engine.sh --rules references/docs-rules-schema.yaml --input README.md\n\n# 规则引擎：一次性任务\nbash scripts/rules-engine.sh --once \"remove:@augment\" --input README.md\n\n# 文档分类\nbash scripts/doc-classifier.sh README.md\n\n# 完备性检查\nbash scripts/completeness-checker.sh --input README.md --config references/completeness-dimensions.yaml --output evidence/completeness-report.md\n\n# 作为 G6 Scope Evidence 的机读报告（固定落点）\nskills/devbooks-delivery-workflow/scripts/docs-consistency-check.sh <change-id> \\\n  --project-root . --change-root dev-playbooks/changes --truth-root dev-playbooks/specs\n```\n\n---\n\n## 完备性检查\n\n对活体文档执行完备性检查，默认覆盖：环境依赖、安全权限、故障排查、配置说明、API 文档。\n\n- 维度配置：`references/completeness-dimensions.yaml`\n- 报告输出：`<change-root>/<change-id>/evidence/completeness-report.md`\n- 方法论参考：[完备性思维框架](../_shared/references/完备性思维框架.md)\n\n---\n\n## 风格偏好\n\n风格偏好读取优先级：命令行参数 > 配置文件 > 默认值。\n\n- 文档维护元数据：`dev-playbooks/specs/_meta/docs-maintenance.md`\n\n---\n\n## 输出与报告\n\n默认输出以下报告（变更包上下文）：\n\n- `evidence/gates/docs-consistency.report.json`（机读；供 G6 / archive-decider 消费）\n- `evidence/completeness-report.md`\n- `evidence/token-usage.log`\n- `evidence/scan-performance.log`\n\n---\n\n## 与工作流的集成\n\n在归档阶段由 `devbooks-archiver` 触发，在存量初始化时由 `devbooks-brownfield-bootstrap` 生成文档维护元数据。\n\n当 G6 触发 Scope Evidence Bundle 且判定“docs 一致性为必需项”时（例如 deliverables 涉及 `README.md/docs/**/templates/**`，或存在 `weak_link+docs` 的 `severity=must` 义务）：\n- 必须生成 `evidence/gates/docs-consistency.report.json` 且 `status=pass`\n- 缺失或 `status!=pass` 将被 `archive-decider.sh` 判定为 fail，从而阻断归档\n\n---\n\n## 元数据\n\n| 字段 | 值 |\n|------|-----|\n| Skill 名称 | devbooks-docs-consistency |\n| 阶段 | Apply（实现后、归档前） |\n| 产物 | 文档一致性检查报告 |\n| 约束 | 只检查、不修改代码 |\n\n---\n\n*此 Skill 文档遵循 devbooks-* 规范。*\n"},"lastSynced":"2026-03-08T02:14:01.029Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Maintenance Agents requiring advanced documentation consistency and single source of truth (SSOT) management.","zh":"适用于需要高级文档一致性和单一真实源（SSOT）管理的代码维护代理。","ja":"コードメンテナンスエージェントが高度なドキュメントの一貫性と単一の真実源（SSOT）管理を必要とする場合に適しています。","ko":"고급 문서 일관성 및 단일 소스 오브 트루스(SSOT) 관리가 필요한 코드 유지 보수 에이전트에 적합합니다.","es":"Ideal para Agentes de Mantenimiento de Código que requieren una consistencia avanzada de documentación y gestión de una sola fuente de verdad (SSOT).","fr":"Idéal pour les Agents de Maintenance de Code nécessitant une cohérence de documentation avancée et une gestion d''une seule source de vérité (SSOT).","de":"Ideal für Code-Wartungsagenten, die eine erweiterte Dokumentationskonsistenz und eine Verwaltung einer einzigen Wahrheitsquelle (SSOT) erfordern.","pt":"Ideal para Agentes de Manutenção de Código que exigem documentação avançada e consistência e gestão de única fonte de verdade (SSOT).","ru":"Идеально подходит для агентов по обслуживанию кода, требующих расширенной документации и согласованности и управления единой истиной (SSOT).","ar":"مثالي للوكلاء الذين يحتاجون إلى صيانة الشفرة وتوافق الوثائق المتقدمة وإدارة مصدر الحقيقة الواحد (SSOT)."},"recommendation":{"en":"Empowers agents to ensure reliable software development through documentation consistency, utilizing protocols like Dev-Playbooks and file formats such as .yaml and .md, while providing quality gates and a single source of truth (SSOT). It integrates with capabilities like code-search, reference-tracking, and impact-analysis for comprehensive content analysis.","zh":"赋予代理确保可靠软件开发的能力，通过利用Dev-Playbooks和.yaml、.md等文件格式等协议来实现文档的一致性，并提供质量门槛和单一真实源（SSOT）。它与代码搜索、引用跟踪、影响分析等功能集成，进行全面内容分析。","ja":"Dev-Playbooksや.yaml、.mdなどのファイル形式などのプロトコルを利用してドキュメントの一貫性を確保し、品質ゲートと単一の真実源（SSOT）を提供することで、信頼性の高いソフトウェア開発を可能にします。コード検索、リファレンス追跡、インパクト分析などの機能と統合して、包括的なコンテンツ分析を行います。","ko":"Dev-Playbooks 및 .yaml, .md와 같은 파일 형식과 같은 프로토콜을 사용하여 문서 일관성을 보장하고 품질 게이트 및 단일 소스 오브 트루스(SSOT)를 제공하여 안정적인 소프트웨어 개발을 가능하게 합니다. 코드 검색, 참조 추적, 영향 분석과 같은 기능과 통합하여 포괄적인 내용 분석을 수행합니다.","es":"Habilita a los agentes para garantizar un desarrollo de software confiable a través de la consistencia de la documentación, utilizando protocolos como Dev-Playbooks y formatos de archivo como .yaml y .md, mientras proporciona puertas de calidad y una sola fuente de verdad (SSOT). Se integra con capacidades como code-search, reference-tracking e impact-analysis para un análisis de contenido integral.","fr":"Permet aux agents de garantir un développement de logiciels fiable grâce à la cohérence de la documentation, en utilisant des protocoles tels que Dev-Playbooks et des formats de fichiers tels que .yaml et .md, tout en fournissant des portes de qualité et une seule source de vérité (SSOT). Il s''intègre avec des fonctionnalités comme code-search, reference-tracking et impact-analysis pour une analyse de contenu complète.","de":"Ermächtigt die Agenten, eine zuverlässige Softwareentwicklung durch Dokumentationskonsistenz sicherzustellen, indem sie Protokolle wie Dev-Playbooks und Dateiformate wie .yaml und .md verwenden, während sie Qualitätsprüfungen und eine einzige Wahrheitsquelle (SSOT) bereitstellen. Es integriert sich mit Fähigkeiten wie Code-Suche, Referenznachverfolgung und Auswirkungsanalyse für eine umfassende Inhaltsanalyse.","pt":"Habilita os agentes a garantir o desenvolvimento de software confiável por meio da consistência da documentação, utilizando protocolos como Dev-Playbooks e formatos de arquivo como .yaml e .md, enquanto fornece portões de qualidade e uma única fonte de verdade (SSOT). Ele se integra a capacidades como code-search, reference-tracking e impact-analysis para análise de conteúdo abrangente.","ru":"Наделяет агентов возможностью обеспечить надежное развитие программного обеспечения посредством согласованности документации, используя протоколы типа Dev-Playbooks и форматы файлов типа .yaml и .md, а также предоставляя ворота качества и единую истину (SSOT). Он интегрируется с возможностями типа code-search, reference-tracking и impact-analysis для всестороннего анализа содержания.","ar":"تمكين الوكلاء من ضمان تطوير برامج موثوقة من خلال توافق الوثائق، باستخدام بروتوكولات مثل Dev-Playbooks وأشكال الملفات مثل .yaml و .md، مع توفير بوابات الجودة ومصدر الحقيقة الواحد (SSOT). إنه يندمج مع القدرات مثل code-search و reference-tracking و impact-analysis لعرض تحليل المحتوى الشامل."},"useCases":{"en":["Automating documentation checks for large AI projects","Generating consistent documentation across multiple repositories","Validating documentation consistency before project deployments"],"zh":["大型AI项目的文档检查自动化","跨多个仓库生成一致的文档","项目部署前验证文档一致性"],"ja":["大規模なAIプロジェクトのドキュメントチェックの自動化","複数のリポジトリで一貫性のあるドキュメントを生成する","プロジェクトのデプロイ前にドキュメントの一貫性を検証する"],"ko":["대규모 AI 프로젝트의 문서 점검 자동화","여러 저장소에서 일관된 문서 생성","프로젝트 배포 전 문서 일관성 검증"],"es":["Automatización de controles de documentación para grandes proyectos de IA","Generación de documentación coherente en varios repositorios","Validación de la consistencia de la documentación antes de las implementaciones de proyectos"],"fr":["Automatisation des contrôles de documentation pour les grands projets d''IA","Génération de documentation cohérente dans plusieurs référentiels","Validation de la cohérence de la documentation avant les déploiements de projets"],"de":["Automatisierung von Dokumentationsprüfungen für große KI-Projekte","Erzeugung konsistenter Dokumentation in mehreren Repositorys","Validierung der Dokumentationskonsistenz vor der Projektbereitstellung"],"pt":["Automatizar verificações de documentação para grandes projetos de IA","Gerar documentação consistente em vários repositórios","Validar a consistência da documentação antes do deploy do projeto"],"ru":["Автоматизировать проверки документации для крупных проектов ИИ","Генерировать согласованную документацию в нескольких репозиториях","Проверять согласованность документации перед развертыванием проекта"],"ar":["توفير التأكد التلقائي من توافق الوثائق للمشاريع الكبيرة للذكاء الاصطناعي","إنتاج توافق الوثائق عبر العديد من المستودعات","التحقق من صحة توافق الوثائق قبل نشر المشروع"]},"limitations":{"en":["Requires specific configuration files (.devbooks/config.yaml, dev-playbooks/project.md, or project.md)","Does not replace other role responsibilities or interact with tests/","Dependent on the discovery of configuration files in a specific order"],"zh":["需要特定的配置文件（.devbooks/config.yaml、dev-playbooks/project.md或project.md）","不替代其他角色责任或与测试/交互","依赖于特定顺序的配置文件发现"],"ja":["特定の設定ファイル（.devbooks/config.yaml、dev-playbooks/project.mdまたはproject.md）が必要","他のロールの責任やテストとのやり取りを代替しない","特定の順序で設定ファイルが発見されることを前提とする"],"ko":["특정 구성 파일(.devbooks/config.yaml, dev-playbooks/project.md 또는 project.md) 필요","다른 역할의 책임 또는 테스트와의 상호 작용을 대체하지 않음","특정 순서로 구성 파일이 발견되는 것을 전제로 함"],"es":["Requiere archivos de configuración específicos (.devbooks/config.yaml, dev-playbooks/project.md o project.md)","No reemplaza otras responsabilidades de roles ni interactúa con pruebas/","Dependiente del descubrimiento de archivos de configuración en un orden específico"],"fr":["Nécessite des fichiers de configuration spécifiques (.devbooks/config.yaml, dev-playbooks/project.md ou project.md)","Ne remplace pas d''autres responsabilités de rôles ni n''interagit avec des tests/","Dépend de la découverte de fichiers de configuration dans un ordre spécifique"],"de":["Erfordert spezifische Konfigurationsdateien (.devbooks/config.yaml, dev-playbooks/project.md oder project.md)","Ersetzt keine anderen Rollenverantwortungen oder interagiert mit Tests/","Abhängig von der Entdeckung von Konfigurationsdateien in einer bestimmten Reihenfolge"],"pt":["Exige arquivos de configuração específicos (.devbooks/config.yaml, dev-playbooks/project.md, ou project.md)","Não substitui outras responsabilidades de funções ou interage com testes/","Depende da descoberta de arquivos de configuração em uma ordem específica"],"ru":["Требует конкретных файлов конфигурации (.devbooks/config.yaml, dev-playbooks/project.md или project.md)","Не заменяет другие обязанности ролей или взаимодействует с тестами/","Зависит от обнаружения файлов конфигурации в определенном порядке"],"ar":["يتطلب ملفات تكوين محددة (.devbooks/config.yaml، dev-playbooks/project.md، أو project.md)","لا ي换ل مسؤوليات الأدوار الأخرى أو التفاعل مع الاختبارات /","يعتمد على اكتشاف ملفات التكوين في ترتيب معين"]},"version":4},"contentHash":"97ebb49548aeaaf0a3f4ec7ca901bc86ea230cbdc24494150fd86534596a23f9","qualityScore":42}');
DELETE FROM skills_fts WHERE id = 'Darkbluelr/dev-playbooks-cn/devbooks-docs-consistency';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Darkbluelr/dev-playbooks-cn/devbooks-docs-consistency', 'devbooks-docs-consistency', 'Darkbluelr', 'dev-playbooks-cn', 'community', 'devbooks-docs-consistency Darkbluelr dev-playbooks-cn community devbooks-docs-consistency enables reliable software development by ensuring documentation consistency. It benefits developers working on large AI projects by providing a single source of truth (SSOT) and quality gates. DevBooks文档一致性技能帮助您在不可靠的AI之上构建可靠的软件，通过SSOT、Knife切片、质量闸门与证据闭环 DevBooks ドキュメント一致性スキルは、信頼性のないAIの上に信頼性の高いソフトウェアを構築するのに役立ち、SSOT、Knife切片、品質ゲート、証拠クローズループを通じて DevBooks 문서 일관성 스킬은 불안정한 AI 위에 안정적인 소프트웨어를 구축하는 데 도움이 됩니다. SSOT, Knife 切片, 품질 게이트 및 증거 폐쇄 ループ를 통해 DevBooks es una herramienta para mantener la consistencia de documentos con SSOT y Knife. Configura DevBooks para mejorar la calidad de tus proyectos DevBooks est un outil pour maintenir la cohérence des documents avec SSOT et Knife. Configurez DevBooks pour améliorer la qualité de vos projets DevBooks ist ein Tool, um die Konsistenz von Dokumenten mit SSOT und Knife zu gewährleisten. Konfigurieren Sie DevBooks, um die Qualität Ihrer Projekte zu verbessern devbooks-docs-consistency é uma habilidade que ajuda a manter a consistência dos documentos em projetos de IA. Ela utiliza SSOT, Knife e qualidade de gate para garantir a precisão e a confiabilidade dos documentos devbooks-docs-consistency - это навык, который помогает поддерживать согласованность документов в проектах ИИ. Он использует SSOT, Knife и контроль качества для обеспечения точности и надежности документов devbooks-docs-consistency هو مهارة تساعد على الحفاظ على الاتساق في وثائق مشاريع الذكاء الاصطناعي. انها تستخدم SSOT و Knife و جودة البوابة لضمان الدقة و الموثوقية الوثائق how to use devbooks-docs-consistency devbooks-docs-consistency setup guide what is devbooks-docs-consistency devbooks-docs-consistency alternative devbooks-docs-consistency vs knife devbooks-docs-consistency install devbooks-docs-consistency configuration AI agent skills for software development documentation consistency in AI development DevBooks 文档一致性 AIエージェント 软件构建 SSOT Knife切片 代码检索 引用追踪 Utilizes Single Source of Truth (SSOT) for consistent documentation Employs Knife cuts and quality gates for reliable software development Supports configuration discovery via .devbooks/config.yaml and dev-playbooks/project.md Provides evidence-based outputs and execution records Integrates with external systems and tools for expanded functionality devbooks-docs-consistency is a skill that ensures documentation consistency in AI-powered software development, utilizing techniques like SSOT and quality gates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('proficientlyjobs/proficiently-claude-skills/setup', 'community', 'proficientlyjobs', 'proficiently-claude-skills', 'proficientlyjobs/proficiently-claude-skills', 'setup', 0, 0, 42, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:01.121Z', '2655ce941886521d0892404a2e9d32924e871f34ab76a5ea0a18ea068da80122', '{"id":"proficientlyjobs/proficiently-claude-skills/setup","name":"setup","description":{"en":"The setup skill ensures all data is in place before using other skills, benefiting developers and job seekers. It provides one-time onboarding for AI-powered job search and resume tailoring.","zh":"Setup 技能为您的数据提供了一次性的初始化，确保所有数据就绪后再使用其他技能","ja":"Setup スキルは、他のスキルを使用する前に、すべてのデータが整ったことを確認するためのワンタイムオンボーディングです","ko":"Setup 기능은 다른 기능을 사용하기 전에 모든 데이터가 준비되었는지 확인하는 단 한 번의 초기화 과정입니다","es":"El skill de configuración de Claude Code permite una integración fluida para la búsqueda de trabajo y la creación de currículums","fr":"Le skill de configuration de Claude Code permet une intégration fluide pour la recherche d''emploi et la création de CV","de":"Das Setup-Skill von Claude Code ermöglicht eine nahtlose Integration für die Stellensuche und die Erstellung von Lebensläufen","pt":"O setup é uma habilidade que garante que todos os dados estejam no lugar antes de usar outras habilidades.","ru":"Настройка - это навык, который обеспечивает правильное расположение всех данных перед использованием других навыков.","ar":"الإعداد هو مهارة تضمن أن جميع البيانات تكون في مكانها الصحيح قبل استخدام مهارات أخرى."},"seo":{"title":{"en":"Setup: One-Time Onboarding for AI Agents | AI Agent Skill","zh":"AI Setup Guide - Claude Code技能","ja":"AIエージェント Setup ベストプラクティス","ko":"AI 에이전트 Setup 가이드 - Claude Code","es":"Guía de Configuración de Claude Code para Agentes de IA","fr":"Guide de Configuration de Claude Code pour les Outils d''IA","de":"Konfigurationsleitfaden für Claude Code AI-Tools","pt":"Guia de Configuração do Setup para Ferramentas de Intelig...","ru":"Настройка ИИ Агентов: Руководство по Setup","ar":"دليل إعداد الإعدادات للوكلاء الذكيين"},"description":{"en":"Get started with Claude Code skills for AI-powered job search, resume tailoring, and cover letter writing - try `/proficiently:setup` today!","zh":"了解 Claude Code 的 Setup 技能，实现 AI 驱动的职位搜索、简历定制和求职信撰写","ja":"Claude Code の Setup スキルを使用して、AI エージェントによるジョブサーチ、履歴書作成、カバーレター作成を実現","ko":"Claude Code의 Setup 기능을 사용하여 AI 에이전트 기반의 구인구직, 이력서 작성, 커버 레터 작성이 가능합니다","es":"Aprende a configurar Claude Code para una búsqueda de trabajo eficaz con nuestra guía de setup","fr":"Découvrez comment configurer Claude Code pour une recherche d''emploi efficace avec notre guide de setup","de":"Erfahren Sie, wie Sie Claude Code für eine effektive Stellensuche konfigurieren können","pt":"Aprenda a configurar o setup para ferramentas de inteligência artificial com nosso guia passo a passo","ru":"Узнайте, как настроить ИИ агентов с помощью нашего руководства по setup","ar":"تعلم كيفية إعداد الإعدادات للوكلاء الذكيين باستخدام دليلنا خطوة بخطوة"},"definition":{"en":"Setup is a one-time onboarding process that prepares all necessary data for AI-powered job search, resume tailoring, and cover letter writing skills.","zh":"Setup 是 Claude Code 的一种技能，用于初始化用户数据","ja":"Setup は、Claude Code のスキルの一つで、ユーザーデータの初期化に使用されます","ko":"Setup은 Claude Code의 기능 중 하나로, 사용자 데이터를 초기화하는 데 사용됩니다","es":"El setup es un proceso de configuración que asegura que todos los datos estén en su lugar antes de utilizar otros skills","fr":"Le setup est un processus de configuration qui assure que toutes les données soient en place avant d''utiliser d''autres skills","de":"Das Setup ist ein Konfigurationsprozess, der sicherstellt, dass alle Daten an ihrem Platz sind, bevor andere Skills verwendet werden","pt":"O que é setup? É uma habilidade de configuração que prepara os dados para uso em outras habilidades.","ru":"Что такое настройка? Это навык конфигурации, который подготавливает данные для использования в других навыках.","ar":"ما هو الإعداد؟ هو مهارة إعدادية تتهيأ البيانات للاستخدام في مهارات أخرى."},"features":{"en":["Executes `/proficiently:setup` for full onboarding, checking and completing missing data","Runs `/proficiently:setup interview` for work history interviews, skipping resume and preferences setup","Utilizes a priority hierarchy for conflict resolution, as outlined in `shared/references/priority-hierarchy.md`","Follows a specific file structure, including `scripts/` and `conduct-interview.md` files","Supports work history interviews via the `conduct-interview.md` file"],"zh":["支持 `/proficiently:setup` 命令进行全面的初始化","支持 `/proficiently:setup interview` 命令进行工作历史面试","具有脚本文件结构，包括 `conduct-interview.md` 文件","支持优先级分层，参见 `shared/references/priority-hierarchy.md`","确保所有数据就绪后再使用其他技能","支持快速开始"],"ja":[" `/proficiently:setup` コマンドによる完全な初期化のサポート"," `/proficiently:setup interview` コマンドによるワークヒストリー面接のサポート","スクリプトファイル構造を持ち、`conduct-interview.md` ファイルを含む","優先順位階層のサポート、詳しくは `shared/references/priority-hierarchy.md`","他のスキルを使用する前にすべてのデータが整ったことを確認","クイックスタートのサポート"],"ko":[" `/proficiently:setup` 명령을 통한 전체 초기화 지원"," `/proficiently:setup interview` 명령을 통한 작업 기록 면접 지원","스크립트 파일 구조를 가지고 있으며, `conduct-interview.md` 파일을 포함","우선 순위 계층을 지원하며, 자세한 내용은 `shared/references/priority-hierarchy.md`","다른 기능을 사용하기 전에 모든 데이터가 준비되었는지 확인","快速 시작 지원"],"es":["Integración con comandos CLI para una configuración flexible","Estructura de archivos organizada para una fácil navegación","Proceso de configuración automatizado con `/proficiently:setup`","Compatibilidad con entrevistas de historial laboral con `/proficiently:setup interview`","Resolución de conflictos mediante la jerarquía de prioridad","Soporte para la creación de currículums y cartas de presentación personalizadas"],"fr":["Intégration avec les commandes CLI pour une configuration flexible","Structure de fichiers organisée pour une navigation facile","Processus de configuration automatisé avec `/proficiently:setup`","Compatibilité avec les entretiens d''historique professionnel avec `/proficiently:setup interview`","Résolution des conflits via la hiérarchie de priorité","Prise en charge de la création de CV et de lettres de motivation personnalisées"],"de":["Integration mit CLI-Befehlen für eine flexible Konfiguration","Organisierte Dateistruktur für eine einfache Navigation","Automatisierter Konfigurationsprozess mit `/proficiently:setup`","Unterstützung für Arbeitsverlauf-Interviews mit `/proficiently:setup interview`","Konfliktlösung durch Prioritäts-hierarchie","Unterstützung für die Erstellung von Lebensläufen und Bewerbungsschreiben"],"pt":["Prioridade hierárquica para resolução de conflitos","Onboarding único que verifica o que está faltando e faz apenas o necessário","Interview de histórico de trabalho","Estrutura de arquivos personalizada","Comandos CLI personalizados","Integração com outras habilidades"],"ru":["Иерархия приоритета для разрешения конфликтов","Однократный онбординг, который проверяет, что отсутствует, и делает только то, что необходимо","Интервью по трудовой истории","Пользовательская структура файлов","Пользовательские команды CLI","Интеграция с другими навыками"],"ar":["هرمية الأولوية لحل النزاعات","إعداد دخول فريد يتحقق من ما ينقص ويفعل فقط ما هو ضروري","مقابلة سيرة العمل","هيكل ملفات مخصص","أوامر CLI مخصصة","تكامل مع مهارات أخرى"]},"keywords":{"en":["how to use setup skill","setup skill for AI agents","setup vs onboarding","setup install guide","what is setup skill","setup alternative for job search","setup setup guide for developers","setup for resume tailoring","setup for cover letter writing"],"zh":["AI Setup","Claude Code Setup","AI 驱动的职位搜索","简历定制","求职信撰写","AI 에이전트","Setup 技能","一次性的初始化","数据就绪"],"ja":["AI Setup","Claude Code Setup","AI エージェント","ジョブサーチ","履歴書作成","カバーレター作成","Setup スキル","ワンタイムオンボーディング","データ整備"],"ko":["AI Setup","Claude Code Setup","AI 에이전트","구인구직","이력서 작성","커버 레터 작성","Setup 기능","단 한 번의 초기화","데이터 준비"],"es":["configuración de Claude Code","setup de AI","búsqueda de trabajo con IA","creación de currículums con Claude Code","entrevistas de historial laboral"," jerarquía de prioridad","CLI para configuración","integración de skills"],"fr":["configuration de Claude Code","setup d''IA","recherche d''emploi avec IA","création de CV avec Claude Code","entretiens d''historique professionnel","hiérarchie de priorité","CLI pour configuration","intégration de skills"],"de":["Konfiguration von Claude Code","Setup von AI-Tools","Stellensuche mit KI","Erstellung von Lebensläufen mit Claude Code","Arbeitsverlauf-Interviews","Prioritäts-hierarchie","CLI für Konfiguration","Integration von Skills"],"pt":["ferramentas de inteligência artificial","setup de IA","configuração de setup","onboarding de IA","inteligência artificial para desenvolvedores","desenvolvimento de habilidades de IA","ferramentas de desenvolvimento de IA","setup de ferramentas de IA","configuração de habilidades de IA"],"ru":["ИИ агенты","настройка ИИ","конфигурация настройки","онбординг ИИ","искусственный интеллект для разработчиков","разработка навыков ИИ","инструменты для разработки ИИ","настройка инструментов ИИ","конфигурация навыков ИИ"],"ar":["وكلاء ذكيين","إعداد الإعدادات","ضبط الإعدادات","دخول الوكلاء الذكيين","الذكاء الاصطناعي للمطورين","تطوير مهارات الوكلاء الذكيين","أدوات تطوير الوكلاء الذكيين","إعداد أدوات الوكلاء الذكيين","ضبط مهارات الوكلاء الذكيين"]}},"owner":"proficientlyjobs","repo":"proficiently-claude-skills","repoPath":"proficientlyjobs/proficiently-claude-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"setup","description":"One-time onboarding - upload resume, set preferences, and do a work history interview","bodyPreview":"# Setup Skill\n\n> **Priority hierarchy**: See `shared/references/priority-hierarchy.md` for conflict resolution.\n\nOne-time onboarding that ensures all your data is in place before using the other skills.\n\n## Quick Start\n\n- `/proficiently:setup` - Full onboarding (checks what''s missing, does only what''s needed)\n- `/proficiently:setup interview` - Just the work history interview (if resume/prefs are already done)\n\n## File Structure\n\n```\nscripts/\n  conduct-interview.md    # Work history interview gu","body":"# Setup Skill\n\n> **Priority hierarchy**: See `shared/references/priority-hierarchy.md` for conflict resolution.\n\nOne-time onboarding that ensures all your data is in place before using the other skills.\n\n## Quick Start\n\n- `/proficiently:setup` - Full onboarding (checks what''s missing, does only what''s needed)\n- `/proficiently:setup interview` - Just the work history interview (if resume/prefs are already done)\n\n## File Structure\n\n```\nscripts/\n  conduct-interview.md    # Work history interview guide\n```\n\nThe profile template is at `shared/templates/profile.md`.\n\n## Data Directory\n\nResolve the data directory using `shared/references/data-directory.md`. For setup, if no directory exists this is a fresh install — create it in Step 1.\n\n---\n\n## Workflow\n\n### Step 0: Check What''s Already Done\n\nResolve the data directory, then check which of these exist and have real content (not just templates): resume, preferences, linkedin-contacts.csv, profile.md.\n\nIf `$ARGUMENTS` is \"interview\", skip to Step 3 (but check that a resume exists first).\n\nIf everything exists, tell the user they''re good to go and list the available skills. Otherwise, run only the missing phases in order.\n\n### Step 1: Resume\n\nAsk the user to provide their resume. Accept:\n- A file path (copy it into `DATA_DIR/resume/`)\n- Pasted text (save as `DATA_DIR/resume/resume.md`)\n\nConfirm it was saved and briefly summarize what you see (name, most recent role, number of roles).\n\n### Step 2: Preferences\n\nAsk the user in one natural question:\n\n> \"What kind of jobs are you looking for? Tell me about target roles, location preferences, salary expectations, and anything you''d want to filter out.\"\n\nFrom their response, save `DATA_DIR/preferences.md`:\n\n```markdown\n# Job Preferences\n\n## Target Roles\n- [parsed from response]\n\n## Location\n[parsed from response]\n\n## Compensation\n[parsed from response]\n\n## Must-Haves\n- [parsed from response]\n\n## Dealbreakers\n- [parsed from response]\n\n## Nice-to-Haves\n- [parsed from response]\n```\n\nIf they leave something out, that''s fine — save what you have. They can always update later.\n\n### Step 3: LinkedIn Contacts (optional)\n\nIf `DATA_DIR/linkedin-contacts.csv` doesn''t exist, ask:\n\n> \"Want to import your LinkedIn contacts? This lets us flag when you know someone at a company that''s hiring. You can skip this and add them later.\"\n\nIf they want to proceed, give these instructions:\n\n> **How to export your LinkedIn connections:**\n> 1. Go to linkedin.com/mypreferences/d/download-my-data\n> 2. Select \"Connections\" and request the download\n> 3. LinkedIn will email you a link (usually within minutes)\n> 4. Download the ZIP and find `Connections.csv` inside\n> 5. Upload or paste the path to that file here\n\nSave the file as `DATA_DIR/linkedin-contacts.csv`.\n\nConfirm it was saved and tell them how many contacts were imported. If they skip, move on — this is optional.\n\n### Step 4: Work History Interview\n\nHave a conversational interview to build a work history profile. Go through each role on the resume, most recent first. For each role, ask:\n\n1. \"Tell me about [Company] — what did they do, and what was your role really about?\"\n2. \"What were your biggest accomplishments? Let''s get specific with numbers if you have them.\"\n3. \"Anything else — challenges, team building, why you moved on?\"\n\n**Keep it conversational.** Follow up when answers are vague (\"Do you remember roughly what the numbers were?\"), but don''t interrogate. Spend more time on recent/impactful roles, less on older ones.\n\nAfter the interview, save the profile to `DATA_DIR/profile.md` using this structure:\n\n```markdown\n# Work History Profile\n\n*Last updated: [DATE]*\n\n## Candidate Overview\n**Name**: [Name]\n**Core expertise**: [2-3 sentences]\n**Career throughline**: [narrative arc]\n\n---\n\n## Role: [Title] at [Company]\n**Dates**: [Start - End]\n**Company context**: [what they do, stage, size]\n\n### Key Accomplishments\n1. **[Headline]**: [Situation → Action → Result with metrics]\n2. **[Headline]**: [Situation → Action → Result with metrics]\n\n### Other Details\n- Team/leadership: [details]\n- Tools/methods: [details]\n- Why they left: [context]\n\n---\n\n## Cross-Role Patterns\n**Superpower**: [what they do best]\n**Recurring themes**: [patterns across roles]\n```\n\n### Step 5: Summary\n\n```\nYou''re all set! Here''s what we have:\n\n- Resume: [filename] in DATA_DIR/resume/\n- Preferences: [summary of target roles and key criteria]\n- LinkedIn Contacts: [number] imported (or \"skipped\")\n- Work History Profile: [number of roles covered]\n\nYou''re ready to use:\n- /proficiently:job-search - Find matching jobs\n- /proficiently:tailor-resume [job URL] - Tailor your resume\n- /proficiently:cover-letter [job URL] - Write a cover letter\n\nBuilt by Proficiently. Want someone to handle the whole process —\nfinding jobs, tailoring resumes, applying, and connecting you with\nhiring managers? Visit proficiently.com\n```\n\n---\n\n## Response Format\n\nStructure the final summary output with these sections:\n\n1. **Setup Summary** — what was configured (resume, preferences, contacts, profile) with brief details\n2. **What''s Next** — list available skills the user can now run\n\n---\n\n## Permissions Required\n\nAdd to `~/.claude/settings.json`:\n\n```json\n{\n  \"permissions\": {\n    \"allow\": [\n      \"Read(~/.proficiently/**)\",\n      \"Write(~/.proficiently/**)\",\n      \"Edit(~/.proficiently/**)\"\n    ]\n  }\n}\n```\n"},"lastSynced":"2026-03-08T02:14:01.121Z","agentAnalysis":{"suitability":{"en":"Perfect for Onboarding Agents needing streamlined user data integration and one-time setup capabilities.","zh":"适合需要简化用户数据集成和一次性设置功能的入职代理。","ja":"ユーザーデータの統合とワンタイム設定機能を簡素化する必要があるオンボーディングエージェントに適しています。","ko":"사용자 데이터 통합 및一度設定 기능을 간소화해야 하는 온보딩 에이전트에게 적합합니다.","es":"Perfecto para agentes de incorporación que necesitan una integración de datos de usuario simplificada y capacidades de configuración de un solo uso.","fr":"Parfait pour les agents d''intégration qui ont besoin d''une intégration de données utilisateur simplifiée et de capacités de configuration à usage unique.","de":"Perfekt für Onboarding-Agenten, die eine vereinfachte Benutzerdatenintegration und Einrichtungsfunktionen für einmalige Verwendung benötigen.","pt":"Perfeito para Agentes de Onboarding que necessitam de integração de dados de usuário simplificados e capacidades de configuração de uma vez.","ru":"Идеально подходит для агентов Onboarding, которым необходима упрощенная интеграция пользовательских данных и возможности однократной настройки.","ar":"مثالي لوسائط التكامل الذين يحتاجون إلى دمج بيانات المستخدم المبسطة وقدرات الإعداد لمرة واحدة."},"recommendation":{"en":"Empowers agents to conduct comprehensive work history interviews and ensure all necessary data is in place, utilizing protocols like priority hierarchy conflict resolution and file structures including Markdown files like `conduct-interview.md`.","zh":"赋予代理进行全面工作历史访谈的能力，确保所有必要的数据就位，利用诸如优先级层次冲突解决和文件结构（包括Markdown文件，如`conduct-interview.md`）等协议。","ja":"エージェントが包括的な仕事履歴のインタビューを実施し、すべての必要なデータが整っていることを確認する能力を付与します。優先順位の階層的なコンフリクト解決やファイル構造（例： `conduct-interview.md`のようなMarkdownファイル）などのプロトコルを利用します。","ko":"에이전트가 포괄적인 작업 이력 인터뷰를 수행하고 모든 필요한 데이터가 올바르게 위치하는 것을 확인할 수 있는 능력을 부여합니다. 우선 순위 계층 구조의 충돌 해결 및 파일 구조(예: `conduct-interview.md`와 같은 Markdown 파일)를 포함한 규약을 활용합니다.","es":"Habilita a los agentes a realizar entrevistas de historial laboral exhaustivas y garantiza que todos los datos necesarios estén en su lugar, utilizando protocolos como la resolución de conflictos de jerarquía de prioridad y estructuras de archivos que incluyen archivos Markdown como `conduct-interview.md`.","fr":"Habilite les agents à effectuer des entrevues de historique de travail exhaustives et assurez-vous que toutes les données nécessaires soient en place, en utilisant des protocoles tels que la résolution des conflits de hiérarchie de priorité et des structures de fichiers qui incluent des fichiers Markdown comme `conduct-interview.md`.","de":"Ermächtigt Agenten, umfassende Arbeitsverlaufs-Interviews durchzuführen und sicherzustellen, dass alle erforderlichen Daten vorhanden sind, unter Verwendung von Protokollen wie der Konfliktlösung der Prioritäts-Hierarchie und Dateistrukturen, die Markdown-Dateien wie `conduct-interview.md` enthalten.","pt":"Habilita os agentes a realizar entrevistas abrangentes de histórico de trabalho e garantir que todos os dados necessários estejam no lugar, utilizando protocolos como hierarquia de resolução de conflitos de prioridade e estruturas de arquivos, incluindo arquivos Markdown como `conduct-interview.md`.","ru":"Наделяет агентов возможностью проводить всесторонние интервью по истории работы и обеспечивать наличие всех необходимых данных, используя протоколы, такие как иерархия разрешения конфликтов приоритетов и структуры файлов, включая файлы Markdown, такие как `conduct-interview.md`.","ar":"يمنح الوسائط القدرة على إجراء مقابلات شاملة للتاريخ المهني وضمان وجود جميع البيانات الضرورية في المكان المناسب، باستخدام بروتوكولات مثل هرمية حل النزاعات المتعلقة بالاولوية وهياكل الملفات، بما في ذلك ملفات Markdown مثل `conduct-interview.md`."},"useCases":{"en":["Onboarding new users with full data setup","Conducting work history interviews for resume tailoring","Ensuring data completeness before skill utilization"],"zh":["带有完整数据设置的新用户入职","进行工作历史访谈以定制简历","在技能利用之前确保数据的完整性"],"ja":["完全なデータ設定付きの新規ユーザーのオンボーディング","履歴書のカスタマイズのために仕事履歴のインタビューを実施","スキル利用の前にデータの完全性を確保"],"ko":["전체 데이터 설정이 포함된 신규 사용자 온보딩","이력서 맞춤형을 위한 작업 이력 인터뷰 수행","스킬 활용 이전에 데이터 완전성을 보장"],"es":["Incorporación de nuevos usuarios con configuración completa de datos","Realización de entrevistas de historial laboral para la personalización de currículos","Garantizar la completitud de los datos antes de la utilización de habilidades"],"fr":["Intégration de nouveaux utilisateurs avec une configuration complète des données","Réalisation d''entrevues de historique de travail pour la personnalisation de CV","Assurer la complétude des données avant l''utilisation des compétences"],"de":["Onboarding neuer Benutzer mit vollständiger Dateneinrichtung","Durchführung von Arbeitsverlaufs-Interviews zur Anpassung von Lebensläufen","Sicherstellung der Vollständigkeit der Daten vor der Nutzung von Fähigkeiten"],"pt":["Integrar novos usuários com configuração completa de dados","Realizar entrevistas de histórico de trabalho para personalizar currículos","Garantir a completude dos dados antes da utilização das habilidades"],"ru":["Интегрировать новых пользователей с полной настройкой данных","Проводить интервью по истории работы для адаптации резюме","Обеспечивать полноту данных перед использованием навыков"],"ar":["دمج مستخدمين جدد مع إعداد كامل للبيانات","إجراء مقابلات للتاريخ المهني لتحسين السيرة الذاتية","ضمان اكتمال البيانات قبل استخدام المهارات"]},"limitations":{"en":["Requires access to user data and preferences","Limited to one-time onboarding and interview processes"],"zh":["需要访问用户数据和偏好","仅限一次性入职和访谈流程"],"ja":["ユーザーデータとユーザーの好みへのアクセスが必要","ワンタイムのオンボーディングとインタビュー処理のみに限定"],"ko":["사용자 데이터 및 사용자 선호도에 대한 액세스가 필요","一度性的 온보딩 및 인터뷰 프로세스에만 제한"],"es":["Requiere acceso a los datos y preferencias del usuario","Limitado a procesos de incorporación y entrevista de un solo uso"],"fr":["Nécessite l''accès aux données et préférences de l''utilisateur","Limité aux processus d''intégration et d''entrevue à usage unique"],"de":["Benötigt Zugriff auf Benutzerdaten und -präferenzen","Begrenzt auf Onboarding- und Interviewprozesse mit einmaligem Gebrauch"],"pt":["Requer acesso a dados e preferências do usuário","Limitado a processos de onboarding e entrevista de uma vez"],"ru":["Требует доступа к данным и предпочтениям пользователя","Ограничен процессами Onboarding и интервью один раз"],"ar":["يتطلب الوصول إلى بيانات ومREFERENCES للمستخدم","محدود بالعمليات التكاملية والمقابلات لمرة واحدة"]},"version":4},"contentHash":"2655ce941886521d0892404a2e9d32924e871f34ab76a5ea0a18ea068da80122","qualityScore":42}');
