INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('proficientlyjobs/proficiently-claude-skills/setup', 'setup', 'proficientlyjobs', 'proficiently-claude-skills', 'community', 'setup proficientlyjobs proficiently-claude-skills community The setup skill ensures all data is in place before using other skills, benefiting developers and job seekers. It provides one-time onboarding for AI-powered job search and resume tailoring. Setup 技能为您的数据提供了一次性的初始化，确保所有数据就绪后再使用其他技能 Setup スキルは、他のスキルを使用する前に、すべてのデータが整ったことを確認するためのワンタイムオンボーディングです Setup 기능은 다른 기능을 사용하기 전에 모든 데이터가 준비되었는지 확인하는 단 한 번의 초기화 과정입니다 El skill de configuración de Claude Code permite una integración fluida para la búsqueda de trabajo y la creación de currículums Le skill de configuration de Claude Code permet une intégration fluide pour la recherche d''emploi et la création de CV Das Setup-Skill von Claude Code ermöglicht eine nahtlose Integration für die Stellensuche und die Erstellung von Lebensläufen O setup é uma habilidade que garante que todos os dados estejam no lugar antes de usar outras habilidades. Настройка - это навык, который обеспечивает правильное расположение всех данных перед использованием других навыков. الإعداد هو مهارة تضمن أن جميع البيانات تكون في مكانها الصحيح قبل استخدام مهارات أخرى. how to use setup skill setup skill for AI agents setup vs onboarding setup install guide what is setup skill setup alternative for job search setup setup guide for developers setup for resume tailoring setup for cover letter writing AI Setup Claude Code Setup AI 驱动的职位搜索 简历定制 求职信撰写 AI 에이전트 Setup 技能 一次性的初始化 数据就绪 Executes `/proficiently:setup` for full onboarding, checking and completing missing data Runs `/proficiently:setup interview` for work history interviews, skipping resume and preferences setup Utilizes a priority hierarchy for conflict resolution, as outlined in `shared/references/priority-hierarchy.md` Follows a specific file structure, including `scripts/` and `conduct-interview.md` files Supports work history interviews via the `conduct-interview.md` file Setup is a one-time onboarding process that prepares all necessary data for AI-powered job search, resume tailoring, and cover letter writing skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adrianomucha/logbook-fit-repo/desktop', 'community', 'adrianomucha', 'logbook-fit-repo', 'adrianomucha/logbook-fit-repo', 'desktop', 0, 0, 42, '2026-03-08T01:39:41Z', '2026-03-08T02:14:22.339Z', '4f87ae28ff6a664525939fe15f5c5b27fc958fded93eadbafed08d78b1c47d90', '{"id":"adrianomucha/logbook-fit-repo/desktop","name":"desktop","description":{"en":"The desktop skill enables developers to build and manage desktop applications using Electron''s main-renderer architecture. It benefits developers by providing a secure and efficient way to expose main process functionality to the renderer.","zh":"Electron 桌面开发是基于主渲染器架构，提供了强大的桌面应用开发能力","ja":"Electron デスクトップ開発はメインレンダラーアーキテクチャに基づいており、強力なデスクトップアプリ開発機能を提供します","ko":"Electron 데스크톱 개발은 메인 렌더러 아키텍처를 기반으로 하며 강력한 데스크톱 애플리케이션 개발 기능을 제공합니다","es":"El desarrollo de escritorio con Electron y main-renderer architecture permite crear aplicaciones robustas y seguras. Aprende a agregar nuevas características y mejorar la seguridad","fr":"Le développement de bureau avec Electron et l''architecture main-renderer permet de créer des applications robustes et sécurisées. Apprenez à ajouter de nouvelles fonctionnalités et améliorer la sécurité","de":"Die Desktop-Entwicklung mit Electron und Main-Renderer-Architektur ermöglicht die Erstellung robuster und sicherer Anwendungen. Erfahren Sie, wie Sie neue Funktionen hinzufügen und die Sicherheit verbessern","pt":"O desktop é construído com Electron e arquitetura main-renderer, permitindo o desenvolvimento de aplicações desktop robustas.","ru":"Desktop построен на Electron с архитектурой main-renderer, что позволяет разрабатывать мощные настольные приложения.","ar":"تم بناء سطح المكتب باستخدام Electron وتصميم main-renderer، مما يسمح بتطوير تطبيقات سطح المكتب القوية."},"seo":{"title":{"en":"Desktop: Electron-Based Development Setup Guide | AI A