INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EthanAlgoX/MarketBot/gog', 'gog', 'EthanAlgoX', 'MarketBot', 'community', 'gog EthanAlgoX MarketBot community The gog skill is a finance-customized AI agent for market intelligence, trading analysis, and decision support, built on openclaw. It benefits developers and financial analysts gog 是一个命令行工具，用于集成 Gmail、Calendar、Drive 等服务，通过 OAuth 进行授权 gog は、Gmail、Calendar、Drive などのサービスを統合するためのコマンドラインツールで、OAuth を使用して認証を行う gog는 Gmail, Calendar, Drive 등의 서비스를 통합하기 위한 명령줄 도구로서 OAuth를 사용하여 인증을 수행한다 gog es una herramienta de línea de comandos para interactuar con servicios de Google como Gmail y Calendar. Requiere configuración de OAuth gog est un outil en ligne de commande pour interagir avec les services Google tels que Gmail et Calendar. Nécessite une configuration OAuth gog ist ein Kommandozeilen-Tool für die Interaktion mit Google-Diensten wie Gmail und Calendar. Benötigt OAuth-Konfiguration O gog é uma ferramenta de automação de tarefas que utiliza OAuth para gerenciar e-mails e calendários. Aprenda a configurá-lo com comandos como gog auth e gog gmail search gog - это инструмент для автоматизации задач, использующий OAuth для управления электронной почтой и календарями. Узнайте, как настроить его с помощью команд gog auth и gog gmail search gog هو أداة لتشغيل المهام الآلية التي تستخدم OAuth لإدارة البريد الإلكتروني والتقويم. تعلم كيفية إعداده باستخدام أوامر مثل gog auth و gog gmail search how to use gog gog oauth setup gog vs openclaw gog install guide what is gog gog alternative gog market intelligence gog trading analysis gog setup tutorial gog authentication gog Gmail API Calendar API Drive API OAuth 命令行工具 AI エージェント 自动化 集成 Requires OAuth setup using client_secret.json Supports authentication with multiple Google services: Gmail, Calendar, Drive, Contacts, Docs, Sheets Enables Gmail search using commands like ''gog gmail search ''newer_than:7d'''' Allows Gmail messages search per email, ignoring threading, with commands like ''gog gmail messages search "in:inbox from:ryanair.com"'' Supports sending plain Gmail messages using ''gog gmail send'' command gog is a dedicated AI agent for market intelligence, trading analysis, and decision support, utilizing OAuth for authentication');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mrfansi/shlink/mobile-design', 'community', 'mrfansi', 'shlink', 'mrfansi/shlink', 'mobile-design', 0, 0, 42, '2026-03-07T12:46:33.424Z', '2026-03-07T12:54:01.971Z', 'ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682', '{"id":"mrfansi/shlink/mobile-design","name":"mobile-design","description":{"en":"The mobile-design skill enables developers to create touch-first, battery-conscious, and offline-capable mobile applications. It benefits developers who need to design mobile interfaces with a focus on mobile constraints.","zh":"移动设计系统是一个touch-first、battery-conscious、platform-respectful和offline-capable的设计哲学。使用Python脚本进行移动UX和触摸审计","ja":"モバイルデザインシステムはタッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能なデザイン哲学です。Pythonスクリプトを使用してモバイルUXとタッチをオーディット","ko":"모바일 디자인 시스템은 터치 우선, 배터리 인식, 플랫폼 존중 및 오프라인 가능な 디자인 철학입니다. Python 스크립트를 사용하여 모바일 UX 및 터치를 감사","es":"El sistema de diseño móvil se centra en la filosofía de touch-first y plataforma-respetful, con scripts de validación como mobile_audit.py","fr":"Le système de conception mobile se concentre sur la philosophie de touch-first et de respect de plateforme, avec des scripts de validation tels que mobile_audit.py","de":"Das mobile Design-System konzentriert sich auf die Philosophie von touch-first und plattformrespektierend, mit Validierungsskripten wie mobile_audit.py","pt":"O design móvel é uma abordagem touch-first, battery-conscious e platform-respectful. Aprenda a criar experiências móveis de alta qualidade","ru":"Мобильный дизайн - это подход, ориентированный на сенсорное управление, экономию батареи и уважение к платформе. Узнайте, как создать высококачественные мобильные trải nghiệm","ar":"التصميم الجوالي هو نهج يركز على اللمس أولاً وتوفير البطارية والاحترام للمنصة. تعلم كيفية إنشاء تجارب جوال عالية الجودة"},"seo":{"title":{"en":"mobile-design: Touch-First Development Setup Guide | AI A...","zh":"移动设计系统搭建指南 - AIエージェント","ja":"モバイルデザインシステムのベストプラクティス - AIエージェント","ko":"모바일 디자인 시스템 설정 가이드 - AI 도구","es":"Guía de configuración de diseño móvil para desarrolladores","fr":"Guide de mise en place de la conception mobile pour les d...","de":"Einrichtungsleitfaden für mobile Designs für Entwickler","pt":"Guia de Configuração de Design Móvel: Melhores Práticas p...","ru":"Руководство по настройке мобильного дизайна: Лучшие практ...","ar":"دليل إعداد تصميم الجوال: أفضل الممارسات للعاملين في مجال ..."},"description":{"en":"Unlock mobile design system best practices with our AI agent skill, featuring touch-first philosophy and platform-respectful development. Get started now!","zh":"了解移动设计系统的核心原则和技术细节，优化您的移动应用体验。使用Python脚本进行移动UX和触摸审计","ja":"モバイルデザインシステムの哲学とコアプリンシプルを理解し、モバイルアプリの体験を最適化する。Pythonスクリプトを使用してモバイルUXとタッチをオーディット","ko":"모바일 디자인 시스템의 철학과 핵심 원리를 이해하고 모바일 앱의 경험을 최적화하십시오. Python 스크립트를 사용하여 모바일 UX 및 터치를 감사","es":"Aprende a crear experiencias móviles óptimas con nuestro sistema de diseño móvil. Ejecuta scripts de validación para asegurar la calidad","fr":"Créez des expériences mobiles optimales avec notre système de conception mobile. Exécutez des scripts de validation pour assurer la qualité","de":"Erstellen Sie optimale Mobile-Erfahrungen mit unserem mobilen Design-System. Führen Sie Validierungsskripte aus, um die Qualität zu gewährleisten","pt":"Aprenda a criar experiências móveis de alta qualidade com nossa guia de design móvel. Descubra as melhores práticas e ferramentas para desenvolvedores","ru":"Узнайте, как создать высококачественные мобильные trải nghiệm с нашим руководством по мобильному дизайну. Откройте для себя лучшие практики и инструменты для...","ar":"تعلم كيفية إنشاء تجارب جوال عالية الجودة مع دليلنا للتصميم الجوالي. اكتشف أفضل الممارسات والأدوات للعاملين في مجال الأدوات الذكية"},"definition":{"en":"mobile-design is a touch-first development approach that prioritizes mobile constraints, platform choice, and offline capabilities.","zh":"移动设计系统是一种设计哲学，注重touch-first、battery-conscious、platform-respectful和offline-capable的设计原则","ja":"モバイルデザインシステムはタッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能なデザイン原則に焦点を当てたデザイン哲学です","ko":"모바일 디자인 시스템은 터치 우선, 배터리 인식, 플랫폼 존중 및 오프라인 가능な 디자인 원칙에 중점을 둔 디자인 철학입니다","es":"Diseño móvil es un enfoque de creación de experiencias móviles que prioriza la usabilidad y la eficiencia","fr":"La conception mobile est une approche de création d''expériences mobiles qui donne la priorité à l''ergonomie et à l''efficacité","de":"Mobiles Design ist ein Ansatz zur Erstellung von Mobile-Erfahrungen, der die Benutzerfreundlichkeit und Effizienz priorisiert","pt":"Design móvel é uma abordagem de design que prioriza a experiência do usuário em dispositivos móveis","ru":"Мобильный дизайн - это подход к дизайну, который отдает приоритет опыту пользователя на мобильных устройствах","ar":"التصميم الجوالي هو نهج في التصميم يؤثر على تجربة المستخدم في الأجهزة الجوالة"},"features":{"en":["Executes mobile UX and touch audits using scripts/mobile_audit.py","Validates mobile applications with python scripts/mobile_audit.py <project_path>","Respects platform choice with a focus on mobile constraints","Develops offline-capable mobile applications","Applies a touch-first philosophy to mobile design","Utilizes runtime scripts for validation and testing"],"zh":["Touch-first设计哲学","Battery-conscious设计原则","Platform-respectful设计原则","Offline-capable设计原则","Python脚本用于移动UX和触摸审计"],"ja":["タッチファースト設計哲学","バッテリー意識設計原則","プラットフォーム尊重設計原則","オフライン可能設計原則","Pythonスクリプトを使用してモバイルUXとタッチをオーディット"],"ko":["터치 우선 디자인 철학","배터리 인식 디자인 원칙","플랫폼 존중 디자인 원칙","오프라인 가능 디자인 원칙","Python 스크립트를 사용하여 모바일 UX 및 터치를 감사"],"es":["Filosofía de touch-first","Respeto por la plataforma","Capacidad de funcionamiento sin conexión","Script de validación mobile_audit.py","Optimización para batería y rendimiento"],"fr":["Philosophie de touch-first","Respect de la plateforme","Capacité de fonctionnement hors ligne","Script de validation mobile_audit.py","Optimisation pour la batterie et les performances"],"de":["Touch-first-Philosophie","Plattformrespekt","Offline-Fähigkeit","Validierungsskript mobile_audit.py","Optimierung für Batterie und Leistung"],"pt":["Abordagem touch-first para experiências móveis","Otimização para economia de bateria","Desenvolvimento de aplicativos para múltiplas plataformas","Execução de scripts de validação para garantir a qualidade","Uso de ferramentas como Python e CLI para desenvolvimento"],"ru":["Подход, ориентированный на сенсорное управление, для мобильных trải nghiệm","Оптимизация для экономии батареи","Разработка приложений для нескольких платформ","Выполнение скриптов валидации для обеспечения качества","Использование инструментов seperti Python и CLI для разработки"],"ar":["نهج يركز على اللمس أولاً لتجارب الجوال","تحسين لتحقيق توفير في البطارية","تطوير تطبيقات للعديد من المنصات","تشغيل سكريبتات التحقق لضمان الجودة","استخدام أدوات مثل Python و CLI للتحwicklung"]},"keywords":{"en":["how to use mobile-design","what is mobile-design","mobile-design alternative","mobile-design vs responsive design","mobile-design install","mobile-design setup guide","touch-first development","mobile constraints","platform-respectful development"],"zh":["移动设计系统","AIエージェント","touch-first设计","battery-conscious设计","platform-respectful设计","offline-capable设计","Python脚本","移动UX","触摸审计"],"ja":["モバイルデザインシステム","AIエージェント","タッチファースト設計","バッテリー意識設計","プラットフォーム尊重設計","オフライン可能設計","Pythonスクリプト","モバイルUX","タッチオーディット"],"ko":["모바일 디자인 시스템","AI 도구","터치 우선 디자인","배터리 인식 디자인","플랫폼 존중 디자인","오프라인 가능 디자인","Python 스크립트","모바일 UX","터치 감사"],"es":["diseño móvil","herramientas de diseño móvil","sistema de diseño móvil","optimización de batería","validación de experiencia móvil","desarrollo de aplicaciones móviles","AI Herramientas","Agentes de IA"],"fr":["conception mobile","outils de conception mobile","système de conception mobile","optimisation de la batterie","validation de l''expérience mobile","développement d''applications mobiles","Outils d''IA","Agents d''IA"],"de":["mobiles Design","Design-Tools für mobile Geräte","mobilies Design-System","Batterie-Optimierung","Validierung von Mobile-Erfahrungen","Entwicklung von Mobile-Anwendungen","KI-Tools","KI-Agents"],"pt":["design móvel","desenvolvimento de aplicativos móveis","experiência do usuário","otimização para bateria","desenvolvimento de aplicativos para múltiplas plataformas","Python","CLI","validação de qualidade"],"ru":["мобильный дизайн","разработка мобильных приложений","опыт пользователя","оптимизация для батареи","разработка приложений для нескольких платформ","Python","CLI","валидация качества"],"ar":["التصميم الجوالي","تطوير تطبيقات الجوال","تجربة المستخدم","تحسين لتحقيق توفير في البطارية","تطوير تطبيقات للعديد من المنصات","Python","CLI","تحقق الجودة"]}},"owner":"mrfansi","repo":"shlink","repoPath":"mrfansi/shlink","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.424Z","topics":[],"category":"community","skillMd":{"name":"mobile-design","description":"Mobile-first design thinking and decision-making for iOS and Android apps. Touch interaction, performance patterns, platform conventions. Teaches principles, not fixed values. Use when building React Native, Flutter, or native mobile apps.","bodyPreview":"# Mobile Design System\n\n> **Philosophy:** Touch-first. Battery-conscious. Platform-respectful. Offline-capable.\n> **Core Principle:** Mobile is NOT a small desktop. THINK mobile constraints, ASK platform choice.\n\n---\n\n## 🔧 Runtime Scripts\n\n**Execute these for validation (don''t read, just run):**\n\n| Script | Purpose | Usage |\n|--------|---------|-------|\n| `scripts/mobile_audit.py` | Mobile UX & Touch Audit | `python scripts/mobile_audit.py <project_path>` |\n\n---\n\n## 🔴 MANDATORY: Read Reference","body":"# Mobile Design System\n\n> **Philosophy:** Touch-first. Battery-conscious. Platform-respectful. Offline-capable.\n> **Core Principle:** Mobile is NOT a small desktop. THINK mobile constraints, ASK platform choice.\n\n---\n\n## 🔧 Runtime Scripts\n\n**Execute these for validation (don''t read, just run):**\n\n| Script | Purpose | Usage |\n|--------|---------|-------|\n| `scripts/mobile_audit.py` | Mobile UX & Touch Audit | `python scripts/mobile_audit.py <project_path>` |\n\n---\n\n## 🔴 MANDATORY: Read Reference Files Before Working!\n\n**⛔ DO NOT start development until you read the relevant files:**\n\n### Universal (Always Read)\n\n| File | Content | Status |\n|------|---------|--------|\n| **[mobile-design-thinking.md](mobile-design-thinking.md)** | **⚠️ ANTI-MEMORIZATION: Forces thinking, prevents AI defaults** | **⬜ CRITICAL FIRST** |\n| **[touch-psychology.md](touch-psychology.md)** | **Fitts'' Law, gestures, haptics, thumb zone** | **⬜ CRITICAL** |\n| **[mobile-performance.md](mobile-performance.md)** | **RN/Flutter performance, 60fps, memory** | **⬜ CRITICAL** |\n| **[mobile-backend.md](mobile-backend.md)** | **Push notifications, offline sync, mobile API** | **⬜ CRITICAL** |\n| **[mobile-testing.md](mobile-testing.md)** | **Testing pyramid, E2E, platform-specific** | **⬜ CRITICAL** |\n| **[mobile-debugging.md](mobile-debugging.md)** | **Native vs JS debugging, Flipper, Logcat** | **⬜ CRITICAL** |\n| [mobile-navigation.md](mobile-navigation.md) | Tab/Stack/Drawer, deep linking | ⬜ Read |\n| [mobile-typography.md](mobile-typography.md) | System fonts, Dynamic Type, a11y | ⬜ Read |\n| [mobile-color-system.md](mobile-color-system.md) | OLED, dark mode, battery-aware | ⬜ Read |\n| [decision-trees.md](decision-trees.md) | Framework/state/storage selection | ⬜ Read |\n\n> 🧠 **mobile-design-thinking.md is PRIORITY!** This file ensures AI thinks instead of using memorized patterns.\n\n### Platform-Specific (Read Based on Target)\n\n| Platform | File | Content | When to Read |\n|----------|------|---------|--------------|\n| **iOS** | [platform-ios.md](platform-ios.md) | Human Interface Guidelines, SF Pro, SwiftUI patterns | Building for iPhone/iPad |\n| **Android** | [platform-android.md](platform-android.md) | Material Design 3, Roboto, Compose patterns | Building for Android |\n| **Cross-Platform** | Both above | Platform divergence points | React Native / Flutter |\n\n> 🔴 **If building for iOS → Read platform-ios.md FIRST!**\n> 🔴 **If building for Android → Read platform-android.md FIRST!**\n> 🔴 **If cross-platform → Read BOTH and apply conditional platform logic!**\n\n---\n\n## ⚠️ CRITICAL: ASK BEFORE ASSUMING (MANDATORY)\n\n> **STOP! If the user''s request is open-ended, DO NOT default to your favorites.**\n\n### You MUST Ask If Not Specified:\n\n| Aspect | Ask | Why |\n|--------|-----|-----|\n| **Platform** | \"iOS, Android, or both?\" | Affects EVERY design decision |\n| **Framework** | \"React Native, Flutter, or native?\" | Determines patterns and tools |\n| **Navigation** | \"Tab bar, drawer, or stack-based?\" | Core UX decision |\n| **State** | \"What state management? (Zustand/Redux/Riverpod/BLoC?)\" | Architecture foundation |\n| **Offline** | \"Does this need to work offline?\" | Affects data strategy |\n| **Target devices** | \"Phone only, or tablet support?\" | Layout complexity |\n\n### ⛔ AI MOBILE ANTI-PATTERNS (YASAK LİSTESİ)\n\n> 🚫 **These are AI default tendencies that MUST be avoided!**\n\n#### Performance Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **ScrollView for long lists** | Renders ALL items, memory explodes | Use `FlatList` / `FlashList` / `ListView.builder` |\n| **Inline renderItem function** | New function every render, all items re-render | `useCallback` + `React.memo` |\n| **Missing keyExtractor** | Index-based keys cause bugs on reorder | Unique, stable ID from data |\n| **Skip getItemLayout** | Async layout = janky scroll | Provide when items have fixed height |\n| **setState() everywhere** | Unnecessary widget rebuilds | Targeted state, `const` constructors |\n| **Native driver: false** | Animations blocked by JS thread | `useNativeDriver: true` always |\n| **console.log in production** | Blocks JS thread severely | Remove before release build |\n| **Skip React.memo/const** | Every item re-renders on any change | Memoize list items ALWAYS |\n\n#### Touch/UX Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Touch target < 44px** | Impossible to tap accurately, frustrating | Minimum 44pt (iOS) / 48dp (Android) |\n| **Spacing < 8px between targets** | Accidental taps on neighbors | Minimum 8-12px gap |\n| **Gesture-only interactions** | Motor impaired users excluded | Always provide button alternative |\n| **No loading state** | User thinks app crashed | ALWAYS show loading feedback |\n| **No error state** | User stuck, no recovery path | Show error with retry option |\n| **No offline handling** | Crash/block when network lost | Graceful degradation, cached data |\n| **Ignore platform conventions** | Users confused, muscle memory broken | iOS feels iOS, Android feels Android |\n\n#### Security Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Token in AsyncStorage** | Easily accessible, stolen on rooted device | `SecureStore` / `Keychain` / `EncryptedSharedPreferences` |\n| **Hardcode API keys** | Reverse engineered from APK/IPA | Environment variables, secure storage |\n| **Skip SSL pinning** | MITM attacks possible | Pin certificates in production |\n| **Log sensitive data** | Logs can be extracted | Never log tokens, passwords, PII |\n\n#### Architecture Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Business logic in UI** | Untestable, unmaintainable | Service layer separation |\n| **Global state for everything** | Unnecessary re-renders, complexity | Local state default, lift when needed |\n| **Deep linking as afterthought** | Notifications, shares broken | Plan deep links from day one |\n| **Skip dispose/cleanup** | Memory leaks, zombie listeners | Clean up subscriptions, timers |\n\n---\n\n## 📱 Platform Decision Matrix\n\n### When to Unify vs Diverge\n\n```\n                    UNIFY (same on both)          DIVERGE (platform-specific)\n                    ───────────────────           ──────────────────────────\nBusiness Logic      ✅ Always                     -\nData Layer          ✅ Always                     -\nCore Features       ✅ Always                     -\n                    \nNavigation          -                             ✅ iOS: edge swipe, Android: back button\nGestures            -                             ✅ Platform-native feel\nIcons               -                             ✅ SF Symbols vs Material Icons\nDate Pickers        -                             ✅ Native pickers feel right\nModals/Sheets       -                             ✅ iOS: bottom sheet vs Android: dialog\nTypography          -                             ✅ SF Pro vs Roboto (or custom)\nError Dialogs       -                             ✅ Platform conventions for alerts\n```\n\n### Quick Reference: Platform Defaults\n\n| Element | iOS | Android |\n|---------|-----|---------|\n| **Primary Font** | SF Pro / SF Compact | Roboto |\n| **Min Touch Target** | 44pt × 44pt | 48dp × 48dp |\n| **Back Navigation** | Edge swipe left | System back button/gesture |\n| **Bottom Tab Icons** | SF Symbols | Material Symbols |\n| **Action Sheet** | UIActionSheet from bottom | Bottom Sheet / Dialog |\n| **Progress** | Spinner | Linear progress (Material) |\n| **Pull to Refresh** | Native UIRefreshControl | SwipeRefreshLayout |\n\n---\n\n## 🧠 Mobile UX Psychology (Quick Reference)\n\n### Fitts'' Law for Touch\n\n```\nDesktop: Cursor is precise (1px)\nMobile:  Finger is imprecise (~7mm contact area)\n\n→ Touch targets MUST be 44-48px minimum\n→ Important actions in THUMB ZONE (bottom of screen)\n→ Destructive actions AWAY from easy reach\n```\n\n### Thumb Zone (One-Handed Usage)\n\n```\n┌─────────────────────────────┐\n│      HARD TO REACH          │ ← Navigation, menu, back\n│        (stretch)            │\n├─────────────────────────────┤\n│      OK TO REACH            │ ← Secondary actions\n│       (natural)             │\n├─────────────────────────────┤\n│      EASY TO REACH          │ ← PRIMARY CTAs, tab bar\n│    (thumb''s natural arc)    │ ← Main content interaction\n└─────────────────────────────┘\n        [  HOME  ]\n```\n\n### Mobile-Specific Cognitive Load\n\n| Desktop | Mobile Difference |\n|---------|-------------------|\n| Multiple windows | ONE task at a time |\n| Keyboard shortcuts | Touch gestures |\n| Hover states | NO hover (tap or nothing) |\n| Large viewport | Limited space, scroll vertical |\n| Stable attention | Interrupted constantly |\n\nFor deep dive: [touch-psychology.md](touch-psychology.md)\n\n---\n\n## ⚡ Performance Principles (Quick Reference)\n\n### React Native Critical Rules\n\n```typescript\n// ✅ CORRECT: Memoized renderItem + React.memo wrapper\nconst ListItem = React.memo(({ item }: { item: Item }) => (\n  <View style={styles.item}>\n    <Text>{item.title}</Text>\n  </View>\n));\n\nconst renderItem = useCallback(\n  ({ item }: { item: Item }) => <ListItem item={item} />,\n  []\n);\n\n// ✅ CORRECT: FlatList with all optimizations\n<FlatList\n  data={items}\n  renderItem={renderItem}\n  keyExtractor={(item) => item.id}  // Stable ID, NOT index\n  getItemLayout={(data, index) => ({\n    length: ITEM_HEIGHT,\n    offset: ITEM_HEIGHT * index,\n    index,\n  })}\n  removeClippedSubviews={true}\n  maxToRenderPerBatch={10}\n  windowSize={5}\n/>\n```\n\n### Flutter Critical Rules\n\n```dart\n// ✅ CORRECT: const constructors prevent rebuilds\nclass MyWidget extends StatelessWidget {\n  const MyWidget({super.key}); // CONST!\n\n  @override\n  Widget build(BuildContext context) {\n    return const Column( // CONST!\n      children: [\n        Text(''Static content''),\n        MyConstantWidget(),\n      ],\n    );\n  }\n}\n\n// ✅ CORRECT: Targeted state with ValueListenableBuilder\nValueListenableBuilder<int>(\n  valueListenable: counter,\n  builder: (context, value, child) => Text(''$value''),\n  child: const ExpensiveWidget(), // Won''t rebuild!\n)\n```\n\n### Animation Performance\n\n```\nGPU-accelerated (FAST):     CPU-bound (SLOW):\n├── transform               ├── width, height\n├── opacity                 ├── top, left, right, bottom\n└── (use these ONLY)        ├── margin, padding\n                            └── (AVOID animating these)\n```\n\nFor complete guide: [mobile-performance.md](mobile-performance.md)\n\n---\n\n## 📝 CHECKPOINT (MANDATORY Before Any Mobile Work)\n\n> **Before writing ANY mobile code, you MUST complete this checkpoint:**\n\n```\n🧠 CHECKPOINT:\n\nPlatform:   [ iOS / Android / Both ]\nFramework:  [ React Native / Flutter / SwiftUI / Kotlin ]\nFiles Read: [ List the skill files you''ve read ]\n\n3 Principles I Will Apply:\n1. _______________\n2. _______________\n3. _______________\n\nAnti-Patterns I Will Avoid:\n1. _______________\n2. _______________\n```\n\n**Example:**\n```\n🧠 CHECKPOINT:\n\nPlatform:   iOS + Android (Cross-platform)\nFramework:  React Native + Expo\nFiles Read: touch-psychology.md, mobile-performance.md, platform-ios.md, platform-android.md\n\n3 Principles I Will Apply:\n1. FlatList with React.memo + useCallback for all lists\n2. 48px touch targets, thumb zone for primary CTAs\n3. Platform-specific navigation (edge swipe iOS, back button Android)\n\nAnti-Patterns I Will Avoid:\n1. ScrollView for lists → FlatList\n2. Inline renderItem → Memoized\n3. AsyncStorage for tokens → SecureStore\n```\n\n> 🔴 **Can''t fill the checkpoint? → GO BACK AND READ THE SKILL FILES.**\n\n---\n\n## 🔧 Framework Decision Tree\n\n```\nWHAT ARE YOU BUILDING?\n        │\n        ├── Need OTA updates + rapid iteration + web team\n        │   └── ✅ React Native + Expo\n        │\n        ├── Need pixel-perfect custom UI + performance critical\n        │   └── ✅ Flutter\n        │\n        ├── Deep native features + single platform focus\n        │   ├── iOS only → SwiftUI\n        │   └── Android only → Kotlin + Jetpack Compose\n        │\n        ├── Existing RN codebase + new features\n        │   └── ✅ React Native (bare workflow)\n        │\n        └── Enterprise + existing Flutter codebase\n            └── ✅ Flutter\n```\n\nFor complete decision trees: [decision-trees.md](decision-trees.md)\n\n---\n\n## 📋 Pre-Development Checklist\n\n### Before Starting ANY Mobile Project\n\n- [ ] **Platform confirmed?** (iOS / Android / Both)\n- [ ] **Framework chosen?** (RN / Flutter / Native)\n- [ ] **Navigation pattern decided?** (Tabs / Stack / Drawer)\n- [ ] **State management selected?** (Zustand / Redux / Riverpod / BLoC)\n- [ ] **Offline requirements known?**\n- [ ] **Deep linking planned from day one?**\n- [ ] **Target devices defined?** (Phone / Tablet / Both)\n\n### Before Every Screen\n\n- [ ] **Touch targets ≥ 44-48px?**\n- [ ] **Primary CTA in thumb zone?**\n- [ ] **Loading state exists?**\n- [ ] **Error state with retry exists?**\n- [ ] **Offline handling considered?**\n- [ ] **Platform conventions followed?**\n\n### Before Release\n\n- [ ] **console.log removed?**\n- [ ] **SecureStore for sensitive data?**\n- [ ] **SSL pinning enabled?**\n- [ ] **Lists optimized (memo, keyExtractor)?**\n- [ ] **Memory cleanup on unmount?**\n- [ ] **Tested on low-end devices?**\n- [ ] **Accessibility labels on all interactive elements?**\n\n---\n\n## 📚 Reference Files\n\nFor deeper guidance on specific areas:\n\n| File | When to Use |\n|------|-------------|\n| [mobile-design-thinking.md](mobile-design-thinking.md) | **FIRST! Anti-memorization, forces context-based thinking** |\n| [touch-psychology.md](touch-psychology.md) | Understanding touch interaction, Fitts'' Law, gesture design |\n| [mobile-performance.md](mobile-performance.md) | Optimizing RN/Flutter, 60fps, memory/battery |\n| [platform-ios.md](platform-ios.md) | iOS-specific design, HIG compliance |\n| [platform-android.md](platform-android.md) | Android-specific design, Material Design 3 |\n| [mobile-navigation.md](mobile-navigation.md) | Navigation patterns, deep linking |\n| [mobile-typography.md](mobile-typography.md) | Type scale, system fonts, accessibility |\n| [mobile-color-system.md](mobile-color-system.md) | OLED optimization, dark mode, battery |\n| [decision-trees.md](decision-trees.md) | Framework, state, storage decisions |\n\n---\n\n> **Remember:** Mobile users are impatient, interrupted, and using imprecise fingers on small screens. Design for the WORST conditions: bad network, one hand, bright sun, low battery. If it works there, it works everywhere.\n"},"lastSynced":"2026-03-07T12:54:01.971Z","agentAnalysis":{"suitability":{"en":"Perfect for Interface Agents needing to create touch-first and offline-capable mobile applications.","zh":"非常适合需要创建面向触摸和离线功能的移动应用程序的接口代理。","ja":"タッチを優先し、オフライン機能を備えたモバイルアプリケーションを作成する必要があるインターフェースエージェントに最適です。","ko":"터치 우선 및 오프라인 기능이 가능한 모바일 애플리케이션을 생성해야 하는 인터페이스 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Interfaz que necesitan crear aplicaciones móviles de primera interacción táctil y capaces de funcionar sin conexión.","fr":"Parfait pour les Agents d''Interface ayant besoin de créer des applications mobiles tactiles et capables de fonctionner hors ligne.","de":"Perfekt für Interface-Agents, die berührungserste und offline-fähige Mobile-Anwendungen erstellen müssen.","pt":"Perfeito para Agentes de Interface que precisam criar aplicativos móveis touch-first e capazes de funcionar offline.","ru":"Идеально для Интерфейсных Агентов, которым необходимо создавать сенсорные и автономные мобильные приложения.","ar":"مثالي للوكلاء الواجهة الذين يحتاجون إلى إنشاء تطبيقات الهاتف المحمول التي تعمل باللمس وأوفلاين."},"recommendation":{"en":"Empowers agents to design mobile interfaces with a focus on mobile constraints, leveraging touch-first and battery-conscious principles, and utilizing platform-respectful and offline-capable protocols.","zh":"赋予代理设计移动接口的能力，重点关注移动约束，利用触摸优先和电池节能原则，并利用尊重平台和离线功能的协议。","ja":"エージェントがモバイルの制約に焦点を当てたモバイルインターフェイスの設計を行えるようにし、タッチを優先し、バッテリーに配慮した原則を利用し、プラットフォームを尊重し、オフライン機能を備えたプロトコルを利用できるようにします。","ko":"에이전트가 모바일 인터페이스를 설계할 수 있도록 하고, 모바일 제약 조건에 중점을 두고, 터치 우선 및 배터리節約 원칙을 활용하며, 플랫폼을 존중하고 오프라인 기능을 갖춘 프로토콜을 활용할 수 있도록 합니다.","es":"Habilita a los agentes para diseñar interfaces móviles con un enfoque en las limitaciones móviles, aprovechando principios de primera interacción táctil y de ahorro de batería, y utilizando protocolos respetuosos con la plataforma y capaces de funcionar sin conexión.","fr":"Autonomise les agents pour concevoir des interfaces mobiles en tenant compte des contraintes mobiles, en exploitant les principes de première interaction tactile et de conscience de la batterie, et en utilisant des protocoles respectueux de la plate-forme et capables de fonctionner hors ligne.","de":"Ermächtigt Agenten, mobile Schnittstellen mit einem Fokus auf mobile Einschränkungen zu entwerfen, indem sie berührungserste und batteriebewusste Prinzipien nutzen und plattformrespektierende und offline-fähige Protokolle verwenden.","pt":"Habilita os agentes a projetarem interfaces móveis com foco nas restrições móveis, aproveitando princípios touch-first e economia de bateria, e utilizando protocolos respeitosos com a plataforma e capazes de funcionar offline.","ru":"Наделяет агентов возможностью проектировать мобильные интерфейсы с учетом мобильных ограничений, используя сенсорные и энергосберегающие принципы, и применяя уважительные к платформе и автономные протоколы.","ar":"يسمح للوكلاء بتصميم واجهات الهاتف المحمول مع التركيز على قيود الهاتف المحمول، واستخدام مبادئ اللمس الأول وتوفير البطارية، وتطبيق بروتوكولات محترمة للمنصة وقادرة على العمل بدون اتصال."},"useCases":{"en":["Designing touch-first mobile interfaces","Optimizing mobile applications for battery life","Developing offline-capable mobile experiences"],"zh":["设计面向触摸的移动接口","优化移动应用程序的电池寿命","开发离线功能的移动体验"],"ja":["タッチを優先したモバイルインターフェイスの設計","モバイルアプリケーションのバッテリー寿命の最適化","オフライン機能を備えたモバイル体験の開発"],"ko":["터치 우선 모바일 인터페이스 설계","모바일 애플리케이션의 배터리 수명의 최적화","오프라인 기능을 갖춘 모바일 경험 개발"],"es":["Diseñar interfaces móviles de primera interacción táctil","Optimizar aplicaciones móviles para la vida de la batería","Desarrollar experiencias móviles capaces de funcionar sin conexión"],"fr":["Concevoir des interfaces mobiles tactiles","Optimiser les applications mobiles pour la durée de vie de la batterie","Développer des expériences mobiles capables de fonctionner hors ligne"],"de":["Berührungserste mobile Schnittstellen entwerfen","Mobile Anwendungen für die Batterielebensdauer optimieren","Offline-fähige mobile Erfahrungen entwickeln"],"pt":["Projetar interfaces móveis touch-first","Otimizar aplicativos móveis para vida útil da bateria","Desenvolver experiências móveis capazes de funcionar offline"],"ru":["Проектирование сенсорных мобильных интерфейсов","Оптимизация мобильных приложений для жизни батареи","Разработка автономных мобильных опытов"],"ar":["تصميم واجهات الهاتف المحمول التي تعمل باللمس","تحسين تطبيقات الهاتف المحمول لحياة البطارية","تطوير تجارب الهاتف المحمول القادرة على العمل بدون اتصال"]},"limitations":{"en":["Requires consideration of mobile constraints","Platform-specific design choices needed"],"zh":["需要考虑移动约束","需要平台特定的设计选择"],"ja":["モバイルの制約を考慮する必要がある","プラットフォーム固有の設計選択が必要"],"ko":["모바일 제약 조건을 고려해야 함","플랫폼 별 디자인 선택이 필요"],"es":["Requiere consideración de las limitaciones móviles","Se necesitan opciones de diseño específicas de la plataforma"],"fr":["Nécessite une prise en compte des contraintes mobiles","Des choix de conception spécifiques à la plate-forme sont nécessaires"],"de":["Erfordert Berücksichtigung mobiler Einschränkungen","Plattformspezifische Designentscheidungen sind erforderlich"],"pt":["Requer consideração das restrições móveis","Escolhas de design específicas da plataforma necessárias"],"ru":["Требует учета мобильных ограничений","Необходимы платформо-специфические дизайнерские решения"],"ar":["يتطلب مراعاة قيود الهاتف المحمول","اختيارات تصميم محددة بالمنصة ضرورية"]},"version":4},"contentHash":"ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682","qualityScore":42}');
