INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mrfansi/shlink/mobile-design', 'mobile-design', 'mrfansi', 'shlink', 'community', 'mobile-design mrfansi shlink community The mobile-design skill enables developers to create touch-first, battery-conscious, and offline-capable mobile applications. It benefits developers who need to design mobile interfaces with a focus on mobile constraints. 移动设计系统是一个touch-first、battery-conscious、platform-respectful和offline-capable的设计哲学。使用Python脚本进行移动UX和触摸审计 モバイルデザインシステムはタッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能なデザイン哲学です。Pythonスクリプトを使用してモバイルUXとタッチをオーディット 모바일 디자인 시스템은 터치 우선, 배터리 인식, 플랫폼 존중 및 오프라인 가능な 디자인 철학입니다. Python 스크립트를 사용하여 모바일 UX 및 터치를 감사 El sistema de diseño móvil se centra en la filosofía de touch-first y plataforma-respetful, con scripts de validación como mobile_audit.py Le système de conception mobile se concentre sur la philosophie de touch-first et de respect de plateforme, avec des scripts de validation tels que mobile_audit.py Das mobile Design-System konzentriert sich auf die Philosophie von touch-first und plattformrespektierend, mit Validierungsskripten wie mobile_audit.py O design móvel é uma abordagem touch-first, battery-conscious e platform-respectful. Aprenda a criar experiências móveis de alta qualidade Мобильный дизайн - это подход, ориентированный на сенсорное управление, экономию батареи и уважение к платформе. Узнайте, как создать высококачественные мобильные trải nghiệm التصميم الجوالي هو نهج يركز على اللمس أولاً وتوفير البطارية والاحترام للمنصة. تعلم كيفية إنشاء تجارب جوال عالية الجودة how to use mobile-design what is mobile-design mobile-design alternative mobile-design vs responsive design mobile-design install mobile-design setup guide touch-first development mobile constraints platform-respectful development 移动设计系统 AIエージェント touch-first设计 battery-conscious设计 platform-respectful设计 offline-capable设计 Python脚本 移动UX 触摸审计 Executes mobile UX and touch audits using scripts/mobile_audit.py Validates mobile applications with python scripts/mobile_audit.py <project_path> Respects platform choice with a focus on mobile constraints Develops offline-capable mobile applications Applies a touch-first philosophy to mobile design Utilizes runtime scripts for validation and testing mobile-design is a touch-first development approach that prioritizes mobile constraints, platform choice, and offline capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jesus-bazan-entel/apolo-lms-admin/mobile-design', 'community', 'jesus-bazan-entel', 'apolo-lms-admin', 'jesus-bazan-entel/apolo-lms-admin', 'mobile-design', 0, 0, 42, '2026-03-07T12:46:33.424Z', '2026-03-07T12:54:43.974Z', 'ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682', '{"id":"jesus-bazan-entel/apolo-lms-admin/mobile-design","name":"mobile-design","description":{"en":"The mobile-design skill enables developers to create touch-first, battery-conscious, and platform-respectful mobile applications. It benefits developers working on Apolo LMS Admin projects.","zh":"移动设计系统是一种touch-first、battery-conscious、platform-respectful、offline-capable的设计哲学，帮助开发者创建优质的移动应用","ja":"モバイルデザインシステムは、タッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能な設計哲学であり、開発者が高品質のモバイルアプリを作成するのに役立ちます","ko":"모바일 디자인 시스템은 터치 우선, 배터리 최적화, 플랫폼 존중, 오프라인 가능性的 디자인 철학으로 개발자가 고품질의 모바일 앱을 생성하는 데 도움이 됩니다","es":"Nuestro enfoque de diseño móvil para agentes de IA se centra en una filosofía de primer contacto, consciente de la batería y respetuosa con la plataforma. Incluye scripts de ejecución para validación","fr":"Notre approche de conception mobile pour les agents IA repose sur une philosophie de premier contact, consciente de la batterie et respectueuse de la plateforme. Elle inclut des scripts d''exécution pour la validation","de":"Unser Ansatz für mobiles Design von KI-Agents basiert auf einer Philosophie des ersten Kontakts, der batteriebewusst und plattformrespektierend ist. Enthält Ausführungsskripte für Validierung","pt":"O design móvel é uma abordagem touch-first, battery-conscious e platform-respectful para criar experiências móveis de alta qualidade","ru":"Мобильный дизайн - это подход, ориентированный на осязание, экономящий батарею и уважающий платформу для создания высококачественных мобильных trải nghiệm","ar":"تصميم الهاتف المحمول هو نهج يركز على اللمس، ي حفاظ على البطارية ويهتم بالمنصة لإنشاء تجارب الهاتف المحمول عالية الجودة"},"seo":{"title":{"en":"mobile-design: Touch-First Development Setup Guide | AI A...","zh":"移动设计系统搭建指南 - AIエージェント","ja":"モバイルデザインのベストプラクティス - AIエージェント","ko":"모바일 디자인 시스템 설정 가이드 - AI Tools","es":"Guía de Diseño Móvil para Agentes de IA: Mejores Prácticas","fr":"Conception Mobile pour Agents IA : Guide de Configuration","de":"Mobile Design für KI-Agents: Einrichtungsleitfaden","pt":"Guia de Configuração de Design Móvel para Ferramentas de IA","ru":"Настройка Мобильного Дизайна для ИИ Агентов","ar":"دليل تصميم الهاتف المحمول لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient mobile development with mobile-design. Run validation scripts and master touch-first design principles. Get started now!","zh":"了解移动设计系统的核心原则和运行时脚本，优化您的移动应用体验 - AIエージェント","ja":"モバイルデザインシステムの哲学とコアプリンシプルを学び、モバイルアプリのUXを改善する - AIエージェント","ko":"모바일 디자인 시스템의 철학과 핵심 원리를 배우고 모바일 앱의 사용자 경험을 최적화하십시오 - AI Tools","es":"Aprende a diseñar experiencias móviles para agentes de IA con nuestro enfoque en filosofía de diseño y scripts de ejecución para validación","fr":"Découvrez comment concevoir des expériences mobiles pour les agents IA avec notre approche de philosophie de conception et de scripts d''exécution pour la val...","de":"Erfahren Sie, wie Sie mobile Erfahrungen für KI-Agents mit unserem Designansatz und Ausführungsskripten für Validierung erstellen","pt":"Aprenda a criar experiências móveis de alta qualidade com nosso guia de design móvel para ferramentas de IA, incluindo validação de UX e auditoria de toque","ru":"Создайте высококачественные мобильные trải nghiệm с нашим руководством по мобильному дизайну для ИИ агентов, включая проверку UX и аудит осязания","ar":"تعلم كيفية إنشاء تجارب الهاتف المحمول عالية الجودة مع دليلنا لتصميم الهاتف المحمول لأدوات الذكاء الاصطناعي، بما في ذلك التحقق من UX ومراجعة اللمس"},"definition":{"en":"mobile-design is a development approach focusing on touch-first, offline-capable, and platform-respectful design principles for mobile applications.","zh":"移动设计系统是一种设计哲学，专注于创建优质的移动应用","ja":"モバイルデザインシステムは、優れたモバイルアプリを作成するための設計哲学です","ko":"모바일 디자인 시스템은 우수한 모바일 앱을 생성하기 위한 디자인 철학입니다","es":"Diseño móvil para agentes de IA: enfoque de diseño centrado en la experiencia móvil","fr":"Conception mobile pour les agents IA : approche de conception centrée sur l''expérience mobile","de":"Mobiles Design für KI-Agents: Designansatz mit Fokus auf mobile Erfahrung","pt":"Design móvel é uma filosofia de design que prioriza a experiência do usuário em dispositivos móveis","ru":"Мобильный дизайн - это философия дизайна, которая отдает приоритет опыту пользователя на мобильных устройствах","ar":"تصميم الهاتف المحمول هو فلسفة التصميم التي تؤثر على تجربة المستخدم على أجهزة الهاتف المحمول"},"features":{"en":["Executes mobile UX and touch audits using scripts/mobile_audit.py","Validates project code with python scripts/mobile_audit.py <project_path>","Applies core principle that mobile is NOT a small desktop","Respects platform choice and thinks mobile constraints","Runs runtime scripts for validation and testing","References technical documentation for mandatory reading"],"zh":["Touch-first设计哲学","Battery-conscious优化","Platform-respectful兼容性","Offline-capable离线支持","Python运行时脚本"],"ja":["タッチファースト設計哲学","バッテリー意識最適化","プラットフォーム尊重互換性","オフライン可能なオフラインサポート","Python実行時スクリプト"],"ko":["터치 우선 디자인 철학","배터리 최적화","플랫폼 존중 호환성","오프라인 가능性的 오프라인 지원","Python 실행 시 스크립트"],"es":["Filosofía de diseño de primer contacto","Scripts de ejecución para validación de UX y touch","Compatibilidad con plataformas móviles","Capacidad de funcionamiento sin conexión","Uso de Python para scripts de ejecución"],"fr":["Philosophie de conception de premier contact","Scripts d''exécution pour la validation de l''UX et du toucher","Compatibilité avec les plateformes mobiles","Capacité de fonctionnement hors ligne","Utilisation de Python pour les scripts d''exécution"],"de":["Designphilosophie des ersten Kontakts","Ausführungsskripte für Validierung von UX und Touch","Kompatibilität mit mobilen Plattformen","Fähigkeit zur Offline-Funktion","Verwendung von Python für Ausführungsskripte"],"pt":["Abordagem touch-first para criar experiências móveis intuitivas","Validação de UX e auditoria de toque com scripts Python","Desenvolvimento de aplicativos móveis com consideração de plataforma","Otimização de bateria para experiências móveis eficientes","Suporte a funcionalidades offline para acessibilidade"],"ru":["Подход, ориентированный на осязание, для создания интуитивных мобильных trải nghiệm","Проверка UX и аудит осязания с помощью скриптов Python","Разработка мобильных приложений с учетом платформы","Оптимизация батареи для эффективных мобильных trải nghiệm","Поддержка функций offline для доступности"],"ar":["نهج يركز على اللمس لإنشاء تجارب الهاتف المحمول بديهية","التحقق من UX ومراجعة اللمس باستخدام البرامج النصية Python","تطوير تطبيقات الهاتف المحمول مع考虑 المنصة","تحسين البطارية لتجارب الهاتف المحمول الفعالة","دعم الميزات ngoại tuyến للوصول"]},"keywords":{"en":["how to use mobile-design","mobile-design setup guide","what is mobile-design","mobile-design alternative","mobile-design vs responsive design","mobile-design install","touch-first development","platform-respectful design","offline-capable mobile applications"],"zh":["移动设计系统","AIエージェント","touch-first设计","battery-conscious优化","platform-respectful兼容性","offline-capable离线支持","Python运行时脚本","移动应用开发"],"ja":["モバイルデザインシステム","AIエージェント","タッチファースト設計","バッテリー意識最適化","プラットフォーム尊重互換性","オフライン可能なオフラインサポート","Python実行時スクリプト","モバイルアプリ開発"],"ko":["모바일 디자인 시스템","AI Tools","터치 우선 디자인","배터리 최적화","플랫폼 존중 호환성","오프라인 가능性的 오프라인 지원","Python 실행 시 스크립트","모바일 앱 개발"],"es":["diseño móvil para agentes de IA","guias de diseño móvil","mejores prácticas de diseño móvil","validación de UX móvil","scripts de Python para diseño móvil","diseño de experiencia móvil","agentes de IA móviles","herramientas de diseño móvil para agentes de IA"],"fr":["conception mobile pour les agents IA","guides de conception mobile","meilleures pratiques de conception mobile","validation de l''UX mobile","scripts Python pour la conception mobile","conception d''expérience mobile","agents IA mobiles","outils de conception mobile pour les agents IA"],"de":["mobiles Design für KI-Agents","Designleitfäden für mobiles Design","Best Practices für mobiles Design","Validierung von UX für mobiles Design","Python-Skripte für mobiles Design","Design von mobiler Erfahrung","mobile KI-Agents","Tools für mobiles Design für KI-Agents"],"pt":["design móvel","ferramentas de IA","experiências móveis","validação de UX","auditoria de toque","Python","desenvolvimento de aplicativos móveis"],"ru":["мобильный дизайн","ИИ агенты","мобильные trải nghiệm","проверка UX","аудит осязания","Python","разработка мобильных приложений"],"ar":["تصميم الهاتف المحمول","أدوات الذكاء الاصطناعي","تجارب الهاتف المحمول","التحقق من UX","مراجعة اللمس","Python","تطوير تطبيقات الهاتف المحمول"]}},"owner":"jesus-bazan-entel","repo":"apolo-lms-admin","repoPath":"jesus-bazan-entel/apolo-lms-admin","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.424Z","topics":[],"category":"community","skillMd":{"name":"mobile-design","description":"Mobile-first design thinking and decision-making for iOS and Android apps. Touch interaction, performance patterns, platform conventions. Teaches principles, not fixed values. Use when building React Native, Flutter, or native mobile apps.","bodyPreview":"# Mobile Design System\n\n> **Philosophy:** Touch-first. Battery-conscious. Platform-respectful. Offline-capable.\n> **Core Principle:** Mobile is NOT a small desktop. THINK mobile constraints, ASK platform choice.\n\n---\n\n## 🔧 Runtime Scripts\n\n**Execute these for validation (don''t read, just run):**\n\n| Script | Purpose | Usage |\n|--------|---------|-------|\n| `scripts/mobile_audit.py` | Mobile UX & Touch Audit | `python scripts/mobile_audit.py <project_path>` |\n\n---\n\n## 🔴 MANDATORY: Read Reference","body":"# Mobile Design System\n\n> **Philosophy:** Touch-first. Battery-conscious. Platform-respectful. Offline-capable.\n> **Core Principle:** Mobile is NOT a small desktop. THINK mobile constraints, ASK platform choice.\n\n---\n\n## 🔧 Runtime Scripts\n\n**Execute these for validation (don''t read, just run):**\n\n| Script | Purpose | Usage |\n|--------|---------|-------|\n| `scripts/mobile_audit.py` | Mobile UX & Touch Audit | `python scripts/mobile_audit.py <project_path>` |\n\n---\n\n## 🔴 MANDATORY: Read Reference Files Before Working!\n\n**⛔ DO NOT start development until you read the relevant files:**\n\n### Universal (Always Read)\n\n| File | Content | Status |\n|------|---------|--------|\n| **[mobile-design-thinking.md](mobile-design-thinking.md)** | **⚠️ ANTI-MEMORIZATION: Forces thinking, prevents AI defaults** | **⬜ CRITICAL FIRST** |\n| **[touch-psychology.md](touch-psychology.md)** | **Fitts'' Law, gestures, haptics, thumb zone** | **⬜ CRITICAL** |\n| **[mobile-performance.md](mobile-performance.md)** | **RN/Flutter performance, 60fps, memory** | **⬜ CRITICAL** |\n| **[mobile-backend.md](mobile-backend.md)** | **Push notifications, offline sync, mobile API** | **⬜ CRITICAL** |\n| **[mobile-testing.md](mobile-testing.md)** | **Testing pyramid, E2E, platform-specific** | **⬜ CRITICAL** |\n| **[mobile-debugging.md](mobile-debugging.md)** | **Native vs JS debugging, Flipper, Logcat** | **⬜ CRITICAL** |\n| [mobile-navigation.md](mobile-navigation.md) | Tab/Stack/Drawer, deep linking | ⬜ Read |\n| [mobile-typography.md](mobile-typography.md) | System fonts, Dynamic Type, a11y | ⬜ Read |\n| [mobile-color-system.md](mobile-color-system.md) | OLED, dark mode, battery-aware | ⬜ Read |\n| [decision-trees.md](decision-trees.md) | Framework/state/storage selection | ⬜ Read |\n\n> 🧠 **mobile-design-thinking.md is PRIORITY!** This file ensures AI thinks instead of using memorized patterns.\n\n### Platform-Specific (Read Based on Target)\n\n| Platform | File | Content | When to Read |\n|----------|------|---------|--------------|\n| **iOS** | [platform-ios.md](platform-ios.md) | Human Interface Guidelines, SF Pro, SwiftUI patterns | Building for iPhone/iPad |\n| **Android** | [platform-android.md](platform-android.md) | Material Design 3, Roboto, Compose patterns | Building for Android |\n| **Cross-Platform** | Both above | Platform divergence points | React Native / Flutter |\n\n> 🔴 **If building for iOS → Read platform-ios.md FIRST!**\n> 🔴 **If building for Android → Read platform-android.md FIRST!**\n> 🔴 **If cross-platform → Read BOTH and apply conditional platform logic!**\n\n---\n\n## ⚠️ CRITICAL: ASK BEFORE ASSUMING (MANDATORY)\n\n> **STOP! If the user''s request is open-ended, DO NOT default to your favorites.**\n\n### You MUST Ask If Not Specified:\n\n| Aspect | Ask | Why |\n|--------|-----|-----|\n| **Platform** | \"iOS, Android, or both?\" | Affects EVERY design decision |\n| **Framework** | \"React Native, Flutter, or native?\" | Determines patterns and tools |\n| **Navigation** | \"Tab bar, drawer, or stack-based?\" | Core UX decision |\n| **State** | \"What state management? (Zustand/Redux/Riverpod/BLoC?)\" | Architecture foundation |\n| **Offline** | \"Does this need to work offline?\" | Affects data strategy |\n| **Target devices** | \"Phone only, or tablet support?\" | Layout complexity |\n\n### ⛔ AI MOBILE ANTI-PATTERNS (YASAK LİSTESİ)\n\n> 🚫 **These are AI default tendencies that MUST be avoided!**\n\n#### Performance Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **ScrollView for long lists** | Renders ALL items, memory explodes | Use `FlatList` / `FlashList` / `ListView.builder` |\n| **Inline renderItem function** | New function every render, all items re-render | `useCallback` + `React.memo` |\n| **Missing keyExtractor** | Index-based keys cause bugs on reorder | Unique, stable ID from data |\n| **Skip getItemLayout** | Async layout = janky scroll | Provide when items have fixed height |\n| **setState() everywhere** | Unnecessary widget rebuilds | Targeted state, `const` constructors |\n| **Native driver: false** | Animations blocked by JS thread | `useNativeDriver: true` always |\n| **console.log in production** | Blocks JS thread severely | Remove before release build |\n| **Skip React.memo/const** | Every item re-renders on any change | Memoize list items ALWAYS |\n\n#### Touch/UX Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Touch target < 44px** | Impossible to tap accurately, frustrating | Minimum 44pt (iOS) / 48dp (Android) |\n| **Spacing < 8px between targets** | Accidental taps on neighbors | Minimum 8-12px gap |\n| **Gesture-only interactions** | Motor impaired users excluded | Always provide button alternative |\n| **No loading state** | User thinks app crashed | ALWAYS show loading feedback |\n| **No error state** | User stuck, no recovery path | Show error with retry option |\n| **No offline handling** | Crash/block when network lost | Graceful degradation, cached data |\n| **Ignore platform conventions** | Users confused, muscle memory broken | iOS feels iOS, Android feels Android |\n\n#### Security Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Token in AsyncStorage** | Easily accessible, stolen on rooted device | `SecureStore` / `Keychain` / `EncryptedSharedPreferences` |\n| **Hardcode API keys** | Reverse engineered from APK/IPA | Environment variables, secure storage |\n| **Skip SSL pinning** | MITM attacks possible | Pin certificates in production |\n| **Log sensitive data** | Logs can be extracted | Never log tokens, passwords, PII |\n\n#### Architecture Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Business logic in UI** | Untestable, unmaintainable | Service layer separation |\n| **Global state for everything** | Unnecessary re-renders, complexity | Local state default, lift when needed |\n| **Deep linking as afterthought** | Notifications, shares broken | Plan deep links from day one |\n| **Skip dispose/cleanup** | Memory leaks, zombie listeners | Clean up subscriptions, timers |\n\n---\n\n## 📱 Platform Decision Matrix\n\n### When to Unify vs Diverge\n\n```\n                    UNIFY (same on both)          DIVERGE (platform-specific)\n                    ───────────────────           ──────────────────────────\nBusiness Logic      ✅ Always                     -\nData Layer          ✅ Always                     -\nCore Features       ✅ Always                     -\n                    \nNavigation          -                             ✅ iOS: edge swipe, Android: back button\nGestures            -                             ✅ Platform-native feel\nIcons               -                             ✅ SF Symbols vs Material Icons\nDate Pickers        -                             ✅ Native pickers feel right\nModals/Sheets       -                             ✅ iOS: bottom sheet vs Android: dialog\nTypography          -                             ✅ SF Pro vs Roboto (or custom)\nError Dialogs       -                             ✅ Platform conventions for alerts\n```\n\n### Quick Reference: Platform Defaults\n\n| Element | iOS | Android |\n|---------|-----|---------|\n| **Primary Font** | SF Pro / SF Compact | Roboto |\n| **Min Touch Target** | 44pt × 44pt | 48dp × 48dp |\n| **Back Navigation** | Edge swipe left | System back button/gesture |\n| **Bottom Tab Icons** | SF Symbols | Material Symbols |\n| **Action Sheet** | UIActionSheet from bottom | Bottom Sheet / Dialog |\n| **Progress** | Spinner | Linear progress (Material) |\n| **Pull to Refresh** | Native UIRefreshControl | SwipeRefreshLayout |\n\n---\n\n## 🧠 Mobile UX Psychology (Quick Reference)\n\n### Fitts'' Law for Touch\n\n```\nDesktop: Cursor is precise (1px)\nMobile:  Finger is imprecise (~7mm contact area)\n\n→ Touch targets MUST be 44-48px minimum\n→ Important actions in THUMB ZONE (bottom of screen)\n→ Destructive actions AWAY from easy reach\n```\n\n### Thumb Zone (One-Handed Usage)\n\n```\n┌─────────────────────────────┐\n│      HARD TO REACH          │ ← Navigation, menu, back\n│        (stretch)            │\n├─────────────────────────────┤\n│      OK TO REACH            │ ← Secondary actions\n│       (natural)             │\n├─────────────────────────────┤\n│      EASY TO REACH          │ ← PRIMARY CTAs, tab bar\n│    (thumb''s natural arc)    │ ← Main content interaction\n└─────────────────────────────┘\n        [  HOME  ]\n```\n\n### Mobile-Specific Cognitive Load\n\n| Desktop | Mobile Difference |\n|---------|-------------------|\n| Multiple windows | ONE task at a time |\n| Keyboard shortcuts | Touch gestures |\n| Hover states | NO hover (tap or nothing) |\n| Large viewport | Limited space, scroll vertical |\n| Stable attention | Interrupted constantly |\n\nFor deep dive: [touch-psychology.md](touch-psychology.md)\n\n---\n\n## ⚡ Performance Principles (Quick Reference)\n\n### React Native Critical Rules\n\n```typescript\n// ✅ CORRECT: Memoized renderItem + React.memo wrapper\nconst ListItem = React.memo(({ item }: { item: Item }) => (\n  <View style={styles.item}>\n    <Text>{item.title}</Text>\n  </View>\n));\n\nconst renderItem = useCallback(\n  ({ item }: { item: Item }) => <ListItem item={item} />,\n  []\n);\n\n// ✅ CORRECT: FlatList with all optimizations\n<FlatList\n  data={items}\n  renderItem={renderItem}\n  keyExtractor={(item) => item.id}  // Stable ID, NOT index\n  getItemLayout={(data, index) => ({\n    length: ITEM_HEIGHT,\n    offset: ITEM_HEIGHT * index,\n    index,\n  })}\n  removeClippedSubviews={true}\n  maxToRenderPerBatch={10}\n  windowSize={5}\n/>\n```\n\n### Flutter Critical Rules\n\n```dart\n// ✅ CORRECT: const constructors prevent rebuilds\nclass MyWidget extends StatelessWidget {\n  const MyWidget({super.key}); // CONST!\n\n  @override\n  Widget build(BuildContext context) {\n    return const Column( // CONST!\n      children: [\n        Text(''Static content''),\n        MyConstantWidget(),\n      ],\n    );\n  }\n}\n\n// ✅ CORRECT: Targeted state with ValueListenableBuilder\nValueListenableBuilder<int>(\n  valueListenable: counter,\n  builder: (context, value, child) => Text(''$value''),\n  child: const ExpensiveWidget(), // Won''t rebuild!\n)\n```\n\n### Animation Performance\n\n```\nGPU-accelerated (FAST):     CPU-bound (SLOW):\n├── transform               ├── width, height\n├── opacity                 ├── top, left, right, bottom\n└── (use these ONLY)        ├── margin, padding\n                            └── (AVOID animating these)\n```\n\nFor complete guide: [mobile-performance.md](mobile-performance.md)\n\n---\n\n## 📝 CHECKPOINT (MANDATORY Before Any Mobile Work)\n\n> **Before writing ANY mobile code, you MUST complete this checkpoint:**\n\n```\n🧠 CHECKPOINT:\n\nPlatform:   [ iOS / Android / Both ]\nFramework:  [ React Native / Flutter / SwiftUI / Kotlin ]\nFiles Read: [ List the skill files you''ve read ]\n\n3 Principles I Will Apply:\n1. _______________\n2. _______________\n3. _______________\n\nAnti-Patterns I Will Avoid:\n1. _______________\n2. _______________\n```\n\n**Example:**\n```\n🧠 CHECKPOINT:\n\nPlatform:   iOS + Android (Cross-platform)\nFramework:  React Native + Expo\nFiles Read: touch-psychology.md, mobile-performance.md, platform-ios.md, platform-android.md\n\n3 Principles I Will Apply:\n1. FlatList with React.memo + useCallback for all lists\n2. 48px touch targets, thumb zone for primary CTAs\n3. Platform-specific navigation (edge swipe iOS, back button Android)\n\nAnti-Patterns I Will Avoid:\n1. ScrollView for lists → FlatList\n2. Inline renderItem → Memoized\n3. AsyncStorage for tokens → SecureStore\n```\n\n> 🔴 **Can''t fill the checkpoint? → GO BACK AND READ THE SKILL FILES.**\n\n---\n\n## 🔧 Framework Decision Tree\n\n```\nWHAT ARE YOU BUILDING?\n        │\n        ├── Need OTA updates + rapid iteration + web team\n        │   └── ✅ React Native + Expo\n        │\n        ├── Need pixel-perfect custom UI + performance critical\n        │   └── ✅ Flutter\n        │\n        ├── Deep native features + single platform focus\n        │   ├── iOS only → SwiftUI\n        │   └── Android only → Kotlin + Jetpack Compose\n        │\n        ├── Existing RN codebase + new features\n        │   └── ✅ React Native (bare workflow)\n        │\n        └── Enterprise + existing Flutter codebase\n            └── ✅ Flutter\n```\n\nFor complete decision trees: [decision-trees.md](decision-trees.md)\n\n---\n\n## 📋 Pre-Development Checklist\n\n### Before Starting ANY Mobile Project\n\n- [ ] **Platform confirmed?** (iOS / Android / Both)\n- [ ] **Framework chosen?** (RN / Flutter / Native)\n- [ ] **Navigation pattern decided?** (Tabs / Stack / Drawer)\n- [ ] **State management selected?** (Zustand / Redux / Riverpod / BLoC)\n- [ ] **Offline requirements known?**\n- [ ] **Deep linking planned from day one?**\n- [ ] **Target devices defined?** (Phone / Tablet / Both)\n\n### Before Every Screen\n\n- [ ] **Touch targets ≥ 44-48px?**\n- [ ] **Primary CTA in thumb zone?**\n- [ ] **Loading state exists?**\n- [ ] **Error state with retry exists?**\n- [ ] **Offline handling considered?**\n- [ ] **Platform conventions followed?**\n\n### Before Release\n\n- [ ] **console.log removed?**\n- [ ] **SecureStore for sensitive data?**\n- [ ] **SSL pinning enabled?**\n- [ ] **Lists optimized (memo, keyExtractor)?**\n- [ ] **Memory cleanup on unmount?**\n- [ ] **Tested on low-end devices?**\n- [ ] **Accessibility labels on all interactive elements?**\n\n---\n\n## 📚 Reference Files\n\nFor deeper guidance on specific areas:\n\n| File | When to Use |\n|------|-------------|\n| [mobile-design-thinking.md](mobile-design-thinking.md) | **FIRST! Anti-memorization, forces context-based thinking** |\n| [touch-psychology.md](touch-psychology.md) | Understanding touch interaction, Fitts'' Law, gesture design |\n| [mobile-performance.md](mobile-performance.md) | Optimizing RN/Flutter, 60fps, memory/battery |\n| [platform-ios.md](platform-ios.md) | iOS-specific design, HIG compliance |\n| [platform-android.md](platform-android.md) | Android-specific design, Material Design 3 |\n| [mobile-navigation.md](mobile-navigation.md) | Navigation patterns, deep linking |\n| [mobile-typography.md](mobile-typography.md) | Type scale, system fonts, accessibility |\n| [mobile-color-system.md](mobile-color-system.md) | OLED optimization, dark mode, battery |\n| [decision-trees.md](decision-trees.md) | Framework, state, storage decisions |\n\n---\n\n> **Remember:** Mobile users are impatient, interrupted, and using imprecise fingers on small screens. Design for the WORST conditions: bad network, one hand, bright sun, low battery. If it works there, it works everywhere.\n"},"lastSynced":"2026-03-07T12:54:43.974Z","agentAnalysis":{"suitability":{"en":"Perfect for Interface Agents needing touch-first and platform-respectful mobile application design capabilities.","zh":"非常适合需要触摸优先和平台尊重的移动应用程序设计能力的接口代理。","ja":"タッチファーストとプラットフォームに応じたモバイルアプリケーションデザイン機能を必要とするインターフェイスエージェントに最適。","ko":"터치 우선 및 플랫폼을 존중하는 모바일 애플리케이션 디자인 기능이 필요한 인터페이스 에이전트에 적합합니다.","es":"Perfecto para Agentes de Interfaz que necesitan capacidades de diseño de aplicaciones móviles de primera generación y respetuosas con la plataforma.","fr":"Parfait pour les Agents d''Interface ayant besoin de capacités de conception d''applications mobiles de première génération et respectueuses de la plateforme.","de":"Perfekt für Interface-Agents, die touch-first- und plattformrespektive mobile Anwendungsentwurfsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Interface que necessitam de capacidades de design de aplicativos móveis touch-first e respeitosas com a plataforma.","ru":"Идеально подходит для Интерфейсных Агентов, требующих возможностей проектирования мобильных приложений с сенсорным управлением и уважением к платформе.","ar":"مثالي لعميل واجهة يتطلب القدرات التصميم التطبيقات المحمولة الأولى والاحترام للمنصة."},"recommendation":{"en":"Empowers agents to create battery-conscious and offline-capable mobile applications using touch-first principles and platform-respectful design, leveraging scripts like mobile_audit.py for validation and ensuring compliance with mobile constraints.","zh":"赋予代理创建节电和离线能力的移动应用程序的能力，使用触摸优先原则和平台尊重的设计，利用脚本如mobile_audit.py进行验证，并确保遵守移动约束。","ja":"タッチファーストの原則とプラットフォームに応じた設計を使用して、バッテリーに優しいオフライン対応可能なモバイルアプリケーションを作成するエージェントを可能にし、mobile_audit.pyなどのスクリプトを使用して検証を行い、モバイルの制約に準拠する。","ko":"터치 우선 원칙 및 플랫폼을 존중하는 설계를 사용하여 배터리 효율과 오프라인 기능이 가능한 모바일 애플리케이션을 생성할 수 있는 에이전트를 강화하고, mobile_audit.py와 같은 스크립트를 사용하여 검증을 수행하며, 모바일 제약 조건을 준수합니다.","es":"Habilita a los agentes a crear aplicaciones móviles conscientes de la batería y capaces de funcionar sin conexión, utilizando principios de primera generación y un diseño respetuoso con la plataforma, aprovechando scripts como mobile_audit.py para la validación y garantizando el cumplimiento de las restricciones móviles.","fr":"Permet aux agents de créer des applications mobiles économes en batterie et capables de fonctionner hors ligne, en utilisant des principes de première génération et une conception respectueuse de la plateforme, en exploitant des scripts comme mobile_audit.py pour la validation et en garantissant le respect des contraintes mobiles.","de":"Ermächtigt Agents, batteriebewusste und offline-fähige mobile Anwendungen zu erstellen, die touch-first-Prinzipien und plattformrespektives Design verwenden, indem es Skripte wie mobile_audit.py für die Validierung nutzt und die Einhaltung der mobilen Einschränkungen sicherstellt.","pt":"Habilita os agentes a criar aplicativos móveis conscientes da bateria e capazes de funcionar offline, utilizando princípios de sенсорного управления e design respeitoso com a plataforma, aproveitando scripts como mobile_audit.py para validação e garantindo conformidade com as restrições móveis.","ru":"Наделяет агентов возможностью создавать мобильные приложения, экономящие заряд батареи и способные работать offline, используя принципы сенсорного управления и уважения к платформе, используя скрипты типа mobile_audit.py для валидации и обеспечения соответствия ограничениям мобильных устройств.","ar":"تمكين الوكيل من إنشاء تطبيقات محمولة واعية البطارية وقادرة على العمل بدون اتصال، باستخدام مبادئ التحكم باللمس والتصميم المحترم للمنصة، واستخدام البرامج النصية مثل mobile_audit.py للتحقق وضمان امتثال القيود المتنقلة."},"useCases":{"en":["Designing touch-first interfaces for mobile devices","Validating mobile UX and touch interactions using scripts like mobile_audit.py","Developing platform-respectful and offline-capable mobile applications"],"zh":["为移动设备设计触摸优先接口","使用脚本如mobile_audit.py验证移动UX和触摸交互","开发平台尊重和离线能力的移动应用程序"],"ja":["モバイルデバイス用のタッチファーストインターフェイスを設計する","mobile_audit.pyなどのスクリプトを使用してモバイルUXとタッチインタラクションを検証する","プラットフォームに応じたオフライン対応可能なモバイルアプリケーションを開発する"],"ko":["모바일 장치용 터치 우선 인터페이스 설계","mobile_audit.py와 같은 스크립트를 사용하여 모바일 UX 및 터치 상호 작용을 검증","플랫폼을 존중하며 오프라인 기능이 가능한 모바일 애플리케이션 개발"],"es":["Diseñar interfaces de primera generación para dispositivos móviles","Validar la experiencia del usuario móvil y las interacciones táctiles utilizando scripts como mobile_audit.py","Desarrollar aplicaciones móviles respetuosas con la plataforma y capaces de funcionar sin conexión"],"fr":["Concevoir des interfaces de première génération pour les appareils mobiles","Valider l''expérience utilisateur mobile et les interactions tactiles en utilisant des scripts comme mobile_audit.py","Développer des applications mobiles respectueuses de la plateforme et capables de fonctionner hors ligne"],"de":["Entwerfen von touch-first-Oberflächen für mobile Geräte","Validieren der mobilen Benutzeroberfläche und Touch-Interaktionen unter Verwendung von Skripten wie mobile_audit.py","Entwickeln von plattformrespektiven und offline-fähigen mobilen Anwendungen"],"pt":["Projetar interfaces touch-first para dispositivos móveis","Validar UX móvel e interações por toque usando scripts como mobile_audit.py","Desenvolver aplicativos móveis respeitosos com a plataforma e capazes de funcionar offline"],"ru":["Проектирование интерфейсов с сенсорным управлением для мобильных устройств","Проверка мобильного UX и взаимодействий с помощью скриптов типа mobile_audit.py","Разработка мобильных приложений, уважающих платформу и способных работать offline"],"ar":["تصميم واجهات التحكم باللمس لأجهزة المحمول","التحقق من UX المحمول وتفاعلات اللمس باستخدام البرامج النصية مثل mobile_audit.py","تطوير التطبيقات المحمولة المحترمة للمنصة وقادرة على العمل بدون اتصال"]},"limitations":{"en":["Requires Python environment for script execution","Specifically designed for mobile application development, not desktop"],"zh":["需要Python环境来执行脚本","专门为移动应用程序开发设计，不适用于桌面"],"ja":["スクリプトの実行にはPython環境が必要","モバイルアプリケーションの開発専用に設計されており、デスクトップには適していない"],"ko":["스크립트 실행을 위해 Python 환경이 필요","모바일 애플리케이션 개발 전용으로 설계되어 데스크톱에는 적합하지 않음"],"es":["Requiere un entorno de Python para la ejecución de scripts","Diseñado específicamente para el desarrollo de aplicaciones móviles, no de escritorio"],"fr":["Nécessite un environnement Python pour l''exécution de scripts","Conçu spécifiquement pour le développement d''applications mobiles, et non de bureau"],"de":["Benötigt eine Python-Umgebung für die Ausführung von Skripten","Speziell für die Entwicklung mobiler Anwendungen und nicht für den Desktop entwickelt"],"pt":["Requer ambiente Python para execução de scripts","Projetado especificamente para desenvolvimento de aplicativos móveis, não para desktop"],"ru":["Требует среды Python для выполнения скриптов","Разработан специально для разработки мобильных приложений, а не для настольных компьютеров"],"ar":["يتطلب بيئة Python لتشغيل البرامج النصية","تم تصميمه خصيصًا لتطوير التطبيقات المحمولة، وليس سطح المكتب"]},"version":4},"contentHash":"ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682","qualityScore":42}');
