INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jesus-bazan-entel/apolo-lms-admin/mobile-design', 'mobile-design', 'jesus-bazan-entel', 'apolo-lms-admin', 'community', 'mobile-design jesus-bazan-entel apolo-lms-admin community The mobile-design skill enables developers to create touch-first, battery-conscious, and platform-respectful mobile applications. It benefits developers working on Apolo LMS Admin projects. 移动设计系统是一种touch-first、battery-conscious、platform-respectful、offline-capable的设计哲学，帮助开发者创建优质的移动应用 モバイルデザインシステムは、タッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能な設計哲学であり、開発者が高品質のモバイルアプリを作成するのに役立ちます 모바일 디자인 시스템은 터치 우선, 배터리 최적화, 플랫폼 존중, 오프라인 가능性的 디자인 철학으로 개발자가 고품질의 모바일 앱을 생성하는 데 도움이 됩니다 Nuestro enfoque de diseño móvil para agentes de IA se centra en una filosofía de primer contacto, consciente de la batería y respetuosa con la plataforma. Incluye scripts de ejecución para validación Notre approche de conception mobile pour les agents IA repose sur une philosophie de premier contact, consciente de la batterie et respectueuse de la plateforme. Elle inclut des scripts d''exécution pour la validation Unser Ansatz für mobiles Design von KI-Agents basiert auf einer Philosophie des ersten Kontakts, der batteriebewusst und plattformrespektierend ist. Enthält Ausführungsskripte für Validierung O design móvel é uma abordagem touch-first, battery-conscious e platform-respectful para criar experiências móveis de alta qualidade Мобильный дизайн - это подход, ориентированный на осязание, экономящий батарею и уважающий платформу для создания высококачественных мобильных trải nghiệm تصميم الهاتف المحمول هو نهج يركز على اللمس، ي حفاظ على البطارية ويهتم بالمنصة لإنشاء تجارب الهاتف المحمول عالية الجودة how to use mobile-design mobile-design setup guide what is mobile-design mobile-design alternative mobile-design vs responsive design mobile-design install touch-first development platform-respectful design offline-capable mobile applications 移动设计系统 AIエージェント touch-first设计 battery-conscious优化 platform-respectful兼容性 offline-capable离线支持 Python运行时脚本 移动应用开发 Executes mobile UX and touch audits using scripts/mobile_audit.py Validates project code with python scripts/mobile_audit.py <project_path> Applies core principle that mobile is NOT a small desktop Respects platform choice and thinks mobile constraints Runs runtime scripts for validation and testing References technical documentation for mandatory reading mobile-design is a development approach focusing on touch-first, offline-capable, and platform-respectful design principles for mobile applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Dwsy/agent/tmux', 'community', 'Dwsy', 'agent', 'Dwsy/agent', 'tmux', 0, 0, 42, '2026-03-07T12:46:33.789Z', '2026-03-07T13:04:25.418Z', '93c8d137ce414cdc14dd8acd9e62edaf77bf0be07cf036f4ba8a2452d9faf5e3', '{"id":"Dwsy/agent/tmux","name":"tmux","description":{"en":"The tmux skill enables enterprise-grade code generation, analysis, and orchestration for AI agents, utilizing socket connections and configurable session management.","zh":"tmux","ja":"tmux","ko":"tmux","es":"tmux es un sistema de gestión de sesiones para agentes de inteligencia artificial que permite la creación de sesiones temporales y de larga duración","fr":"tmux est un système de gestion de sessions pour les agents d''intelligence artificielle qui permet la création de sessions temporaires et de longue durée","de":"tmux ist ein Sitzungsverwaltungssystem für KI-Agents, das die Erstellung von temporären und langfristigen Sitzungen ermöglicht","pt":"O Tmux é uma habilidade de código de nível empresarial para geração, análise e orquestração de código","ru":"Tmux - это система ИИ Агентов для генерации, анализа и оркестровки кода","ar":"tmux هو نظام وسيط ذكاء اصطناعي من الدرجة الأولى لمعالجة وتحليل وأتمتة التعليمات البرمجية"},"seo":{"title":{"en":"tmux: Setup Guide for AI Agents | AI Agent Skill","zh":"tmux_SETUP_GUIDE","ja":"tmux_BEST_PRACTICES","ko":"tmux_SETUP_TUTORIAL","es":"Guía de configuración de tmux para agentes de inteligenci...","fr":"Guide de configuration de tmux pour les agents d''intellig...","de":"Einrichtungsleitfaden für tmux in KI-Agents-Systemen","pt":"Guia de Configuração do Tmux para Desenvolvedores","ru":"Настройка Tmux для разработчиков: лучшие практики","ar":"دليل إعداد tmux لأدوات الترميز"},"description":{"en":"Unlock efficient code generation and analysis with tmux. Discover how to configure sessions, utilize socket connections, and automate workflows.","zh":"AI","ja":"AI","es":"Aprende a configurar y utilizar tmux en entornos de agentes de inteligencia artificial para una gestión de sesiones más eficiente","fr":"Découvrez comment configurer et utiliser tmux dans les environnements d''agents d''intelligence artificielle pour une gestion de sessions plus efficace","de":"Erfahren Sie, wie Sie tmux in KI-Agents-Systemen konfigurieren und nutzen können, um die Sitzungsverwaltung zu optimieren","pt":"Aprenda a configurar o Tmux para melhorar a produtividade do seu código com sessões nomeadas e persistence de dados","ru":"ИИ Агенты: узнайте, как настроить Tmux для повышения производительности кода с помощью именованных сессий и сохранения данных","ar":"تعلم كيفية إعداد tmux لتحسين إنتاجية التعليمات البرمجية مع الجلسات المسمى وتخزين البيانات"},"definition":{"en":"tmux is an enterprise-grade AI Agent system for code generation, analysis, and orchestration, utilizing private sockets and customizable session naming conventions.","zh":"tmux","ja":"tmux","ko":"tmux","es":"tmux es un sistema de gestión de sesiones que utiliza sockets y sesiones con nombres específicos para la gestión de agentes de inteligencia artificial","fr":"tmux est un système de gestion de sessions qui utilise des sockets et des sessions avec des noms spécifiques pour la gestion des agents d''intelligence artificielle","de":"tmux ist ein Sitzungsverwaltungssystem, das Sockets und Sitzungen mit spezifischen Namen für die Verwaltung von KI-Agents verwendet","pt":"O que é Tmux? É uma habilidade de código que permite a criação de sessões nomeadas e persistência de dados","ru":"Что такое Tmux? Это система, позволяющая создавать именованные сессии и сохранять данные","ar":"ما هو tmux؟ هو نظام يسمح بإنشاء جلسات مسمى وتخزين البيانات"},"features":{"en":["Utilizes private socket connections via `/tmp/pi-tmux-sockets/pi.sock`","Supports customizable session naming with categories like `task`, `service`, and `agent`","Manages session states including `running`, `idle`, and `exited`","Enables persistence via `/tmp/pi-tmux-sessions.json`","Automates cleanup of inactive sessions after 24 hours"],"zh":["Socket","Session Naming","Session States","Persistence","Auto-cleanup"],"ja":["Socket","Session Naming","Session States","Persistence","Auto-cleanup"],"ko":["Socket","Session Naming","Session States","Persistence","Auto-cleanup"],"es":["Gestión de sesiones con nombres específicos (pi-{category}-{name}-{timestamp})","Uso de sockets (private, no conflicts with personal tmux)","Estados de sesión: running, idle, exited","Persistencia de sesiones en /tmp/pi-tmux-sessions.json","Limpieza automática de sesiones inactivas después de 24h"],"fr":["Gestion de sessions avec des noms spécifiques (pi-{category}-{name}-{timestamp})","Utilisation de sockets (privé, sans conflit avec tmux personnel)","États de session : running, idle, exited","Persistance de sessions dans /tmp/pi-tmux-sessions.json","Nettoyage automatique des sessions inactives après 24h"],"de":["Sitzungsverwaltung mit spezifischen Namen (pi-{category}-{name}-{timestamp})","Verwendung von Sockets (privat, ohne Konflikte mit persönlichem tmux)","Sitzungsstatus: running, idle, exited","Persistenz von Sitzungen in /tmp/pi-tmux-sessions.json","Automatische Bereinigung von inaktiven Sitzungen nach 24h"],"pt":["Criação de sessões nomeadas com timestamp","Persistence de dados em /tmp/pi-tmux-sessions.json","Auto-cleanup de sessões inativas após 24h","Suporte a comandos CLI personalizados","Integração com sockets privados em /tmp/pi-tmux-sockets/pi.sock"],"ru":["Создание именованных сессий с timestamp","Сохранение данных в /tmp/pi-tmux-sessions.json","Автоматическое удаление неактивных сессий после 24ч","Поддержка пользовательских команд CLI","Интеграция с приватными сокетами в /tmp/pi-tmux-sockets/pi.sock"],"ar":["إنشاء جلسات مسمى مع marca de tiempo","تخزين البيانات في /tmp/pi-tmux-sessions.json","تنظيف تلقائي للجلسات غير نشطة بعد 24 ساعة","دعم أوامر CLI مخصصة","التكامل مع сокеты خاصة في /tmp/pi-tmux-sockets/pi.sock"]},"keywords":{"en":["how to use tmux with AI agents","tmux setup guide for developers","what is tmux in AI development","tmux vs screen for code generation","tmux install for Linux systems","tmux configuration for enterprise-grade AI"],"zh":["tmux","AI","CLI","Socket","Session Naming","Session States","Persistence","Auto-cleanup"],"ja":["tmux","AI","CLI","Socket","Session Naming","Session States","Persistence","Auto-cleanup"],"ko":["tmux","","CLI","Socket","Session Naming","Session States","Persistence","Auto-cleanup"],"es":["tmux para agentes de inteligencia artificial","gestión de sesiones en entornos de inteligencia artificial","configuración de tmux para KI","agentes de inteligencia artificial y tmux","sessión de tmux en KI","sockets en tmux para KI"],"fr":["tmux pour les agents d''intelligence artificielle","gestion de sessions dans les environnements d''intelligence artificielle","configuration de tmux pour les agents d''IA","agents d''intelligence artificielle et tmux","session tmux dans les environnements d''IA","sockets dans tmux pour les agents d''IA"],"de":["tmux für KI-Agents","Sitzungsverwaltung in KI-Umgebungen","Konfiguration von tmux für KI-Systeme","KI-Agents und tmux","tmux-Sitzung in KI-Systemen","Sockets in tmux für KI-Agents"],"pt":["tmux","desenvolvimento de código","geração de código","análise de código","orquestração de código","sessões nomeadas","persistence de dados","comandos CLI","sockets privados"],"ru":["Tmux","разработка кода","генерация кода","анализ кода","оркестровка кода","именованные сессии","сохранение данных","команды CLI","приватные сокеты","ИИ Агенты"],"ar":["tmux","تطوير التعليمات البرمجية","معالجة التعليمات البرمجية","تحليل التعليمات البرمجية","أتمتة التعليمات البرمجية","جلسات مسمى","تخزين البيانات","أوامر CLI","سوكيتات خاصة","أدوات الذكاء الاصطناعي"]}},"owner":"Dwsy","repo":"agent","repoPath":"Dwsy/agent","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.789Z","topics":[],"category":"community","skillMd":{"name":"tmux","description":"Remote control tmux sessions for interactive CLIs, background tasks, and services.","bodyPreview":"# tmux Skill\n\n## Core Concepts\n\n**Socket**: `/tmp/pi-tmux-sockets/pi.sock` (private, no conflicts with personal tmux)\n\n**Session Naming**: `pi-{category}-{name}-{timestamp}`\n- Categories: `task` (temporary), `service` (long-running), `agent` (agent-specific)\n\n**Session States**: `running` | `idle` | `exited`\n\n**Persistence**: `/tmp/pi-tmux-sessions.json`\n\n**Auto-cleanup**: Inactive sessions > 24h removed (configurable)\n\n## CLI Commands\n\n```bash\nbun ~/.pi/agent/skills/tmux/lib.ts <command>\n\ncreat","body":"# tmux Skill\n\n## Core Concepts\n\n**Socket**: `/tmp/pi-tmux-sockets/pi.sock` (private, no conflicts with personal tmux)\n\n**Session Naming**: `pi-{category}-{name}-{timestamp}`\n- Categories: `task` (temporary), `service` (long-running), `agent` (agent-specific)\n\n**Session States**: `running` | `idle` | `exited`\n\n**Persistence**: `/tmp/pi-tmux-sessions.json`\n\n**Auto-cleanup**: Inactive sessions > 24h removed (configurable)\n\n## CLI Commands\n\n```bash\nbun ~/.pi/agent/skills/tmux/lib.ts <command>\n\ncreate <name> <command> [category]    # Create session, prints monitoring command\nlist [filter]                         # List sessions with status\nstatus <id>                           # Session details\nsend <id> <keys>                      # Send keystrokes (literal mode, safe)\ncapture <id> [lines]                  # Capture pane output (default: 200)\nkill <id>                             # Terminate session\ncleanup [hours]                       # Remove old sessions (default: 24h)\nattach <id>                           # Print attach command\nsync                                  # Sync session state with tmux\n```\n\n**TUI**: `bun ~/.pi/agent/skills/tmux/tui.ts` (visual management, shortcuts: r/n/c/s/a/k/q)\n\n## TypeScript API\n\n```typescript\nimport { TmuxManager } from \"~/.pi/agent/skills/tmux/lib.ts\";\n\nconst tmux = new TmuxManager({ autoCleanup: false }); // optional config\n\n// Session lifecycle\nconst session = await tmux.createSession(name, command, category);\nawait tmux.killSession(session.id);\n\n// Output handling\nconst output = await tmux.capturePane(target, lines);\nconst success = await tmux.waitForText(target, pattern, { timeout: 60 });\n\n// State management\nconst sessions = await tmux.listSessions(filter);\nconst status = await tmux.getSessionStatus(id);\nawait tmux.sync();\nawait tmux.cleanup(hours);\n```\n\n## Key Rules\n\n1. **Always print monitoring command** after session creation:\n   ```\n   tmux -S /tmp/pi-tmux-sockets/pi.sock attach -t {session-id}\n   ```\n\n2. **Use `send` for interactive tools** (Python REPL, gdb, databases):\n   ```bash\n   # Python REPL: always use PYTHON_BASIC_REPL=1\n   bun ~/.pi/agent/skills/tmux/lib.ts create python \"PYTHON_BASIC_REPL=1 python3 -q\" task\n   bun ~/.pi/agent/skills/tmux/lib.ts send pi-task-python-* \"print(''Hello'')\"\n   ```\n\n3. **Category selection**:\n   - `task`: compilation, testing, temporary operations\n   - `service`: dev servers, databases, persistent services\n   - `agent`: training, data processing, agent-specific tasks\n\n4. **Safe key injection**: `send` uses literal mode (`-l`), no shell escaping needed\n\n5. **Session recovery**: Run `sync` if session not found\n\n## Helper Scripts\n\n```bash\n# Wait for text pattern with timeout\n./scripts/wait-for-text.sh -t session:0.0 -p ''pattern'' [-F] [-T 20] [-i 0.5] [-l 2000]\n\n# List sessions with metadata\n./scripts/find-sessions.sh -S \"$SOCKET\"\n./scripts/find-sessions.sh --all\n```\n\n## Requirements\n\n- tmux (Linux/macOS)\n- Bun runtime\n- Bash (helper scripts)"},"lastSynced":"2026-03-07T13:04:25.418Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents needing robust session management and code orchestration via socket connections.","zh":"适用于需要通过 socket 连接进行强大的会话管理和代码编排的高级 AI 代理。","ja":"ソケット接続を介した強力なセッション管理とコードオーケストレーションを必要とする高度な AI エージェントに最適です。","ko":"소켓 연결을 통해 강력한 세션 관리 및 코드 오케스트레이션을 필요한 고급 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA Avanzados que necesitan una gestión de sesión robusta y orquestación de código a través de conexiones de socket.","fr":"Parfait pour les Agents d''IA Avancés nécessitant une gestion de session robuste et une orchestration de code via des connexions de socket.","de":"Perfekt für erweiterte KI-Agenten, die eine robuste Sitzungsverwaltung und Codeorchestrierung über Socket-Verbindungen benötigen.","pt":"Perfeito para Agentes de IA Avançados que precisam de gerenciamento de sessão robusto e orquestração de código via conexões de socket.","ru":"Идеально подходит для продвинутых агентов ИИ, которым необходим надежный менеджмент сессий и оркестрация кода через соединения сокета.","ar":"مثالي للوكلاء الذكاء الاصطناعي المتقدم الذين يحتاجون إلى إدارة جلسة قوية وتنسيق رمز عبر اتصالات сокيت."},"recommendation":{"en":"Empowers agents to manage configurable sessions using socket connections, with features like auto-cleanup of inactive sessions and persistence via JSON files, leveraging protocols like socket connections and file formats like JSON.","zh":"赋予代理管理可配置的会话使用 socket 连接的能力，具有自动清理不活动会话和通过 JSON 文件实现持久化等功能，利用 socket 连接和 JSON 等协议以及文件格式。","ja":"ソケット接続を使用して構成可能なセッションを管理するエージェントの機能を強化し、自動的に非アクティブなセッションをクリーンアップしたり、JSON ファイルを介して永続化したりする機能を提供し、ソケット接続や JSON などのプロトコルやファイル形式を利用します。","ko":"에이전트가 소켓 연결을 사용하여 구성 가능한 세션을 관리할 수 있는 기능을 제공하며, 자동으로 비활성 세션을 정리하거나 JSON 파일을 통해 지속성을 제공하는 기능을 제공하며, 소켓 연결 및 JSON과 같은 프로토콜 및 파일 형식을 활용합니다.","es":"Habilita a los agentes a gestionar sesiones configurables utilizando conexiones de socket, con características como la limpieza automática de sesiones inactivas y persistencia a través de archivos JSON, aprovechando protocolos como conexiones de socket y formatos de archivo como JSON.","fr":"Permet aux agents de gérer des sessions configurables en utilisant des connexions de socket, avec des fonctionnalités comme la suppression automatique des sessions inactives et la persistance via des fichiers JSON, en exploitant des protocoles comme les connexions de socket et des formats de fichier comme JSON.","de":"Ermächtigt Agenten, konfigurierbare Sitzungen über Socket-Verbindungen zu verwalten, mit Funktionen wie der automatischen Bereinigung inaktiver Sitzungen und der Persistenz über JSON-Dateien, unter Ausnutzung von Protokollen wie Socket-Verbindungen und Dateiformaten wie JSON.","pt":"Permite que os agentes gerenciem sessões configuráveis usando conexões de socket, com recursos como limpeza automática de sessões inativas e persistência via arquivos JSON, aproveitando protocolos como conexões de socket e formatos de arquivo como JSON.","ru":"Позволяет агентам управлять настраиваемыми сессиями с помощью соединений сокета, с функциями, такими как автоматическая очистка неактивных сессий и сохранение через файлы JSON, используя протоколы, такие как соединения сокета, и форматы файлов, такие как JSON.","ar":"يمكن للوكلاء إدارة الجلسات القابلة للتكوين باستخدام اتصالات السوكت، مع ميزات مثل تنظيف الجلسات غير النشطة تلقائيًا والاستمرار عبر ملفات JSON، واستخدام بروتوكولات مثل اتصالات السوكت وتنسيقات الملفات مثل JSON."},"useCases":{"en":["Automating temporary task sessions with idle and exited states","Orchestrating long-running service sessions with configurable persistence","Managing agent-specific sessions using private socket connections"],"zh":["自动化具有空闲和退出状态的临时任务会话","编排具有可配置持久性的长期运行服务会话","使用私有 socket 连接管理特定于代理的会话"],"ja":["アイドル状態と終了状態を持つ一時的なタスクセッションの自動化","構成可能な永続性を持つ長時間実行サービスセッションのオーケストレーション","プライベートソケット接続を使用してエージェント固有のセッションを管理"],"ko":["유휴 상태 및 종료 상태가 있는 임시 작업 세션 자동화","구성 가능한 지속성을 갖는 장기 실행 서비스 세션 오케스트레이션","개인 소켓 연결을 사용하여 에이전트별 세션 관리"],"es":["Automatización de sesiones de tareas temporales con estados inactivos y salidos","Orquestación de sesiones de servicio de larga duración con persistencia configurable","Gestión de sesiones específicas del agente utilizando conexiones de socket privadas"],"fr":["Automatisation de sessions de tâches temporaires avec états inactifs et sortis","Orchestration de sessions de service à longue durée avec persistance configurable","Gestion de sessions spécifiques à l''agent en utilisant des connexions de socket privées"],"de":["Automatisierung von Sitzungen für temporäre Aufgaben mit inaktiven und beendeten Zuständen","Orchestrierung von Sitzungen für lang laufende Dienste mit konfigurierbarer Persistenz","Verwaltung von agentenspezifischen Sitzungen unter Verwendung privater Socket-Verbindungen"],"pt":["Automatizar sessões de tarefas temporárias com estados de ociosidade e saída","Orquestrar sessões de serviço de longa duração com persistência configurável","Gerenciar sessões específicas do agente usando conexões de socket privadas"],"ru":["Автоматизировать временные сессии задач с состояниями простоя и выхода","Оркестрировать長ные сессии служб с настраиваемой сохранностью","Управлять сессиями, специфичными для агента, с помощью приватных соединений сокета"],"ar":["تحويل جلسات المهام المؤقتة مع حالات الخمول والإنهاء إلى自动","تنسيق جلسات الخدمة الطويلة مع الاستمرارية القابلة للتكوين","إدارة الجلسات الخاصة بالوكيل باستخدام اتصالات السوكت الخاصة"]},"limitations":{"en":["Requires access to the filesystem for socket connections and session persistence","Limited to sessions with a maximum inactivity of 24 hours before auto-cleanup","Dependent on the availability of the /tmp directory for socket and session files"],"zh":["需要访问文件系统以进行 socket 连接和会话持久化","仅限会话在 24 小时的最大非活动时间后自动清理","依赖于 /tmp 目录的可用性以用于 socket 和会话文件"],"ja":["ソケット接続とセッションの永続化のためにファイルシステムへのアクセスが必要","24 時間の最大非アクティブ時間後自动的にクリーンアップされるセッションに限定","/tmp ディレクトリの可用性に依存してソケットとセッションファイルに使用"],"ko":["소켓 연결 및 세션 지속성을 위해 파일 시스템에 대한 액세스가 필요합니다.","24시간의 최대 비활성 시간 후에 자동으로 정리되는 세션으로 제한됩니다.","소켓 및 세션 파일에 사용하기 위해 /tmp 디렉토리의 가용성에 의존합니다."],"es":["Requiere acceso al sistema de archivos para conexiones de socket y persistencia de sesión","Limitado a sesiones con un máximo de inactividad de 24 horas antes de la limpieza automática","Dependiente de la disponibilidad del directorio /tmp para archivos de socket y sesión"],"fr":["Nécessite un accès au système de fichiers pour les connexions de socket et la persistance de session","Limité aux sessions avec un maximum d''inactivité de 24 heures avant la suppression automatique","Dépend de la disponibilité du répertoire /tmp pour les fichiers de socket et de session"],"de":["Benötigt Zugriff auf das Dateisystem für Socket-Verbindungen und Sitzungspersistenz","Begrenzt auf Sitzungen mit einer maximalen Inaktivität von 24 Stunden vor der automatischen Bereinigung","Abhängig von der Verfügbarkeit des Verzeichnisses /tmp für Socket- und Sitzungsdateien"],"pt":["Requer acesso ao sistema de arquivos para conexões de socket e persistência de sessão","Limitado a sessões com um período máximo de inatividade de 24 horas antes da limpeza automática","Dependente da disponibilidade do diretório /tmp para arquivos de socket e sessão"],"ru":["Требует доступа к файловой системе для соединений сокета и сохранности сессий","Ограничен сессиями с максимальным периодом неактивности 24 часа до автоматической очистки","Зависит от наличия директории /tmp для файлов сокета и сессий"],"ar":["يتطلب الوصول إلى نظام الملفات لاتصالات السوكت واستمرار الجلسة","محدود بالجلسات التي تتمتع بفترة خمول قصوى تبلغ 24 ساعة قبل التنظيف التلقائي","يعتمد على توافر دليل /tmp لملفات السوكت والجلسة"]},"version":4},"contentHash":"93c8d137ce414cdc14dd8acd9e62edaf77bf0be07cf036f4ba8a2452d9faf5e3","qualityScore":42}');
