INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dwsy/agent/tmux', 'tmux', 'Dwsy', 'agent', 'community', 'tmux Dwsy agent community The tmux skill enables enterprise-grade code generation, analysis, and orchestration for AI agents, utilizing socket connections and configurable session management. tmux tmux tmux tmux es un sistema de gestión de sesiones para agentes de inteligencia artificial que permite la creación de sesiones temporales y de larga duración tmux est un système de gestion de sessions pour les agents d''intelligence artificielle qui permet la création de sessions temporaires et de longue durée tmux ist ein Sitzungsverwaltungssystem für KI-Agents, das die Erstellung von temporären und langfristigen Sitzungen ermöglicht O Tmux é uma habilidade de código de nível empresarial para geração, análise e orquestração de código Tmux - это система ИИ Агентов для генерации, анализа и оркестровки кода tmux هو نظام وسيط ذكاء اصطناعي من الدرجة الأولى لمعالجة وتحليل وأتمتة التعليمات البرمجية how to use tmux with AI agents tmux setup guide for developers what is tmux in AI development tmux vs screen for code generation tmux install for Linux systems tmux configuration for enterprise-grade AI tmux AI CLI Socket Session Naming Session States Persistence Auto-cleanup Utilizes private socket connections via `/tmp/pi-tmux-sockets/pi.sock` Supports customizable session naming with categories like `task`, `service`, and `agent` Manages session states including `running`, `idle`, and `exited` Enables persistence via `/tmp/pi-tmux-sessions.json` Automates cleanup of inactive sessions after 24 hours tmux is an enterprise-grade AI Agent system for code generation, analysis, and orchestration, utilizing private sockets and customizable session naming conventions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yu-iskw/lightdash-tools/openspec-explore', 'community', 'yu-iskw', 'lightdash-tools', 'yu-iskw/lightdash-tools', 'openspec-explore', 0, 0, 42, '2026-03-05T06:20:06.215Z', '2026-03-05T07:11:36.469Z', '37cb96a8ba4c1f65d3a79e3a2636f1367325e7dbc815e9519c2c5d46d346ce15', '{"id":"yu-iskw/lightdash-tools/openspec-explore","name":"openspec-explore","description":{"zh":"openspec-explore AI工具提供Lightdash工具集，包括HTTP客户端、CLI、MCP等，帮助开发者提高开发效率","ja":"openspec-explore AIエージェントは、Lightdashツール（HTTPクライアント、CLI、MCPなど）を提供し、開発者が開発効率を向上させることができます","ko":"openspec-explore AI 에이전트는 Lightdash 도구를 제공합니다. HTTP 클라이언트, CLI, MCP 등이 포함되어 있습니다. 개발자들이 개발 효율성을 높일 수 있습니다.","es":"Openspec-explore es una colección de herramientas de Lightdash, incluyendo cliente HTTP, CLI, MCP y más, para mejorar tu desarrollo con AI Agent.","fr":"Openspec-explore est un ensemble d''outils de Lightdash, notamment le client HTTP, la CLI, le MCP et plus, pour améliorer votre développement avec l''Agent IA.","de":"Openspec-explore ist eine Sammlung von Lightdash-Tools, einschließlich HTTP-Client, CLI, MCP und mehr, um Ihre Entwicklung mit AI-Tool-Agents zu verbessern.","pt":"O openspec-explore é uma ferramenta de AI que oferece uma variedade de recursos, incluindo um cliente HTTP, CLI e MCP, para ajudar os desenvolvedores a melhorar a produtividade","ru":"ИИ Агент openspec-explore предлагает набор инструментов, включая HTTP-клиент, CLI и MCP, для повышения производительности разработчиков","ar":"وکیل الذكاء الاصطناعي openspec-explore يقدم مجموعة من الميزات، بما في ذلك عميل HTTP و CLI و MCP، لمساعدة المطورين على تحسين الإنتاجية","en":"Lightdash tools (HTTP client, CLI, MCP and more)"},"seo":{"title":{"zh":"AI工具openspec-explore：Lightdash工具集","ja":"AIエージェントopenspec-explore：Lightdashツール","ko":"AI 에이전트 openspec-explore: Lightdash 도구","es":"Herramientas de openspec-explore: Descubre Lightdash","fr":"Outils openspec-explore: Découvrez Lightdash","de":"Openspec-Explore-Tools: Entdecken Sie Lightdash","pt":"Ferramentas de AI: openspec-explore com Lightdash","ru":"ИИ Агенты: openspec-explore с инструментами Lightdash","ar":"أدوات الذكاء الاصطناعي: openspec-explore مع Lightdash","en":"openspec-explore"},"description":{"zh":"openspec-explore AI工具提供Lightdash工具集，包括HTTP客户端、CLI、MCP等，帮助开发者提高开发效率","ja":"openspec-explore AIエージェントは、Lightdashツール（HTTPクライアント、CLI、MCPなど）を提供し、開発者が開発効率を向上させることができます","ko":"openspec-explore AI 에이전트는 Lightdash 도구를 제공합니다. HTTP 클라이언트, CLI, MCP 등이 포함되어 있습니다. 개발자들이 개발 효율성을 높일 수 있습니다.","es":"Openspec-explore es una colección de herramientas de Lightdash, incluyendo cliente HTTP, CLI, MCP y más, para mejorar tu desarrollo con AI Agent.","fr":"Openspec-explore est un ensemble d''outils de Lightdash, notamment le client HTTP, la CLI, le MCP et plus, pour améliorer votre développement avec l''Agent IA.","de":"Openspec-explore ist eine Sammlung von Lightdash-Tools, einschließlich HTTP-Client, CLI, MCP und mehr, um Ihre Entwicklung mit AI-Tool-Agents zu verbessern.","pt":"O openspec-explore é uma ferramenta de AI que oferece uma variedade de recursos, incluindo um cliente HTTP, CLI e MCP, para ajudar os desenvolvedores a melho...","ru":"ИИ Агент openspec-explore предлагает набор инструментов, включая HTTP-клиент, CLI и MCP, для повышения производительности разработчиков","ar":"وکیل الذكاء الاصطناعي openspec-explore يقدم مجموعة من الميزات، بما في ذلك عميل HTTP و CLI و MCP، لمساعدة المطورين على تحسين الإنتاجية","en":"Lightdash tools (HTTP client, CLI, MCP and more)"},"definition":{"en":"Lightdash tools (HTTP client, CLI, MCP and more)"},"features":{"zh":["Lightdash工具集","HTTP客户端","CLI","MCP","提高开发效率"],"ja":["Lightdashツール","HTTPクライアント","CLI","MCP","開発効率の向上"],"ko":["Lightdash 도구","HTTP 클라이언트","CLI","MCP","개발 효율성 향상"],"es":["Cliente HTTP para solicitudes","Interfaz de línea de comandos (CLI) para scripts","MCP para la gestión de datos","Herramientas de desarrollo para AI Agent","Integración con Lightdash"],"fr":["Client HTTP pour les requêtes","Interface de ligne de commande (CLI) pour les scripts","MCP pour la gestion des données","Outils de développement pour l''Agent IA","Intégration avec Lightdash"],"de":["HTTP-Client für Anfragen","Kommandozeileninterface (CLI) für Skripte","MCP für die Datenverwaltung","Entwicklungstools für AI-Tool-Agents","Integration mit Lightdash"],"pt":["Cliente HTTP para requisições de API","CLI para automação de tarefas","MCP para gerenciamento de projetos","Integração com ferramentas de desenvolvimento","Suporte a múltiplos protocolos de comunicação"],"ru":["HTTP-клиент для запросов API","CLI для автоматизации задач","MCP для управления проектами","Интеграция с инструментами разработки","Поддержка нескольких протоколов связи"],"ar":["عميل HTTP لطلبات API","CLI للآليّة التلقائية للمهام","MCP لإدارة المشاريع","التكامل مع أدوات التطوير","دعم بروتوكولات الاتصال المتعددة"]},"keywords":{"zh":["如何使用Lightdash工具","什么是openspec-explore AI工具","Lightdash工具替代品","openspec-explore AI工具安装","Lightdash工具设置指南","openspec-explore AI工具与其他工具的比较"],"ja":["Lightdashツールの使い方","openspec-explore AIエージェントとは","Lightdashツールの代替","openspec-explore AIエージェントのインストール","Lightdashツールの設定ガイド","openspec-explore AIエージェントと他のツールの比較"],"ko":["Lightdash 도구 사용 방법","openspec-explore AI 에이전트란","Lightdash 도구 대안","openspec-explore AI 에이전트 설치","Lightdash 도구 설정 가이드","openspec-explore AI 에이전트와 다른 도구의 비교"],"es":["cómo usar Lightdash","qué es AI Agent","alternativas a Lightdash","Lightdash vs Tableau","instalar Lightdash","guía de configuración de Lightdash","desarrollo con AI Agent","herramientas de desarrollo para AI"],"fr":["comment utiliser Lightdash","qu''est-ce que l''Agent IA","alternatives à Lightdash","Lightdash vs Tableau","installer Lightdash","guide de configuration de Lightdash","développement avec l''Agent IA","outils de développement pour l''IA"],"de":["wie man Lightdash verwendet","was ist AI-Tool-Agent","Alternativen zu Lightdash","Lightdash vs Tableau","Lightdash installieren","Konfigurationshandbuch für Lightdash","Entwicklung mit AI-Tool- Agents","Entwicklungstools für künstliche Intelligenz"],"pt":["como usar openspec-explore","o que é openspec-explore","ferramentas de AI para desenvolvedores","alternativas para openspec-explore","openspec-explore vs outras ferramentas","instalação do openspec-explore","guia de configuração do openspec-explore"],"ru":["как использовать openspec-explore","что такое openspec-explore","инструменты ИИ для разработчиков","альтернативы openspec-explore","openspec-explore vs другие инструменты","установка openspec-explore","руководство по настройке openspec-explore"],"ar":["كيفية استخدام openspec-explore","ما هو openspec-explore","أدوات الذكاء الاصطناعي للمطورين","بديلات ل.openspec-explore","openspec-explore مقابل أدوات أخرى","تثبيت openspec-explore","دليل إعداد openspec-explore"]}},"owner":"yu-iskw","repo":"lightdash-tools","repoPath":"yu-iskw/lightdash-tools","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.215Z","topics":[],"category":"community","skillMd":{"name":"openspec-explore","description":"Enter explore mode - a thinking partner for exploring ideas, investigating problems, and clarifying requirements. Use when the user wants to think through something before or during a change.","version":"1.0","bodyPreview":"# OpenSpec Explore\n\nEnter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if th","body":"# OpenSpec Explore\n\nEnter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s capturing thinking, not implementing.\n\n**This is a stance, not a workflow.** There are no fixed steps, no required sequence, no mandatory outputs. You''re a thinking partner helping the user explore.\n\n---\n\n## The Stance\n\n- **Curious, not prescriptive** - Ask questions that emerge naturally, don''t follow a script\n- **Open threads, not interrogations** - Surface multiple interesting directions and let the user follow what resonates. Don''t funnel them through a single path of questions.\n- **Visual** - Use ASCII diagrams liberally when they''d help clarify thinking\n- **Adaptive** - Follow interesting threads, pivot when new information emerges\n- **Patient** - Don''t rush to conclusions, let the shape of the problem emerge\n- **Grounded** - Explore the actual codebase when relevant, don''t just theorize\n\n---\n\n## What You Might Do\n\nDepending on what the user brings, you might:\n\n**Explore the problem space**\n\n- Ask clarifying questions that emerge from what they said\n- Challenge assumptions\n- Reframe the problem\n- Find analogies\n\n**Investigate the codebase**\n\n- Map existing architecture relevant to the discussion\n- Find integration points\n- Identify patterns already in use\n- Surface hidden complexity\n\n**Compare options**\n\n- Brainstorm multiple approaches\n- Build comparison tables\n- Sketch tradeoffs\n- Recommend a path (if asked)\n\n**Visualize**\n\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│   ┌────────┐         ┌────────┐        │\n│   │ State  │────────▶│ State  │        │\n│   │   A    │         │   B    │        │\n│   └────────┘         └────────┘        │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**\n\n- Identify what could go wrong\n- Find gaps in understanding\n- Suggest spikes or investigations\n\n---\n\n## OpenSpec Awareness\n\nYou have full context of the OpenSpec system. Use it naturally, don''t force it.\n\n### Check for context\n\nAt the start, quickly check what exists:\n\n```bash\ncd docs && openspec list --json\n```\n\nThis tells you:\n\n- If there are active changes\n- Their names, schemas, and status\n- What the user might be working on\n\n### When no change exists\n\nThink freely. When insights crystallize, you might offer:\n\n- \"This feels solid enough to start a change. Want me to create one?\"\n  → Can transition to `/opsx:new` or `/opsx:ff`\n- Or keep exploring - no pressure to formalize\n\n### When a change exists\n\nIf the user mentions a change or you detect one is relevant:\n\n1. **Read existing artifacts for context**\n   - `docs/openspec/changes/<name>/proposal.md`\n   - `docs/openspec/changes/<name>/design.md`\n   - `docs/openspec/changes/<name>/tasks.md`\n   - etc.\n\n2. **Reference them naturally in conversation**\n   - \"Your design mentions using Redis, but we just realized SQLite fits better...\"\n   - \"The proposal scopes this to premium users, but we''re now thinking everyone...\"\n\n3. **Offer to capture when decisions are made**\n\n   | Insight Type               | Where to Capture             |\n   | -------------------------- | ---------------------------- |\n   | New requirement discovered | `specs/<capability>/spec.md` |\n   | Requirement changed        | `specs/<capability>/spec.md` |\n   | Design decision made       | `design.md`                  |\n   | Scope changed              | `proposal.md`                |\n   | New work identified        | `tasks.md`                   |\n   | Assumption invalidated     | Relevant artifact            |\n\n   Example offers:\n   - \"That''s a design decision. Capture it in design.md?\"\n   - \"This is a new requirement. Add it to specs?\"\n   - \"This changes scope. Update the proposal?\"\n\n4. **The user decides** - Offer and move on. Don''t pressure. Don''t auto-capture.\n\n---\n\n## What You Don''t Have To Do\n\n- Follow a script\n- Ask the same questions every time\n- Produce a specific artifact\n- Reach a conclusion\n- Stay on topic if a tangent is valuable\n- Be brief (this is thinking time)\n\n---\n\n## Handling Different Entry Points\n\n**User brings a vague idea:**\n\n```\nUser: I''m thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where''s your head at?\n```\n\n**User brings a specific problem:**\n\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one''s burning?\n```\n\n**User is stuck mid-implementation:**\n\n```\nUser: /opsx:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You''re on task 4: \"Implement OAuth flow\"\n\n     Let me trace what''s involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What''s the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │         CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery\n\nThere''s no required ending. Discovery might:\n\n- **Flow into action**: \"Ready to start? /opsx:new or /opsx:ff\"\n- **Result in artifact updates**: \"Updated design.md with these decisions\"\n- **Just provide clarity**: User has what they need, moves on\n- **Continue later**: \"We can pick this up anytime\"\n\nWhen it feels like things are crystallizing, you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change: /opsx:new <name>\n- Fast-forward to tasks: /opsx:ff <name>\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional. Sometimes the thinking IS the value.\n\n---\n\n## Guardrails\n\n- **Don''t implement** - Never write code or implement features. Creating OpenSpec artifacts is fine, writing application code is not.\n- **Don''t fake understanding** - If something is unclear, dig deeper\n- **Don''t rush** - Discovery is thinking time, not task time\n- **Don''t force structure** - Let patterns emerge naturally\n- **Don''t auto-capture** - Offer to save insights, don''t just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions** - Including the user''s and your own\n"},"lastSynced":"2026-03-05T07:11:36.469Z","agentAnalysis":{"suitability":{"en":"Perfect for Analysis Agents needing comprehensive content analysis and exploration capabilities via Lightdash tools and OpenSpec artifacts","zh":"非常适合需要通过Lightdash工具和OpenSpec文档进行全面内容分析和探索的分析代理","ja":"LightdashツールとOpenSpecアーティファクトを使用した包括的なコンテンツ分析および探索機能が必要な分析エージェントに最適","ko":"Lightdash 도구 및 OpenSpec 아티팩트를 통해 종합적인 콘텐츠 분석 및 탐색 기능이 필요한 분석 에이전트에 적합","es":"Perfecto para Agentes de Análisis que necesitan capacidades de análisis y exploración de contenido integral a través de herramientas de Lightdash y artefactos de OpenSpec","fr":"Parfait pour les Agents d''Analyse ayant besoin d''une analyse et d''une exploration de contenu complètes via les outils Lightdash et les artefacts OpenSpec","de":"Perfekt für Analyseagenten, die umfassende Inhaltsanalyse- und Explorationsfunktionen über Lightdash-Tools und OpenSpec-Artefakte benötigen","pt":"Perfeito para Agentes de Análise que necessitam de capacidades de análise e exploração de conteúdo abrangentes via ferramentas Lightdash e artefatos OpenSpec","ru":"Идеально подходит для Агентов Анализа, которым необходимы всесторонние возможности анализа и изучения контента с помощью инструментов Lightdash и артефактов OpenSpec","ar":"مثالي لعميل التحليل الذي يحتاج إلى возможности تحليل ومسح محتوى شاملة من خلال أدوات Lightdash وملحقات OpenSpec"},"recommendation":{"en":"Empowers agents to deeply explore and visualize codebases using HTTP clients, CLI, and MCP, while creating OpenSpec proposals, designs, and specs, all within a conversation-driven interface leveraging protocols and file formats","zh":"赋予代理深入探索和可视化代码库的能力，使用HTTP客户端、CLI和MCP，同时创建OpenSpec提案、设计和规格，所有这些都在一个对话驱动的接口中，利用协议和文件格式","ja":"HTTPクライアント、CLI、MCPを使用してコードベースを深く探索および視覚化する能力をエージェントに与え、OpenSpecの提案、設計、仕様をすべて会話駆動のインターフェースで作成し、プロトコルとファイル形式を利用する","ko":"HTTP 클라이언트, CLI 및 MCP를 사용하여 코드베이스를 깊이 탐색하고 시각화하는 능력을 에이전트에게 부여하며, OpenSpec 제안, 설계 및 사양을 모두 대화형 인터페이스에서 생성하고, 프로토콜 및 파일 형식을 활용","es":"Habilita a los agentes a explorar y visualizar profundamente las bases de código utilizando clientes HTTP, CLI y MCP, mientras crea propuestas, diseños y especificaciones de OpenSpec, todo dentro de una interfaz impulsada por conversaciones que aprovecha protocolos y formatos de archivo","fr":"Permet aux agents d''explorer et de visualiser en profondeur les bases de code en utilisant des clients HTTP, CLI et MCP, tout en créant des propositions, des conceptions et des spécifications OpenSpec, le tout dans une interface pilotée par conversation qui exploite les protocoles et les formats de fichier","de":"Ermächtigt Agenten, Codebasen mithilfe von HTTP-Clients, CLI und MCP tief zu erkunden und zu visualisieren, während sie OpenSpec-Vorschläge, Entwürfe und Spezifikationen erstellen, all dies innerhalb einer konversationsgesteuerten Schnittstelle, die Protokolle und Dateiformate nutzt","pt":"Habilita agentes a explorar profundamente e visualizar codebases usando clientes HTTP, CLI e MCP, enquanto criam propostas, designs e specs OpenSpec, tudo dentro de uma interface impulsionada por conversas que aproveita protocolos e formatos de arquivo","ru":"Позволяет агентам глубоко исследовать и визуализировать кодовые базы с помощью клиентов HTTP, CLI и MCP, а также создавать предложения, дизайны и спецификации OpenSpec, все в рамках интерфейса, управляемого разговорами, который использует протоколы и форматы файлов","ar":"يمنح العميل khảية استكشاف وفهم شفرات البرامج بعمق باستخدام عملاء HTTP و CLI و MCP، مع создания مقترحات وتصاميم ومواصفات OpenSpec، كل ذلك في واجهة مدعومة بالحوار التي تعتمد على بروتوكولات وصيغ الملفات"},"useCases":{"en":["Exploring codebases for dependency analysis","Generating OpenSpec artifacts for proposal development","Investigating codebase issues without modifying code"],"zh":["探索代码库以进行依赖关系分析","为提案开发生成OpenSpec文档","在不修改代码的情况下调查代码库问题"],"ja":["依存関係分析のためのコードベースの探索","提案開発のためのOpenSpecアーティファクトの生成","コードの変更せずにコードベースの問題を調査する"],"ko":["의존성 분석을 위한 코드베이스 탐색","제안 개발을 위한 OpenSpec 아티팩트 생성","코드를 수정하지 않고 코드베이스 문제 조사"],"es":["Explorar bases de código para análisis de dependencias","Generar artefactos de OpenSpec para el desarrollo de propuestas","Investigar problemas de base de código sin modificar el código"],"fr":["Explorer les bases de code pour l''analyse des dépendances","Générer des artefacts OpenSpec pour le développement de propositions","Enquêter sur les problèmes de base de code sans modifier le code"],"de":["Codebasen für Abhängigkeitsanalysen erkunden","OpenSpec-Artefakte für die Entwicklung von Vorschlägen generieren","Codebasen-Probleme ohne Code-Modifikationen untersuchen"],"pt":["Explorar codebases para análise de dependências","Gerar artefatos OpenSpec para desenvolvimento de propostas","Investigar problemas de codebase sem modificar o código"],"ru":["Изучение кодовых баз для анализа зависимостей","Генерация артефактов OpenSpec для разработки предложений","Изучение проблем кодовой базы без изменения кода"],"ar":["استكشاف قواعد الشفرة لتحليل الإعتماديات","إنشاء ملحقات OpenSpec لتطوير المقترحات","تحقيق مشاكل قاعدة الشفرة دون تعديل الشفرة"]},"limitations":{"en":["Must not write code or implement features in explore mode","Requires exit from explore mode to implement changes via /opsx:new or /opsx:ff"],"zh":["探索模式下不能编写代码或实现功能","需要退出探索模式以通过/opsx:new或/opsx:ff实现更改"],"ja":["探索モードではコードを書いたり機能を実装したりできない","変更を/opsx:newまたは/opsx:ffで実装するには探索モードを終了する必要がある"],"ko":["탐색 모드에서는 코드를 작성하거나 기능을 구현할 수 없다.","/opsx:new 또는 /opsx:ff를 통해 변경을 구현하려면 탐색 모드를 종료해야 한다."],"es":["No debe escribir código o implementar características en el modo de exploración","Requiere la salida del modo de exploración para implementar cambios a través de /opsx:new o /opsx:ff"],"fr":["Ne doit pas écrire de code ou implémenter des fonctionnalités en mode d''exploration","Nécessite la sortie du mode d''exploration pour implémenter des modifications via /opsx:new ou /opsx:ff"],"de":["Darf im Explorationsmodus keinen Code schreiben oder Funktionen implementieren","Erfordert den Ausstieg aus dem Explorationsmodus, um Änderungen über /opsx:new oder /opsx:ff umzusetzen"],"pt":["Não deve escrever código ou implementar recursos no modo de exploração","Requer saída do modo de exploração para implementar alterações via /opsx:new ou /opsx:ff"],"ru":["Не должен писать код или реализовывать функции в режиме изучения","Требует выхода из режима изучения для реализации изменений через /opsx:new или /opsx:ff"],"ar":["لا ينبغي كتابة الشفرة أو تنفيذ الميزات في وضع الاستكشاف","يتطلب الخروج من وضع الاستكشاف لتنفيذ التغييرات عبر /opsx:new أو /opsx:ff"]},"version":3},"contentHash":"37cb96a8ba4c1f65d3a79e3a2636f1367325e7dbc815e9519c2c5d46d346ce15","qualityScore":42}');
