INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('victorbecerragit/eks-cdk-argocd-showcase/kubernetes-architect', 'kubernetes-architect', 'victorbecerragit', 'eks-cdk-argocd-showcase', 'community', 'kubernetes-architect victorbecerragit eks-cdk-argocd-showcase community Kubernetes架构师的eks-cdk-argocd展示是一个云原生应用开发的最佳实践 Kubernetesアーキテクトのeks-cdk-argocd展示はクラウドネイティブアプリ開発のベストプラクティスです 쿠버네티스 아키텍트의 eks-cdk-argocd展示는 클라우드 네이티브 애플리케이션 개발의 베스트 프랙티스입니다 El arquitecto de Kubernetes es una herramienta de AI que facilita la implementación de soluciones de DevOps con eks-cdk-argocd-showcase L''architecte Kubernetes est un outil d''IA qui facilite la mise en œuvre de solutions DevOps avec eks-cdk-argocd-showcase Der Kubernetes-Architekt ist ein KI-Tool, das die Umsetzung von DevOps-Lösungen mit eks-cdk-argocd-showcase erleichtert O skill de arquiteto Kubernetes com EKS, CDK e Argo CD é uma solução para gerenciar e orquestrar aplicações em contêineres Навык архитектора Kubernetes с EKS, CDK и Argo CD - это решение для управления и оркестровки контейнеризированных приложений مهارة مهندس معماري كوبرنيتس مع EKS و CDK و Argo CD هي حل لادارة وتشغيل التطبيقات في الحاويات eks-cdk-argocd-showcase Kubernetes架构师 eks-cdk-argocd 云原生应用开发 AI智能代理 自动化部署 安全性和合规性 可扩展性和高可用性 如何使用Kubernetes Kubernetes vs Docker eks-cdk-argocd-showcase');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaxxstorm/sentinel/openspec-onboard', 'community', 'jaxxstorm', 'sentinel', 'jaxxstorm/sentinel', 'openspec-onboard', 0, 0, 42, '2026-03-05T06:20:06.303Z', '2026-03-05T08:43:20.761Z', 'f764e94014ec70ccd261ab580debbaa6ce74eff2877bffc80734e64fb70bb397', '{"id":"jaxxstorm/sentinel/openspec-onboard","name":"openspec-onboard","description":{"zh":"openspec-onboard AI智能代理监控您的Tailnet，并在发生更改时通知您，确保您的网络安全","ja":"openspec-onboard AIエージェントは、Tailnetを監視し、変更が発生すると通知します。ネットワークのセキュリティを確保します","ko":"openspec-onboard AI 에이전트는 테일넷을 감시하며 변경 사항이 발생하면 알림을 보내 네트워크 보안을 보장","es":"openspec-onboard es una herramienta de AI que monitorea tu tailnet y notifica cambios. Ideal para desarrolladores que buscan seguridad","fr":"openspec-onboard est un outil IA qui surveille votre tailnet et alerte en cas de modifications. Idéal pour les développeurs qui recherchent la sécurité","de":"openspec-onboard ist ein KI-Tool, das Ihr Tailnet überwacht und Änderungen meldet. Ideal für Entwickler, die Sicherheit suchen","pt":"O openspec-onboard é uma ferramenta de IA que monitora sua rede e notifica alterações. Aprenda a utilizá-la para melhorar a segurança da sua rede.","ru":"ИИ Агент openspec-onboard следит за вашей сетью и уведомляет об изменениях. Узнайте, как использовать эту технологию для повышения безопасности.","ar":"أداة الذكاء الاصطناعي openspec-onboard تتابع شبكتك وتنبه التغييرات. تعلم كيفية استخدام هذه الأداة لتحسين أمان شبكتك.","en":"Watch over your tailnet and notify of changes"},"seo":{"title":{"zh":"AI智能代理 openspec-onboard 监控Tailnet","ja":"AIエージェント openspec-onboard のTailnet監視","ko":"AI 에이전트 openspec-onboard 테일넷 감시","es":"Herramientas de AI: openspec-onboard para monitorear tailnet","fr":"Outils IA: openspec-onboard pour surveiller tailnet","de":"KI-Tools: openspec-onboard für Tailnet-Überwachung","pt":"Ferramentas de IAs: openspec-onboard para Monitoramento","ru":"ИИ Агенты: openspec-onboard для Надзора","ar":"أدوات الذكاء الاصطناعي: openspec-onboard لمراقبة الشبكة","en":"openspec-onboard"},"description":{"zh":"openspec-onboard AI智能代理监控您的Tailnet，并在发生更改时通知您，确保您的网络安全","ja":"openspec-onboard AIエージェントは、Tailnetを監視し、変更が発生すると通知します。ネットワークのセキュリティを確保します","ko":"openspec-onboard AI 에이전트는 테일넷을 감시하며 변경 사항이 발생하면 알림을 보내 네트워크 보안을 보장","es":"openspec-onboard es una herramienta de AI que monitorea tu tailnet y notifica cambios. Ideal para desarrolladores que buscan seguridad","fr":"openspec-onboard est un outil IA qui surveille votre tailnet et alerte en cas de modifications. Idéal pour les développeurs qui recherchent la sécurité","de":"openspec-onboard ist ein KI-Tool, das Ihr Tailnet überwacht und Änderungen meldet. Ideal für Entwickler, die Sicherheit suchen","pt":"O openspec-onboard é uma ferramenta de IA que monitora sua rede e notifica alterações. Aprenda a utilizá-la para melhorar a segurança da sua rede.","ru":"ИИ Агент openspec-onboard следит за вашей сетью и уведомляет об изменениях. Узнайте, как использовать эту технологию для повышения безопасности.","ar":"أداة الذكاء الاصطناعي openspec-onboard تتابع شبكتك وتنبه التغييرات. تعلم كيفية استخدام هذه الأداة لتحسين أمان شبكتك.","en":"Watch over your tailnet and notify of changes"},"definition":{"en":"Watch over your tailnet and notify of changes"},"features":{"zh":["监控Tailnet","通知更改","确保网络安全","AI智能代理","实时监控","自定义通知"],"ja":["Tailnetの監視","変更の通知","ネットワークのセキュリティ","AIエージェント","リアルタイム監視","カスタム通知"],"ko":["테일넷 감시","변경 사항 알림","네트워크 보안","AI 에이전트","실시간 감시","사용자 정의 알림"],"es":["Monitoreo de tailnet","Notificación de cambios","Seguridad para desarrolladores","Integración con herramientas de desarrollo","Facilidad de uso y configuración"],"fr":["Surveillance de tailnet","Alerte en cas de modifications","Sécurité pour les développeurs","Intégration avec les outils de développement","Facilité d''utilisation et de configuration"],"de":["Überwachung von Tailnet","Meldung von Änderungen","Sicherheit für Entwickler","Integration mit Entwicklungstools","Einfachheit bei der Verwendung und Konfiguration"],"pt":["Monitoramento de rede em tempo real","Notificação de alterações na rede","Integração com tecnologias de segurança existentes","Análise de dados de rede avançada","Suporte a múltiplas plataformas"],"ru":["Мониторинг сети в режиме реального времени","Уведомление об изменениях в сети","Интеграция с существующими технологиями безопасности","Расширенный анализ данных сети","Поддержка нескольких платформ"],"ar":["مراقبة الشبكة في الوقت الفعلي","تنبيه التغييرات في الشبكة","التكامل مع تقنيات الأمان الحالية","تحليل البيانات الشبكية المتقدم","دعم منصات متعددة"]},"keywords":{"zh":["如何使用openspec-onboard","什么是AI智能代理","openspec-onboard替代品","openspec-onboard vs 其他AI代理","openspec-onboard安装","openspec-onboard设置指南","Tailnet监控","网络安全解决方案"],"ja":["openspec-onboardの使い方","AIエージェントとは","openspec-onboardの代替","openspec-onboard vs 他のAIエージェント","openspec-onboardのインストール","openspec-onboardの設定ガイド","Tailnetの監視","ネットワークのセキュリティソリューション"],"ko":["openspec-onboard 사용법","AI 에이전트란","openspec-onboard 대안","openspec-onboard vs 다른 AI 에이전트","openspec-onboard 설치","openspec-onboard 설정 가이드","테일넷 감시","네트워크 보안 솔루션"],"es":["herramientas de AI","monitoreo de tailnet","seguridad para desarrolladores","cómo usar openspec-onboard","alternativas a openspec-onboard","instalación de openspec-onboard","guía de configuración de openspec-onboard","openspec-onboard vs otras herramientas","beneficios de openspec-onboard"],"fr":["outils IA","surveillance de tailnet","sécurité pour les développeurs","comment utiliser openspec-onboard","alternatives à openspec-onboard","installation d''openspec-onboard","guide de configuration d''openspec-onboard","openspec-onboard vs autres outils","avantages d''openspec-onboard"],"de":["KI-Tools","Überwachung von Tailnet","Sicherheit für Entwickler","wie man openspec-onboard verwendet","Alternativen zu openspec-onboard","Installation von openspec-onboard","Konfigurationsanleitung für openspec-onboard","openspec-onboard vs andere Tools","Vorteile von openspec-onboard"],"pt":["como usar openspec-onboard","ferramentas de IA para segurança","openspec-onboard vs outros agentes","guia de instalação do openspec-onboard","configuração do openspec-onboard","alternativas ao openspec-onboard"],"ru":["как использовать openspec-onboard","ИИ инструменты для безопасности","openspec-onboard vs другие агенты","руководство по установке openspec-onboard","настройка openspec-onboard","альтернативы openspec-onboard"],"ar":["كيفية استخدام openspec-onboard","أدوات الذكاء الاصطناعي للأمان","openspec-onboard مقابل أدوات أخرى","دليل تثبيت openspec-onboard","إعداد openspec-onboard","بديلات openspec-onboard"]}},"owner":"jaxxstorm","repo":"sentinel","repoPath":"jaxxstorm/sentinel","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.303Z","topics":[],"category":"community","skillMd":{"name":"openspec-onboard","description":"Guided onboarding for OpenSpec - walk through a complete workflow cycle with narration and real codebase work.","version":"1.0","bodyPreview":"Guide the user through their first complete OpenSpec workflow cycle. This is a teaching experience—you''ll do real work in their codebase while explaining each step.\n\n---\n\n## Preflight\n\nBefore starting, check if OpenSpec is initialized:\n\n```bash\nopenspec status --json 2>&1 || echo \"NOT_INITIALIZED\"\n```\n\n**If not initialized:**\n> OpenSpec isn''t set up in this project yet. Run `openspec init` first, then come back to `/opsx:onboard`.\n\nStop here if not initialized.\n\n---\n\n## Phase 1: Welcome\n\nDisplay","body":"Guide the user through their first complete OpenSpec workflow cycle. This is a teaching experience—you''ll do real work in their codebase while explaining each step.\n\n---\n\n## Preflight\n\nBefore starting, check if OpenSpec is initialized:\n\n```bash\nopenspec status --json 2>&1 || echo \"NOT_INITIALIZED\"\n```\n\n**If not initialized:**\n> OpenSpec isn''t set up in this project yet. Run `openspec init` first, then come back to `/opsx:onboard`.\n\nStop here if not initialized.\n\n---\n\n## Phase 1: Welcome\n\nDisplay:\n\n```\n## Welcome to OpenSpec!\n\nI''ll walk you through a complete change cycle—from idea to implementation—using a real task in your codebase. Along the way, you''ll learn the workflow by doing it.\n\n**What we''ll do:**\n1. Pick a small, real task in your codebase\n2. Explore the problem briefly\n3. Create a change (the container for our work)\n4. Build the artifacts: proposal → specs → design → tasks\n5. Implement the tasks\n6. Archive the completed change\n\n**Time:** ~15-20 minutes\n\nLet''s start by finding something to work on.\n```\n\n---\n\n## Phase 2: Task Selection\n\n### Codebase Analysis\n\nScan the codebase for small improvement opportunities. Look for:\n\n1. **TODO/FIXME comments** - Search for `TODO`, `FIXME`, `HACK`, `XXX` in code files\n2. **Missing error handling** - `catch` blocks that swallow errors, risky operations without try-catch\n3. **Functions without tests** - Cross-reference `src/` with test directories\n4. **Type issues** - `any` types in TypeScript files (`: any`, `as any`)\n5. **Debug artifacts** - `console.log`, `console.debug`, `debugger` statements in non-debug code\n6. **Missing validation** - User input handlers without validation\n\nAlso check recent git activity:\n```bash\ngit log --oneline -10 2>/dev/null || echo \"No git history\"\n```\n\n### Present Suggestions\n\nFrom your analysis, present 3-4 specific suggestions:\n\n```\n## Task Suggestions\n\nBased on scanning your codebase, here are some good starter tasks:\n\n**1. [Most promising task]**\n   Location: `src/path/to/file.ts:42`\n   Scope: ~1-2 files, ~20-30 lines\n   Why it''s good: [brief reason]\n\n**2. [Second task]**\n   Location: `src/another/file.ts`\n   Scope: ~1 file, ~15 lines\n   Why it''s good: [brief reason]\n\n**3. [Third task]**\n   Location: [location]\n   Scope: [estimate]\n   Why it''s good: [brief reason]\n\n**4. Something else?**\n   Tell me what you''d like to work on.\n\nWhich task interests you? (Pick a number or describe your own)\n```\n\n**If nothing found:** Fall back to asking what the user wants to build:\n> I didn''t find obvious quick wins in your codebase. What''s something small you''ve been meaning to add or fix?\n\n### Scope Guardrail\n\nIf the user picks or describes something too large (major feature, multi-day work):\n\n```\nThat''s a valuable task, but it''s probably larger than ideal for your first OpenSpec run-through.\n\nFor learning the workflow, smaller is better—it lets you see the full cycle without getting stuck in implementation details.\n\n**Options:**\n1. **Slice it smaller** - What''s the smallest useful piece of [their task]? Maybe just [specific slice]?\n2. **Pick something else** - One of the other suggestions, or a different small task?\n3. **Do it anyway** - If you really want to tackle this, we can. Just know it''ll take longer.\n\nWhat would you prefer?\n```\n\nLet the user override if they insist—this is a soft guardrail.\n\n---\n\n## Phase 3: Explore Demo\n\nOnce a task is selected, briefly demonstrate explore mode:\n\n```\nBefore we create a change, let me quickly show you **explore mode**—it''s how you think through problems before committing to a direction.\n```\n\nSpend 1-2 minutes investigating the relevant code:\n- Read the file(s) involved\n- Draw a quick ASCII diagram if it helps\n- Note any considerations\n\n```\n## Quick Exploration\n\n[Your brief analysis—what you found, any considerations]\n\n┌─────────────────────────────────────────┐\n│   [Optional: ASCII diagram if helpful]  │\n└─────────────────────────────────────────┘\n\nExplore mode (`/opsx:explore`) is for this kind of thinking—investigating before implementing. You can use it anytime you need to think through a problem.\n\nNow let''s create a change to hold our work.\n```\n\n**PAUSE** - Wait for user acknowledgment before proceeding.\n\n---\n\n## Phase 4: Create the Change\n\n**EXPLAIN:**\n```\n## Creating a Change\n\nA \"change\" in OpenSpec is a container for all the thinking and planning around a piece of work. It lives in `openspec/changes/<name>/` and holds your artifacts—proposal, specs, design, tasks.\n\nLet me create one for our task.\n```\n\n**DO:** Create the change with a derived kebab-case name:\n```bash\nopenspec new change \"<derived-name>\"\n```\n\n**SHOW:**\n```\nCreated: `openspec/changes/<name>/`\n\nThe folder structure:\n```\nopenspec/changes/<name>/\n├── proposal.md    ← Why we''re doing this (empty, we''ll fill it)\n├── design.md      ← How we''ll build it (empty)\n├── specs/         ← Detailed requirements (empty)\n└── tasks.md       ← Implementation checklist (empty)\n```\n\nNow let''s fill in the first artifact—the proposal.\n```\n\n---\n\n## Phase 5: Proposal\n\n**EXPLAIN:**\n```\n## The Proposal\n\nThe proposal captures **why** we''re making this change and **what** it involves at a high level. It''s the \"elevator pitch\" for the work.\n\nI''ll draft one based on our task.\n```\n\n**DO:** Draft the proposal content (don''t save yet):\n\n```\nHere''s a draft proposal:\n\n---\n\n## Why\n\n[1-2 sentences explaining the problem/opportunity]\n\n## What Changes\n\n[Bullet points of what will be different]\n\n## Capabilities\n\n### New Capabilities\n- `<capability-name>`: [brief description]\n\n### Modified Capabilities\n<!-- If modifying existing behavior -->\n\n## Impact\n\n- `src/path/to/file.ts`: [what changes]\n- [other files if applicable]\n\n---\n\nDoes this capture the intent? I can adjust before we save it.\n```\n\n**PAUSE** - Wait for user approval/feedback.\n\nAfter approval, save the proposal:\n```bash\nopenspec instructions proposal --change \"<name>\" --json\n```\nThen write the content to `openspec/changes/<name>/proposal.md`.\n\n```\nProposal saved. This is your \"why\" document—you can always come back and refine it as understanding evolves.\n\nNext up: specs.\n```\n\n---\n\n## Phase 6: Specs\n\n**EXPLAIN:**\n```\n## Specs\n\nSpecs define **what** we''re building in precise, testable terms. They use a requirement/scenario format that makes expected behavior crystal clear.\n\nFor a small task like this, we might only need one spec file.\n```\n\n**DO:** Create the spec file:\n```bash\nmkdir -p openspec/changes/<name>/specs/<capability-name>\n```\n\nDraft the spec content:\n\n```\nHere''s the spec:\n\n---\n\n## ADDED Requirements\n\n### Requirement: <Name>\n\n<Description of what the system should do>\n\n#### Scenario: <Scenario name>\n\n- **WHEN** <trigger condition>\n- **THEN** <expected outcome>\n- **AND** <additional outcome if needed>\n\n---\n\nThis format—WHEN/THEN/AND—makes requirements testable. You can literally read them as test cases.\n```\n\nSave to `openspec/changes/<name>/specs/<capability>/spec.md`.\n\n---\n\n## Phase 7: Design\n\n**EXPLAIN:**\n```\n## Design\n\nThe design captures **how** we''ll build it—technical decisions, tradeoffs, approach.\n\nFor small changes, this might be brief. That''s fine—not every change needs deep design discussion.\n```\n\n**DO:** Draft design.md:\n\n```\nHere''s the design:\n\n---\n\n## Context\n\n[Brief context about the current state]\n\n## Goals / Non-Goals\n\n**Goals:**\n- [What we''re trying to achieve]\n\n**Non-Goals:**\n- [What''s explicitly out of scope]\n\n## Decisions\n\n### Decision 1: [Key decision]\n\n[Explanation of approach and rationale]\n\n---\n\nFor a small task, this captures the key decisions without over-engineering.\n```\n\nSave to `openspec/changes/<name>/design.md`.\n\n---\n\n## Phase 8: Tasks\n\n**EXPLAIN:**\n```\n## Tasks\n\nFinally, we break the work into implementation tasks—checkboxes that drive the apply phase.\n\nThese should be small, clear, and in logical order.\n```\n\n**DO:** Generate tasks based on specs and design:\n\n```\nHere are the implementation tasks:\n\n---\n\n## 1. [Category or file]\n\n- [ ] 1.1 [Specific task]\n- [ ] 1.2 [Specific task]\n\n## 2. Verify\n\n- [ ] 2.1 [Verification step]\n\n---\n\nEach checkbox becomes a unit of work in the apply phase. Ready to implement?\n```\n\n**PAUSE** - Wait for user to confirm they''re ready to implement.\n\nSave to `openspec/changes/<name>/tasks.md`.\n\n---\n\n## Phase 9: Apply (Implementation)\n\n**EXPLAIN:**\n```\n## Implementation\n\nNow we implement each task, checking them off as we go. I''ll announce each one and occasionally note how the specs/design informed the approach.\n```\n\n**DO:** For each task:\n\n1. Announce: \"Working on task N: [description]\"\n2. Implement the change in the codebase\n3. Reference specs/design naturally: \"The spec says X, so I''m doing Y\"\n4. Mark complete in tasks.md: `- [ ]` → `- [x]`\n5. Brief status: \"✓ Task N complete\"\n\nKeep narration light—don''t over-explain every line of code.\n\nAfter all tasks:\n\n```\n## Implementation Complete\n\nAll tasks done:\n- [x] Task 1\n- [x] Task 2\n- [x] ...\n\nThe change is implemented! One more step—let''s archive it.\n```\n\n---\n\n## Phase 10: Archive\n\n**EXPLAIN:**\n```\n## Archiving\n\nWhen a change is complete, we archive it. This moves it from `openspec/changes/` to `openspec/changes/archive/YYYY-MM-DD-<name>/`.\n\nArchived changes become your project''s decision history—you can always find them later to understand why something was built a certain way.\n```\n\n**DO:**\n```bash\nopenspec archive \"<name>\"\n```\n\n**SHOW:**\n```\nArchived to: `openspec/changes/archive/YYYY-MM-DD-<name>/`\n\nThe change is now part of your project''s history. The code is in your codebase, the decision record is preserved.\n```\n\n---\n\n## Phase 11: Recap & Next Steps\n\n```\n## Congratulations!\n\nYou just completed a full OpenSpec cycle:\n\n1. **Explore** - Thought through the problem\n2. **New** - Created a change container\n3. **Proposal** - Captured WHY\n4. **Specs** - Defined WHAT in detail\n5. **Design** - Decided HOW\n6. **Tasks** - Broke it into steps\n7. **Apply** - Implemented the work\n8. **Archive** - Preserved the record\n\nThis same rhythm works for any size change—a small fix or a major feature.\n\n---\n\n## Command Reference\n\n| Command | What it does |\n|---------|--------------|\n| `/opsx:explore` | Think through problems before/during work |\n| `/opsx:new` | Start a new change, step through artifacts |\n| `/opsx:ff` | Fast-forward: create all artifacts at once |\n| `/opsx:continue` | Continue working on an existing change |\n| `/opsx:apply` | Implement tasks from a change |\n| `/opsx:verify` | Verify implementation matches artifacts |\n| `/opsx:archive` | Archive a completed change |\n\n---\n\n## What''s Next?\n\nTry `/opsx:new` or `/opsx:ff` on something you actually want to build. You''ve got the rhythm now!\n```\n\n---\n\n## Graceful Exit Handling\n\n### User wants to stop mid-way\n\nIf the user says they need to stop, want to pause, or seem disengaged:\n\n```\nNo problem! Your change is saved at `openspec/changes/<name>/`.\n\nTo pick up where we left off later:\n- `/opsx:continue <name>` - Resume artifact creation\n- `/opsx:apply <name>` - Jump to implementation (if tasks exist)\n\nThe work won''t be lost. Come back whenever you''re ready.\n```\n\nExit gracefully without pressure.\n\n### User just wants command reference\n\nIf the user says they just want to see the commands or skip the tutorial:\n\n```\n## OpenSpec Quick Reference\n\n| Command | What it does |\n|---------|--------------|\n| `/opsx:explore` | Think through problems (no code changes) |\n| `/opsx:new <name>` | Start a new change, step by step |\n| `/opsx:ff <name>` | Fast-forward: all artifacts at once |\n| `/opsx:continue <name>` | Continue an existing change |\n| `/opsx:apply <name>` | Implement tasks |\n| `/opsx:verify <name>` | Verify implementation |\n| `/opsx:archive <name>` | Archive when done |\n\nTry `/opsx:new` to start your first change, or `/opsx:ff` if you want to move fast.\n```\n\nExit gracefully.\n\n---\n\n## Guardrails\n\n- **Follow the EXPLAIN → DO → SHOW → PAUSE pattern** at key transitions (after explore, after proposal draft, after tasks, after archive)\n- **Keep narration light** during implementation—teach without lecturing\n- **Don''t skip phases** even if the change is small—the goal is teaching the workflow\n- **Pause for acknowledgment** at marked points, but don''t over-pause\n- **Handle exits gracefully**—never pressure the user to continue\n- **Use real codebase tasks**—don''t simulate or use fake examples\n- **Adjust scope gently**—guide toward smaller tasks but respect user choice\n"},"lastSynced":"2026-03-05T08:43:20.761Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing guided OpenSpec workflow integration and codebase analysis.","zh":"非常适合需要引导式OpenSpec工作流集成和代码库分析的开发代理。","ja":"OpenSpecワークフロー統合とコードベース分析のガイダンスが必要な開発エージェントに最適です。","ko":"가이드된 OpenSpec 워크플ロー 통합 및 코드베이스 분석이 필요한 개발 에이전트에게 완벽합니다.","es":"Perfecto para agentes de desarrollo que necesitan una integración de flujo de trabajo de OpenSpec guiada y análisis de código base.","fr":"Parfait pour les agents de développement qui ont besoin d''une intégration de flux de travail OpenSpec guidée et d''une analyse de codebase.","de":"Perfekt für Entwicklungsmittel, die eine geleitete OpenSpec-Workflow-Integration und Codebase-Analyse benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de integração de fluxo de trabalho OpenSpec orientada e análise de código","ru":"Идеально для агентов разработки, которым необходима интеграция рабочего процесса OpenSpec с руководством и анализ кодовой базы","ar":"مثالي للوكلاء الناشئين الذين يحتاجون إلى دمج تدفق العمل المفتوح مع إرشادات وتحليل للمجموعة الكودية"},"recommendation":{"en":"Empowers agents to onboard users to OpenSpec by guiding them through their first complete workflow cycle, utilizing JSON output and bash commands like `openspec status` and `openspec init`, to ensure seamless project setup and initialization.","zh":"使代理能够通过引导用户完成第一个完整的工作流周期来将用户加入OpenSpec，利用JSON输出和bash命令，如`openspec status`和`openspec init`，以确保项目设置和初始化的无缝进行。","ja":"エージェントがユーザーをOpenSpecにオンボードするために、最初の完全なワークフローサイクルを通じてユーザーをガイダンスすることを可能にし、JSON出力とbashコマンド（例： `openspec status`および`openspec init`）を利用して、プロジェクトの設定と初期化をスムーズに行えるようにします。","ko":"에이전트가 첫 번째 완전한 워크플ロー 사이클을 통해 사용자를 OpenSpec에 온보딩할 수 있도록 하여 JSON 출력 및 bash 명령어(`openspec status` 및 `openspec init` 등)을 사용하여 프로젝트 설정 및 초기화를 무중단으로 수행할 수 있도록 합니다.","es":"Habilita a los agentes a incorporar usuarios a OpenSpec guiándolos a través de su primer ciclo de flujo de trabajo completo, utilizando la salida JSON y comandos bash como `openspec status` y `openspec init`, para garantizar una configuración y inicialización de proyecto sin problemas.","fr":"Permet aux agents d''intégrer les utilisateurs à OpenSpec en les guidant à travers leur premier cycle de flux de travail complet, en utilisant la sortie JSON et les commandes bash comme `openspec status` et `openspec init`, pour assurer une configuration et une initialisation de projet sans problème.","de":"Ermächtigt Agenten, Benutzer in OpenSpec einzubinden, indem sie diese durch ihren ersten vollständigen Workflow-Zyklus führen, wobei JSON-Ausgabe und Bash-Befehle wie `openspec status` und `openspec init` verwendet werden, um eine reibungslose Projektkonfiguration und -initialisierung zu gewährleisten.","pt":"Habilita os agentes a integrar os usuários ao OpenSpec, orientando-os por meio de seu primeiro ciclo de fluxo de trabalho completo, utilizando saída JSON e comandos bash como `openspec status` e `openspec init`, para garantir uma configuração e inicialização de projeto sem problemas","ru":"Наделяет агентов возможностью интегрировать пользователей в OpenSpec, руководя ими через их первый полный цикл рабочего процесса, используя выходные данные JSON и команды bash, такие как `openspec status` и `openspec init`, для обеспечения бесшовной настройки и инициализации проекта","ar":"يمنح الوكلاء القدرة على ربط المستخدمين بالمشروع المفتوح من خلال إرشادهم خلال دورة العمل الكاملة الأولى، باستخدام الإخراج JSON وأوامر bash مثل `openspec status` و `openspec init` ، لضمان إعداد مشروع بدون مشاكل"},"useCases":{"en":["Onboarding new users to OpenSpec projects","Initializing OpenSpec in uninitialized projects","Analyzing project status with `openspec status`"],"zh":["将新用户加入OpenSpec项目","在未初始化的项目中初始化OpenSpec","使用`openspec status`分析项目状态"],"ja":["OpenSpecプロジェクトへの新規ユーザーのオンボード","未初期化プロジェクトでのOpenSpecの初期化","`openspec status`を使用したプロジェクトステータスの分析"],"ko":["새 사용자를 OpenSpec 프로젝트에 온보딩하는 것","초기화되지 않은 프로젝트에서 OpenSpec 초기화","`openspec status`를 사용한 프로젝트 상태 분석"],"es":["Incorporación de nuevos usuarios a proyectos de OpenSpec","Inicialización de OpenSpec en proyectos no inicializados","Análisis del estado del proyecto con `openspec status`"],"fr":["Intégration de nouveaux utilisateurs aux projets OpenSpec","Initialisation d''OpenSpec dans les projets non initialisés","Analyse de l''état du projet avec `openspec status`"],"de":["Einbindung neuer Benutzer in OpenSpec-Projekte","Initialisierung von OpenSpec in nicht initialisierten Projekten","Analyse des Projektstatus mit `openspec status`"],"pt":["Integração de novos usuários a projetos OpenSpec","Inicialização do OpenSpec em projetos não inicializados","Análise do status do projeto com `openspec status`"],"ru":["Интеграция новых пользователей в проекты OpenSpec","Инициализация OpenSpec в неинициализированных проектах","Анализ статуса проекта с помощью `openspec status`"],"ar":["دمج المستخدمين الجدد في مشاريع_OpenSpec","تثبيت OpenSpec في المشاريع غير المثبتة","تحليل حالة المشروع باستخدام `openspec status`"]},"limitations":{"en":["Requires OpenSpec installation","Must be run in a project directory","Project must be initialized with `openspec init` to proceed"],"zh":["需要OpenSpec安装","必须在项目目录中运行","项目必须使用`openspec init`初始化后才能继续"],"ja":["OpenSpecのインストールが必要","プロジェクトディレクトリ内で実行する必要がある","`openspec init`で初期化されたプロジェクトでないと続行できない"],"ko":["OpenSpec 설치가 필요합니다.","프로젝트 디렉토리에서 실행해야 합니다.","프로젝트가 `openspec init`으로 초기화되지 않으면 계속할 수 없습니다."],"es":["Requiere la instalación de OpenSpec","Debe ejecutarse en un directorio de proyecto","El proyecto debe estar inicializado con `openspec init` para proceder"],"fr":["Nécessite l''installation d''OpenSpec","Doit être exécuté dans un répertoire de projet","Le projet doit être initialisé avec `openspec init` pour procéder"],"de":["Benötigt die Installation von OpenSpec","Muss in einem Projektverzeichnis ausgeführt werden","Das Projekt muss mit `openspec init` initialisiert werden, um fortzufahren"],"pt":["Requer instalação do OpenSpec","Deve ser executado em um diretório de projeto","O projeto deve ser inicializado com `openspec init` para prosseguir"],"ru":["Требует установки OpenSpec","Должен быть запущен в каталоге проекта","Проект должен быть инициализирован с помощью `openspec init` для продолжения"],"ar":["يتطلب تثبيت OpenSpec","يجب تشغيله في دليل المشروع","يجب تهيئة المشروع باستخدام `openspec init` للمواصلة"]},"version":3},"contentHash":"f764e94014ec70ccd261ab580debbaa6ce74eff2877bffc80734e64fb70bb397","qualityScore":42}');
