INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MixTapeSoftware/pop_stash/design-principles', 'design-principles', 'MixTapeSoftware', 'pop_stash', 'community', 'design-principles MixTapeSoftware pop_stash community The design-principles skill enforces precise design for enterprise software, SaaS dashboards, and web applications, benefiting developers and product teams. It ensures polished interfaces designed for specific contexts 设计原则技能强调精确的企业软件和 SaaS 仪表盘设计，注重 Jony Ive 级别的精确性和故意的人格化 デザインプリンシップスキルは、企業ソフトウェアと SaaS ダッシュボードの設計を最適化するためのもので、AIエージェントによるインターフェース設計を実現 디자인 원칙 스킬은 정확한 엔터프라이즈 소프트웨어와 SaaS 대시보드 디자인을 구현하기 위한 것으로, LLM 확장 메모리와 인사이트 캡처를 활용 Los principios de diseño permiten crear interfaces de usuario personalizadas y precisas para software y aplicaciones web Les principes de conception permettent de créer des interfaces utilisateur personnalisées et précises pour les logiciels et les applications web Die Designprinzipien ermöglichen die Erstellung von benutzerdefinierten und präzisen Benutzeroberflächen für Software und Webanwendungen O skill de princípios de design permite a criação de interfaces de usuário polidas e personalizadas para software empresarial e aplicações web Навык принципов дизайна позволяет создавать отполированные и персонализированные интерфейсы пользователей для корпоративного программного обеспечения и веб-приложений مahirة مبادئ التصميم تسمح بإنشاء واجهات مستخدم متطورة ومتخصصة لبرامج الأعمال والتطبيقات الويب how to use design-principles what is design-principles design-principles alternative design-principles vs material design design-principles install design-principles setup guide enterprise software design principles SaaS dashboard design best practices intentional interface design 设计原则 LLM 扩展内存 洞察捕获 企业软件设计 SaaS 仪表盘设计 Jony Ive 界面设计 设计方向 Enforces Jony Ive-level precision in design Requires commitment to a design direction before writing code Considers context for interface design Supports design for enterprise software, SaaS dashboards, and web applications Ensures polished interfaces with intentional personality Captures insight with LLM Extended Memory and Insight Capture MCP Service design-principles is a skill that enforces precise, crafted design for enterprise software and web applications, focusing on intentional personality and context-specific interfaces');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brixtonpham/claude-setup/github-search', 'community', 'brixtonpham', 'claude-setup', 'brixtonpham/claude-setup', 'github-search', 0, 0, 42, '2026-03-06T06:23:00.159Z', '2026-03-06T07:23:42.750Z', '0bd94b4585b68dc19ed433deacd7586ac6724ce906eb76505e2804dd7e239003', '{"id":"brixtonpham/claude-setup/github-search","name":"github-search","description":{"en":"The github-search skill enables developers to efficiently search GitHub repositories, code, issues, and PRs using specific commands like gh search repos and Direct API Search. It benefits developers who need precise search results.","zh":"GitHub 搜索工具提供快速命令和直接 API 搜索功能，用于查找仓库、代码、问题和 PR","ja":"GitHub 検索ツールは、リポジトリ、コード、問題、PR を検索するためのクイックコマンドと直接 API 検索機能を提供します","ko":"GitHub 검색 에이전트는 저장소, 코드, 문제, PR를 검색하는 빠른 명령과 직접 API 검색 기능을 제공합니다","es":"github-search es una herramienta para buscar en GitHub. Ofrece comandos para buscar repositorios, código, problemas y solicitudes de extracción.","fr":"github-search est un outil de recherche sur GitHub. Il propose des commandes pour rechercher des référentiels, du code, des problèmes et des demandes de tirage.","de":"github-search ist ein Suchtool für GitHub. Es bietet Kommandos zum Suchen von Repositorys, Code, Problemen und Pull-Requests.","pt":"O GitHub Search é uma ferramenta poderosa para desenvolvedores, permitindo busca rápida em repositórios, código, issues e PRs.","ru":"GitHub Search - это мощный инструмент для разработчиков, позволяющий быстро искать репозитории, код, issues и PRs.","ar":"بحث GitHub هو أداة قوية للمطورين، تمكن من البحث السريع في المستودعات والكود والقضايا والطلبات"},"seo":{"title":{"en":"github-search: Efficient Repository Search Setup Guide | ...","zh":"GitHub 搜索工具 Setup Guide","ja":"GitHub 検索ツールのベストプラクティス","ko":"GitHub 검색 에이전트 설정 가이드","es":"Guía de configuración de github-search para desarrolladores