INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brixtonpham/claude-setup/github-search', 'github-search', 'brixtonpham', 'claude-setup', 'community', 'github-search brixtonpham claude-setup community The github-search skill enables developers to efficiently search GitHub repositories, code, issues, and PRs using specific commands like gh search repos and Direct API Search. It benefits developers who need precise search results. GitHub 搜索工具提供快速命令和直接 API 搜索功能，用于查找仓库、代码、问题和 PR GitHub 検索ツールは、リポジトリ、コード、問題、PR を検索するためのクイックコマンドと直接 API 検索機能を提供します GitHub 검색 에이전트는 저장소, 코드, 문제, PR를 검색하는 빠른 명령과 직접 API 검색 기능을 제공합니다 github-search es una herramienta para buscar en GitHub. Ofrece comandos para buscar repositorios, código, problemas y solicitudes de extracción. github-search est un outil de recherche sur GitHub. Il propose des commandes pour rechercher des référentiels, du code, des problèmes et des demandes de tirage. github-search ist ein Suchtool für GitHub. Es bietet Kommandos zum Suchen von Repositorys, Code, Problemen und Pull-Requests. O GitHub Search é uma ferramenta poderosa para desenvolvedores, permitindo busca rápida em repositórios, código, issues e PRs. GitHub Search - это мощный инструмент для разработчиков, позволяющий быстро искать репозитории, код, issues и PRs. بحث GitHub هو أداة قوية للمطورين، تمكن من البحث السريع في المستودعات والكود والقضايا والطلبات github-search setup guide how to use github-search github-search alternative github-search vs git search github-search install what is github-search github-search api github-search commands github-search tutorial GitHub 搜索工具 GitHub 搜索命令 GitHub API 搜索 仓库搜索 代码搜索 问题搜索 PR 搜索 命令行工具 Searches repositories using the gh search repos command Supports code search with gh search code Enables issue search using gh search issues Allows pull request search with gh search prs Utilizes Direct API Search for complex queries Automatically URL-encodes queries for precise results github-search is a skill that allows for efficient searching of GitHub repositories, code, issues, and pull requests using the gh search command and Direct API Search.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('toilahuongg/submission-design/shopify-metafields', 'community', 'toilahuongg', 'submission-design', 'toilahuongg/submission-design', 'shopify-metafields', 0, 0, 42, '2026-03-06T12:59:22.202Z', '2026-03-06T13:32:43.672Z', '441022fbededbed02ceebc72f92efc2d15ad1ca2f6484d16fa8256fb2269dfcd', '{"id":"toilahuongg/submission-design/shopify-metafields","name":"shopify-metafields","description":{"en":"The shopify-metafields skill allows developers to store additional data on Shopify resources, such as products and orders, using custom namespaces, keys, and data types. This benefits e-commerce developers and businesses seeking to extend Shopify''s default schema.","es":"Los metafields de Shopify permiten almacenar datos adicionales en recursos como productos y clientes. Aprende a utilizarlos con nuestra guía.","fr":"Les metafields Shopify permettent de stocker des données supplémentaires sur des ressources telles que des produits et des clients. Découvrez comment les utiliser avec notre guide.","de":"Die Metafields von Shopify ermöglichen die Speicherung von zusätzlichen Daten in Ressourcen wie Produkten und Kunden. Erfahren Sie, wie Sie sie verwenden mit unserem Leitfaden.","pt":"Os metafields do Shopify permitem armazenar dados adicionais em recursos como produtos e pedidos","ru":"Метаполя Shopify позволяют хранить дополнительные данные о продуктах и заказах","ar":"تتيح الحقول الفرعية في Shopify تخزين البيانات الإضافية للمنتجات والطلبات"},"seo":{"title":{"en":"shopify-metafields: Mastering Custom Data Storage | AI Ag...","es":"Guía de configuración de Shopify Metafields para desarrol...","fr":"Guide de mise en place des metafields Shopify pour les dé...","de":"Einrichtungsleitfaden für Shopify Metafields für Entwickler","pt":"Guia de Configuração de Metafields do Shopify","ru":"Руководство по настройке метаполей Shopify ИИ Агенты","ar":"دليل إعداد الحقول الفرعية في Shopify"},"description":{"en":"Unlock the full potential of Shopify with metafields! Learn how to store custom data on products, orders, and more. Get started with our expert guide and tra...","es":"Aprende a utilizar los metafields de Shopify para almacenar datos adicionales en recursos como productos, pedidos y clientes. Herramientas de IA para desarro...","fr":"Découvrez comment utiliser les metafields Shopify pour stocker des données supplémentaires sur des ressources telles que des produits, des commandes et des c...","de":"Erfahren Sie, wie Sie die Metafields von Shopify verwenden, um zusätzliche Daten in Ressourcen wie Produkten, Bestellungen und Kunden zu speichern. KI-Tools ...","pt":"Aprenda a usar metafields do Shopify para armazenar dados adicionais em recursos como produtos, pedidos e clientes","ru":"Используйте метаполя Shopify для хранения дополнительных данных о продуктах, заказах и клиентах с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام الحقول الفرعية في Shopify لتخزين البيانات الإضافية للمنتجات والطلبات والعملاء"},"definition":{"en":"shopify-metafields is a feature that enables storing custom data on Shopify resources, including products, orders, and customers, using namespaces, keys, and specific data types like single_line_text_field and json.","es":"Los metafields de Shopify son campos personalizados que permiten almacenar datos adicionales en recursos como productos y clientes.","fr":"Les metafields Shopify sont des champs personnalisés qui permettent de stocker des données supplémentaires sur des ressources telles que des produits et des clients.","de":"Die Metafields von Shopify sind benutzerdefinierte Felder, die die Speicherung von zusätzlichen Daten in Ressourcen wie Produkten und Kunden ermöglichen.","pt":"Metafields são campos personalizados que armazenam dados adicionais em recursos do Shopify","ru":"Метаполя - это пользовательские поля, которые хранят дополнительные данные о ресурсах Shopify","ar":"الحقول الفرعية هي حقول مخصصة لتخزين البيانات الإضافية للموارد في Shopify"},"features":{"en":["Stores custom data on Shopify resources using namespaces and keys","Supports various data types, including single_line_text_field, number_integer, and json","Allows grouping of custom data using namespaces, such as my_app or global","Enables attachment of custom data to specific resources, like products or orders","Utilizes a specific owner to attach data to resources, such as a product"],"es":["Almacenamiento de datos adicionales en recursos como productos y clientes","Uso de espacios de nombres para organizar los metafields","Soporte para diferentes tipos de datos, como texto y números","Asignación de propietarios a los metafields para controlar el acceso","Uso de claves para identificar los metafields de forma única"],"fr":["Stockage de données supplémentaires sur des ressources telles que des produits et des clients","Utilisation d''espaces de noms pour organiser les metafields","Prise en charge de différents types de données, tels que du texte et des nombres","Attribution de propriétaires aux metafields pour contrôler l''accès","Utilisation de clés pour identifier les metafields de manière unique"],"de":["Speicherung von zusätzlichen Daten in Ressourcen wie Produkten und Kunden","Verwendung von Namensräumen, um die Metafields zu organisieren","Unterstützung für verschiedene Datentypen, wie Text und Zahlen","Zuweisung von Besitzern zu den Metafields, um den Zugriff zu kontrollieren","Verwendung von Schlüsseln, um die Metafields eindeutig zu identifizieren"],"pt":["Namespace para agrupar metafields","Chaves para identificar campos específicos","Tipos de dados para armazenar informações","Proprietário para vincular metafields a recursos","Suporte a campos de texto único e número inteiro","Suporte a campos JSON"],"ru":["Пространство имён для группировки метаполей","Ключи для идентификации конкретных полей","Типы данных для хранения информации","Владелец для привязки метаполей к ресурсам","Поддержка полей текста и целых чисел","Поддержка полей JSON"],"ar":["مساحة اسم لتقسيم الحقول الفرعية","مفاتيح لتحديد الحقول المحددة","أنواع البيانات لتخزين المعلومات","المالك لربط الحقول الفرعية بالموارد","دعم حقول النص الواحد والأرقام الصحيحة","دعم حقول JSON"]},"keywords":{"en":["how to use shopify metafields","shopify metafields setup guide","what is shopify metafields","shopify metafields alternative","shopify metafields vs custom attributes","shopify metafields install","shopify metafields namespace","shopify metafields data types","shopify metafields for e-commerce"],"es":["shopify metafields","desarrollo de shopify","herramientas de ia para desarrolladores","almacenamiento de datos en shopify","personalización de shopify","metafields de shopify","guias de shopify","desarrollo de comercio electrónico"],"fr":["metafields shopify","développement shopify","outils ia pour développeurs","stockage de données sur shopify","personnalisation de shopify","metafields de shopify","guides shopify","développement de commerce électronique"],"de":["shopify metafields","shopify entwickler","ki-tools für entwickler","datenspeicherung in shopify","anpassung von shopify","metafields von shopify","shopify-leitfäden","entwicklung von e-commerce"],"pt":["metafields shopify","configurar metafields","usar metafields","armazenar dados adicionais","recursos shopify","campos personalizados","namespace metafields","chaves metafields","tipos de dados metafields"],"ru":["метаполя shopify","настройка метаполей","использование метаполей","хранение дополнительных данных","ресурсы shopify","пользовательские поля","пространство имён метаполей","ключи метаполей","типы данных метаполей","ИИ Агенты"],"ar":["حقول فرعية شوبيفاي","إعداد الحقول الفرعية","استخدام الحقول الفرعية","تخزين البيانات الإضافية","موارد شوبيفاي","حقول مخصصة","مساحة اسم الحقول الفرعية","مفاتيح الحقول الفرعية","أنواع البيانات الحقول الفرعية"]}},"owner":"toilahuongg","repo":"submission-design","repoPath":"toilahuongg/submission-design","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.202Z","topics":[],"category":"community","skillMd":{"name":"shopify-metafields","description":"Guide for working with Shopify Metafields. Covers definitions, storing custom data, accessing via Liquid, and GraphQL mutations.","bodyPreview":"# Shopify Metafields\n\nMetafields allow you to store additional data on Shopify resources (Products, Orders, Customers, Shops) that aren''t included in the default schema (e.g., \"washing instructions\" for a product).\n\n## 1. Concepts\n\n-   **Namespace**: Grouping folder (e.g., `my_app`, `global`).\n-   **Key**: Specific field name (e.g., `washing_instructions`).\n-   **Type**: Data type (e.g., `single_line_text_field`, `number_integer`, `json`).\n-   **Owner**: The resource attaching the data (Product","body":"# Shopify Metafields\n\nMetafields allow you to store additional data on Shopify resources (Products, Orders, Customers, Shops) that aren''t included in the default schema (e.g., \"washing instructions\" for a product).\n\n## 1. Concepts\n\n-   **Namespace**: Grouping folder (e.g., `my_app`, `global`).\n-   **Key**: Specific field name (e.g., `washing_instructions`).\n-   **Type**: Data type (e.g., `single_line_text_field`, `number_integer`, `json`).\n-   **Owner**: The resource attaching the data (Product ID, Shop ID).\n\n## 2. Metafield Definitions (Standard)\n\nAlways use **Metafield Definitions** (pinned metafields) when possible. This integrates them into the Admin UI and ensures standard processing.\n\n-   **Create**: Settings > Custom Data > [Resource] > Add definition.\n-   **Access**: `namespace.key`\n\n## 3. Accessing in Liquid\n\nTo display metafield data on the Storefront:\n\n```liquid\n<!-- Accessing a product metafield -->\n<p>Washing: {{ product.metafields.my_app.washing_instructions }}</p>\n\n<!-- Accessing a file/image metafield -->\n{% assign file = product.metafields.my_app.size_chart.value %}\n<img src=\"{{ file | image_url: width: 500 }}\" />\n\n<!-- Checking existence -->\n{% if product.metafields.my_app.instructions != blank %}\n   ...\n{% endif %}\n```\n\n## 4. Reading via API (GraphQL)\n\n```graphql\nquery {\n  product(id: \"gid://shopify/Product/123\") {\n    title\n    metafield(namespace: \"my_app\", key: \"instructions\") {\n      value\n      type\n    }\n  }\n}\n```\n\n## 5. Writing via API (GraphQL)\n\nTo create or update a metafield, use `metafieldsSet`.\n\n```graphql\nmutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {\n  metafieldsSet(metafields: $metafields) {\n    metafields {\n      id\n      namespace\n      key\n      value\n    }\n    userErrors {\n      field\n      message\n    }\n  }\n}\n\n/* Variables */\n{\n  \"metafields\": [\n    {\n      \"ownerId\": \"gid://shopify/Product/123\",\n      \"namespace\": \"my_app\",\n      \"key\": \"instructions\",\n      \"type\": \"single_line_text_field\",\n      \"value\": \"Wash cold, tumble dry.\"\n    }\n  ]\n}\n```\n\n## 6. Private Metafields\n\nIf you want data to be **hidden from other apps** and the storefront, use Private Metafields. Note: These cannot be accessed via Liquid directly.\n\n-   Use `privateMetafield` queries/mutations.\n-   Requires explicit `read_private_metafields` / `write_private_metafields` scope (rarely used now, `app_data` metafields are preferred for app-specific valid storage).\n"},"lastSynced":"2026-03-06T13:32:43.672Z","agentAnalysis":{"suitability":{"en":"Perfect for E-commerce Agents needing custom data storage and retrieval on Shopify resources","zh":"非常适合需要在Shopify资源上进行自定义数据存储和检索的电子商务代理","ja":"Shopifyリソース上でカスタムデータのストレージと取得が必要な電子商取引エージェントに最適","ko":"Shopify 리소스에서 사용자 지정 데이터 저장 및 검색이 필요한 전자 상거래 에이전트에 적합","es":"Perfecto para agentes de comercio electrónico que necesitan almacenamiento y recuperación de datos personalizados en recursos de Shopify","fr":"Parfait pour les agents de commerce électronique ayant besoin d''un stockage et d''une récupération de données personnalisés sur les ressources Shopify","de":"Perfekt für E-Commerce-Agents, die benutzerdefinierten Datenspeicher und -abruf auf Shopify-Ressourcen benötigen","pt":"Perfeito para Agentes de Comércio Eletrônico que necessitam de armazenamento e recuperação de dados personalizados em recursos do Shopify","ru":"Идеально для агентов электронной коммерции, которым требуются пользовательское хранение и извлечение данных в ресурсах Shopify","ar":"مثالي للوكلاء التجاريين الإلكترونيين الذين يحتاجون إلى تخزين و استرجاع بيانات مخصصة في موارد Shopify"},"recommendation":{"en":"Empowers agents to store and manage additional data on Shopify products, orders, and customers using custom namespaces, keys, and data types, such as single_line_text_field, number_integer, and json, enabling advanced e-commerce automation and analysis","zh":"赋予代理商使用自定义命名空间、键和数据类型（如single_line_text_field、number_integer和json）在Shopify产品、订单和客户上存储和管理额外数据，从而实现高级电子商务自动化和分析","ja":"カスタムネームスペース、キー、およびデータ型（single_line_text_field、number_integer、jsonなど）を使用して、Shopify製品、注文、および顧客に追加のデータを保存および管理できるようにエージェントをEmpowerし、高度な電子商取引の自動化および分析を可能にします","ko":"사용자 지정 네임스페이스, 키 및 데이터 유형(such as single_line_text_field, number_integer, json)을 사용하여 Shopify 제품, 주문 및 고객에 추가 데이터를 저장 및 관리할 수 있도록 에이전트를 활성화하여 고급 전자 상거래 자동화 및 분석을 가능하게 합니다","es":"Habilita a los agentes a almacenar y gestionar datos adicionales en productos, pedidos y clientes de Shopify utilizando espacios de nombres personalizados, claves y tipos de datos, como single_line_text_field, number_integer y json, lo que permite una automatización y análisis de comercio electrónico avanzados","fr":"Permet aux agents de stocker et de gérer des données supplémentaires sur les produits, les commandes et les clients Shopify en utilisant des espaces de noms personnalisés, des clés et des types de données tels que single_line_text_field, number_integer et json, permettant ainsi une automatisation et une analyse de commerce électronique avancées","de":"Ermächtigt Agents, zusätzliche Daten auf Shopify-Produkten, -Bestellungen und -Kunden mit benutzerdefinierten Namensräumen, Schlüsseln und Datentypen wie single_line_text_field, number_integer und json zu speichern und zu verwalten, ermöglicht so eine erweiterte Automatisierung und Analyse des E-Commerce","pt":"Habilita os agentes a armazenar e gerenciar dados adicionais em produtos, pedidos e clientes do Shopify usando namespaces, chaves e tipos de dados personalizados, como single_line_text_field, number_integer e json, permitindo automação e análise avançadas de comércio eletrônico","ru":"Позволяет агентам хранить и управлять дополнительными данными о продуктах, заказах и клиентах Shopify, используя пользовательские пространства имен, ключи и типы данных, такие как single_line_text_field, number_integer и json, что обеспечивает продвинутую автоматизацию и анализ электронной коммерции","ar":"يمكن للوكلاء تخزين و إدارة بيانات إضافية حول المنتجات و الطلبات و العملاء في Shopify باستخدام مساحات أسماء و مفاتيح و أنواع بيانات مخصصة مثل single_line_text_field و number_integer و json، و ذلك لتمكين автоматиة وتحليل متقدمين للتجارة الإلكترونية"},"useCases":{"en":["Storing product-specific data, such as washing instructions or nutritional information","Managing customer preferences and order history using custom metafields","Automating workflows based on metafield data, such as triggering notifications or updates"],"zh":["存储特定产品数据，例如洗涤说明或营养信息","使用自定义元字段管理客户偏好和订单历史","根据元字段数据自动化工作流程，例如触发通知或更新"],"ja":["特定製品データ（洗濯方法の説明や栄養情報など）を保存する","カスタムメタフィールドを使用して顧客の好みや注文履歴を管理する","メタフィールドデータに基づいてワークフローを自動化する（通知や更新のトリガーなど）"],"ko":["특정 제품 데이터(세탁 지침 또는 영양 정보 등)를 저장","사용자 지정 메타 필드를 사용하여 고객의 선호도 및 주문 내력을 관리","메타 필드 데이터를 기반으로 워크플ロー 자동화(알림 또는 업데이트 트리거 등)"],"es":["Almacenar datos específicos de productos, como instrucciones de lavado o información nutricional","Gestionar preferencias de clientes y historial de pedidos utilizando metafields personalizados","Automatizar flujos de trabajo basados en datos de metafields, como desencadenar notificaciones o actualizaciones"],"fr":["Stockage de données spécifiques aux produits, telles que les instructions de lavage ou les informations nutritionnelles","Gestion des préférences des clients et de l''historique des commandes à l''aide de metafields personnalisés","Automation des flux de travail basés sur les données de metafields, telles que le déclenchement de notifications ou de mises à jour"],"de":["Speicherung von produktspezifischen Daten, wie Waschanweisungen oder Nährinformationen","Verwaltung von Kundenpräferenzen und Bestellhistorie mithilfe benutzerdefinierter Metafelder","Automatisierung von Workflows basierend auf Metafeld-Daten, wie z.B. Auslösen von Benachrichtigungen oder Updates"],"pt":["Armazenar dados específicos de produtos, como instruções de lavagem ou informações nutricionais","Gerenciar preferências de clientes e histórico de pedidos usando metafields personalizados","Automatizar fluxos de trabalho com base em dados de metafields, como disparar notificações ou atualizações"],"ru":["Хранение данных, специфичных для продукта, таких как инструкции по стирке или информация о питании","Управление предпочтениями клиентов и историей заказов с помощью пользовательских metafields","Автоматизация рабочих процессов на основе данных metafields, таких как запуск уведомлений или обновлений"],"ar":["تخزين بيانات محددة للمنتجات، مثل إرشادات الغسيل أو المعلومات الغذائية","إدارة تفضيلات العملاء و سجل الطلبات باستخدام حقول مخصصة","تأتمتة سير العمل بناءً على بيانات الحقول، مثل تشغيل الإشعارات أو التحديثات"]},"limitations":{"en":["Requires Shopify API access and authentication","Limited to Shopify resources, such as products, orders, customers, and shops"],"zh":["需要Shopify API访问和认证","仅限Shopify资源，如产品、订单、客户和商店"],"ja":["Shopify APIへのアクセスと認証が必要","Shopifyリソース（製品、注文、顧客、ショップなど）に限定される"],"ko":["Shopify API 액세스 및 인증이 필요","Shopify 리소스(제품, 주문, 고객, 상점 등)로 제한"],"es":["Requiere acceso y autenticación a la API de Shopify","Limitado a recursos de Shopify, como productos, pedidos, clientes y tiendas"],"fr":["Nécessite un accès et une authentification à l''API Shopify","Limité aux ressources Shopify, telles que les produits, les commandes, les clients et les magasins"],"de":["Benötigt Zugriff und Authentifizierung auf die Shopify-API","Begrenzt auf Shopify-Ressourcen, wie Produkte, Bestellungen, Kunden und Shops"],"pt":["Exige acesso e autenticação à API do Shopify","Limitado a recursos do Shopify, como produtos, pedidos, clientes e lojas"],"ru":["Требует доступа и аутентификации в API Shopify","Ограничен ресурсами Shopify, такими как продукты, заказы, клиенты и магазины"],"ar":["يتطلب الوصول و التحقق من صحة واجهة برمجة التطبيقات Shopify","محدود بموارد Shopify، مثل المنتجات و الطلبات و العملاء و المتاجر"]},"version":4},"contentHash":"441022fbededbed02ceebc72f92efc2d15ad1ca2f6484d16fa8256fb2269dfcd","qualityScore":42}');
