INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('toilahuongg/submission-design/shopify-metafields', 'shopify-metafields', 'toilahuongg', 'submission-design', 'community', 'shopify-metafields toilahuongg submission-design community The shopify-metafields skill allows developers to store additional data on Shopify resources, such as products and orders, using custom namespaces, keys, and data types. This benefits e-commerce developers and businesses seeking to extend Shopify''s default schema. Los metafields de Shopify permiten almacenar datos adicionales en recursos como productos y clientes. Aprende a utilizarlos con nuestra guía. Les metafields Shopify permettent de stocker des données supplémentaires sur des ressources telles que des produits et des clients. Découvrez comment les utiliser avec notre guide. Die Metafields von Shopify ermöglichen die Speicherung von zusätzlichen Daten in Ressourcen wie Produkten und Kunden. Erfahren Sie, wie Sie sie verwenden mit unserem Leitfaden. Os metafields do Shopify permitem armazenar dados adicionais em recursos como produtos e pedidos Метаполя Shopify позволяют хранить дополнительные данные о продуктах и заказах تتيح الحقول الفرعية في Shopify تخزين البيانات الإضافية للمنتجات والطلبات how to use shopify metafields shopify metafields setup guide what is shopify metafields shopify metafields alternative shopify metafields vs custom attributes shopify metafields install shopify metafields namespace shopify metafields data types shopify metafields for e-commerce Stores custom data on Shopify resources using namespaces and keys Supports various data types, including single_line_text_field, number_integer, and json Allows grouping of custom data using namespaces, such as my_app or global Enables attachment of custom data to specific resources, like products or orders Utilizes a specific owner to attach data to resources, such as a product shopify-metafields is a feature that enables storing custom data on Shopify resources, including products, orders, and customers, using namespaces, keys, and specific data types like single_line_text_field and json.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('boku-miyaji/claude_dev/design-principles', 'community', 'boku-miyaji', 'claude_dev', 'boku-miyaji/claude_dev', 'design-principles', 0, 0, 42, '2026-03-06T12:59:22.252Z', '2026-03-06T14:44:18.979Z', '57fa00a86a879ceee59ee9949fa222872b8288258a9243cfb471f45346fe7716', '{"id":"boku-miyaji/claude_dev/design-principles","name":"design-principles","description":{"en":"The design-principles skill enforces precise, crafted design for enterprise software, SaaS dashboards, and web applications, benefiting developers and designers. It ensures polished interfaces with intentional personality.","zh":"设计原则技能为企业软件、SaaS仪表板和Web应用程序提供精确的设计","ja":"デザイン原則技能は、エンタープライズソフトウェア、SaaSダッシュボード、ウェブアプリケーションに精密な設計を提供する","ko":"디자인 원칙 기술은 엔터프라이즈 소프트웨어, SaaS 대시보드, 웹 애플리케이션을 위한 정교한 디자인을 제공합니다","es":"Los principios de diseño permiten crear interfaces de usuario personalizadas y pulidas para software y aplicaciones web. Aprende a aplicarlos en tus proyectos.","fr":"Les principes de conception permettent de créer des interfaces utilisateur personnalisées et polies pour les logiciels et les applications web. Découvrez comment les appliquer dans vos projets.","de":"Die Designprinzipien ermöglichen die Erstellung von benutzerdefinierten und polierten Benutzeroberflächen für Software und Webanwendungen. Erfahren Sie, wie Sie sie in Ihren Projekten anwenden können.","pt":"O skill de princípios de design permite a criação de interfaces de usuário precisas e personalizadas para software de empresa e aplicações web","ru":"Навык принципов дизайна позволяет создавать точные и персонализированные интерфейсы пользователя для enterprise софтвера и веб-приложений","ar":"مهارة مبادئ التصميم تمكن من إنشاء واجهات مستخدم دقيقة ومخصصة لبرمجيات الشركات وتطبيقات الويب"},"seo":{"title":{"en":"Design-Principles: Polished Interface Setup Guide | AI Ag...","zh":"设计原则设置指