INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('boku-miyaji/claude_dev/design-principles', 'design-principles', 'boku-miyaji', 'claude_dev', 'community', 'design-principles boku-miyaji claude_dev community The design-principles skill enforces precise, crafted design for enterprise software, SaaS dashboards, and web applications, benefiting developers and designers. It ensures polished interfaces with intentional personality. 设计原则技能为企业软件、SaaS仪表板和Web应用程序提供精确的设计 デザイン原則技能は、エンタープライズソフトウェア、SaaSダッシュボード、ウェブアプリケーションに精密な設計を提供する 디자인 원칙 기술은 엔터프라이즈 소프트웨어, SaaS 대시보드, 웹 애플리케이션을 위한 정교한 디자인을 제공합니다 Los principios de diseño permiten crear interfaces de usuario personalizadas y pulidas para software y aplicaciones web. Aprende a aplicarlos en tus proyectos. Les principes de conception permettent de créer des interfaces utilisateur personnalisées et polies pour les logiciels et les applications web. Découvrez comment les appliquer dans vos projets. Die Designprinzipien ermöglichen die Erstellung von benutzerdefinierten und polierten Benutzeroberflächen für Software und Webanwendungen. Erfahren Sie, wie Sie sie in Ihren Projekten anwenden können. O skill de princípios de design permite a criação de interfaces de usuário precisas e personalizadas para software de empresa e aplicações web Навык принципов дизайна позволяет создавать точные и персонализированные интерфейсы пользователя для enterprise софтвера и веб-приложений مهارة مبادئ التصميم تمكن من إنشاء واجهات مستخدم دقيقة ومخصصة لبرمجيات الشركات وتطبيقات الويب how to use design-principles what is design-principles design-principles alternative design-principles vs material design design-principles install design-principles setup guide enterprise software design principles SaaS dashboard design best practices intentional interface design 设计原则 AI设计工具 企业软件设计 SaaS仪表板设计 Web应用程序设计 Jony Ive设计 精确设计 产品设计 Commits to a design direction before writing code Thinks about context to create intentional interfaces Enforces Jony Ive-level precision in design Creates polished interfaces for specific contexts Supports design for enterprise software, SaaS dashboards, and web applications design-principles is a skill that enforces precise design for enterprise software, emphasizing intentional personality and polished interfaces.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kayistandhere/Career-Gap-Architect/nextjs-best-practices', 'community', 'kayistandhere', 'Career-Gap-Architect', 'kayistandhere/Career-Gap-Architect', 'nextjs-best-practices', 0, 0, 42, '2026-03-07T01:49:01.514Z', '2026-03-07T01:59:28.051Z', '50bf04377ef5686f02884153c4115168ef2ec21b481bdac732c27389e4f3d3ef', '{"id":"kayistandhere/Career-Gap-Architect/nextjs-best-practices","name":"nextjs-best-practices","description":{"en":"The nextjs-best-practices skill provides developers with principles for Next.js App Router development, including decision trees for Server vs Client Components. This skill benefits Next.js developers looking to optimize their application''s performance.","zh":"Next.js 最佳实践指南，帮助您优化应用性能和开发效率，包括 Server 和 Client 组件的选择","ja":"Next.js ベストプラクティスの設定方法を学び、Server と Client コンポーネントの選択を最適化する","ko":"Next.js 베스트 프랙티스 설정 가이드, 애플리케이션 성능과 개발 효율을 최적화하는 데 도움이 됩니다","es":"Next.js es un framework para desarrollar aplicaciones web de alta calidad. Nuestras mejores prácticas te ayudan a configurar y optimizar tus proyectos.","fr":"Next.js est un framework pour développer des applications web de haute qualité. Nos bonnes pratiques vous aident à configurer et à optimiser vos projets.","de":"Next.js ist ein Framework für die Entwicklung von hochwertigen Webanwendungen. Unsere Best Practices helfen Ihnen, Ihre Projekte zu konfigurieren und zu optimieren.","pt":"Desenvolva aplicações Next.js com eficiência usando Server e Client Components. Aprenda a decidir quando usar cada um","ru":"Разрабатывайте приложения Next.js с помощью Server и Client Components. Узнайте, когда использовать каждый из них","ar":"طور تطبيقات Next.js بفعالية باستخدام مكونات Server و Client. تعرف على كيفية تحديد الوقت المناسب لاستخدام كل منهما"},"seo":{"title":{"en":"nextjs-best-practices: Optimized Next.js App Router Devel...","zh":"Next.js 最佳实践指南：AIエージェント技能","ja":"Next.js ベストプラクティス設定ガイド：AIエージェント","ko":"Next.js 베스트 프랙티스 설정 가이드: AI 에이전트","es":"Guía de configuración de Next.js: Mejores prácticas para ...","fr":"Guide de configuration Next.js : Bonnes pratiques pour le...","de":"Next.js-Konfigurationsleitfaden: Best Practices für Entwi...","pt":"Melhores Práticas Next.js: Guia de Configuração","ru":"Лучшие практики Next.js: Настройка и разработка с ИИ Аген...","ar":"أفضل الممارسات ل Next.js: دليل الإعداد مع أدوات الذكاء ال..."},"description":{"en":"Unlock efficient Next.js development with our expert guide - learn how to decide between Server and Client Components for optimal performance","zh":"了解 Next.js 最佳实践，优化您的应用性能和开发效率，使用 AI エージェント技能","ja":"Next.js アプリのパフォーマンスと開発効率を最適化するためのベストプラクティスを学び、AI エージェントを活用する","ko":"Next.js 애플리케이션의 성능과 개발 효율을 최적화하는 방법을 배우고, AI 에이전트 기능을 사용하세요","es":"Aprende a configurar Next.js con nuestras mejores prácticas para desarrolladores. Mejora el rendimiento y la seguridad de tus aplicaciones.","fr":"Découvrez comment configurer Next.js avec nos meilleures pratiques pour les développeurs. Améliorez les performances et la sécurité de vos applications.","de":"Erfahren Sie, wie Sie Next.js mit unseren Best Practices für Entwickler konfigurieren. Verbessern Sie die Leistung und Sicherheit Ihrer Anwendungen.","pt":"Aprenda as melhores práticas para desenvolver aplicações Next.js com Server e Client Components, incluindo dicas para data fetching e interatividade","ru":"Узнайте о лучших практиках разработки приложений Next.js с помощью Server и Client Components, включая советы по получению данных и интерактивности с ИИ Аген...","ar":"تعرف على أفضل الممارسات لتطوير تطبيقات Next.js باستخدام مكونات Server و Client، بما في ذلك نصائح لFetching البيانات والتفاعل مع أدوات الذكاء الاصطناعي"},"definition":{"en":"nextjs-best-practices is a set of guidelines for developing efficient Next.js applications, focusing on Server and Client Component decision-making","zh":"Next.js 最佳实践是指一套优化 Next.js 应用的原则和方法，包括 Server 和 Client 组件的选择","ja":"Next.js ベストプラクティスとは、Next.js アプリを最適化するための原則と方法のセットであり、Server と Client コンポーネントの選択が含まれる","ko":"Next.js 베스트 프랙티스는 Next.js 애플리케이션을 최적화하는 원칙과 방법의 집합으로, Server와 Client 컴포넌트의 선택을 포함합니다","es":"Las mejores prácticas de Next.js son principios para desarrollar aplicaciones web escalables y seguras con el framework Next.js","fr":"Les bonnes pratiques de Next.js sont des principes pour développer des applications web évolutives et sécurisées avec le framework Next.js","de":"Die Best Practices von Next.js sind Prinzipien für die Entwicklung von skalierbaren und sicheren Webanwendungen mit dem Next.js-Framework","pt":"Melhores práticas para desenvolver aplicações Next.js com Server e Client Components","ru":"Лучшие практики разработки приложений Next.js с помощью Server и Client Components","ar":"أفضل الممارسات لتطوير تطبيقات Next.js باستخدام مكونات Server و Client"},"features":{"en":["Decision tree for choosing between Server and Client Components","Guidance on using ''use client'' for Client Components","Default Server Component usage for data fetching and layout","Splitting components into Server parent and Client child for optimal performance","Usage of useState, useEffect, and event handlers in Client Components"],"zh":["Server 和 Client 组件的选择","数据获取和布局优化","静态内容和交互式内容的分离","useState 和 useEffect 的使用","事件处理和直接数据获取"],"ja":["Server と Client コンポーネントの選択","データ取得とレイアウトの最適化","静的コンテンツとインタラクティブコンテンツの分離","useState と useEffect の使用","イベントハンドリングと直接データ取得"],"ko":["Server와 Client 컴포넌트의 선택","데이터 가져오기와 레이아웃 최적화","정적 콘텐츠와 상호작용 콘텐츠의 분리","useState와 useEffect의 사용","이벤트 처리와 직접 데이터 가져오기"],"es":["Diferenciación entre componentes del servidor y del cliente","Uso de ''use client'' para componentes del cliente","Uso de componentes del servidor para la recuperación de datos","División de componentes en padre servidor y hijo cliente","Optimización del rendimiento con la configuración adecuada","Mejora de la seguridad con la autenticación y autorización adecuadas"],"fr":["Différenciation entre les composants serveur et client","Utilisation de ''use client'' pour les composants client","Utilisation de composants serveur pour la récupération de données","Division des composants en parent serveur et enfant client","Optimisation des performances avec la configuration appropriée","Amélioration de la sécurité avec l''authentification et l''autorisation appropriées"],"de":["Unterscheidung zwischen Server- und Client-Komponenten","Verwendung von ''use client'' für Client-Komponenten","Verwendung von Server-Komponenten für die Datenabruf","Aufteilung von Komponenten in Server-Eltern und Client-Kind","Leistungsoptimierung mit der richtigen Konfiguration","Sicherheitsverbesserung mit der richtigen Authentifizierung und Autorisierung"],"pt":["Decisão de uso de Server ou Client Components com base em requisitos de interatividade e data fetching","Uso de Server Components para layout e conteúdo estático","Uso de Client Components para formulários e interatividade","Divisão de componentes em Server e Client para melhor desempenho","Uso de ''use client'' para indicar componentes Client","Uso de componentes Server para fetching de dados diretos"],"ru":["Принятие решения об использовании Server или Client Components на основе требований к интерактивности и получению данных","Использование Server Components для макета и статического контента","Использование Client Components для форм и интерактивности","Разделение компонентов на Server и Client для лучшей производительности","Использование ''use client'' для указания компонентов Client","Использование компонентов Server для прямого получения данных"],"ar":["اتخاذ قرار باستخدام مكونات Server أو Client بناءً على متطلبات التفاعل و Fetching البيانات","استخدام مكونات Server لAYOUT و المحتوى الثابت","استخدام مكونات Client لأشكال و التفاعل","تقسيم المكونات إلى Server و Client لتحسين الأداء","استخدام ''use client'' للإشارة إلى مكونات Client","استخدام مكونات Server لFetching البيانات المباشر"]},"keywords":{"en":["nextjs-best-practices setup guide","how to use nextjs-best-practices","nextjs-best-practices vs react","what is nextjs-best-practices","nextjs-best-practices alternative","nextjs-best-practices install","nextjs app router development","server vs client components in nextjs","optimizing nextjs application performance"],"zh":["Next.js 最佳实践","Server 和 Client 组件","数据获取和布局优化","AI エージェント技能","Next.js 性能优化","开发效率提高"],"ja":["Next.js ベストプラクティス","Server と Client コンポーネント","データ取得とレイアウトの最適化","AI エージェント","Next.js パフォーマンス最適化","開発効率の向上"],"ko":["Next.js 베스트 프랙티스","Server와 Client 컴포넌트","데이터 가져오기와 레이아웃 최적화","AI 에이전트","Next.js 성능 최적화","개발 효율성 향상"],"es":["Next.js","mejores prácticas","desarrollo web","componentes del servidor","componentes del cliente","use client","optimización del rendimiento","seguridad web","autenticación y autorización","herramientas de desarrollo"],"fr":["Next.js","bonnes pratiques","développement web","composants serveur","composants client","use client","optimisation des performances","sécurité web","authentification et autorisation","outils de développement"],"de":["Next.js","Best Practices","Webentwicklung","Server-Komponenten","Client-Komponenten","use client","Leistungsoptimierung","Web-Sicherheit","Authentifizierung und Autorisierung","Entwicklungstools"],"pt":["nextjs melhores práticas","desenvolvimento nextjs","server components nextjs","client components nextjs","data fetching nextjs","interatividade nextjs","react nextjs","nextjs tutorial"],"ru":["лучшие практики nextjs","разработка приложений nextjs","серверные компоненты nextjs","клиентские компоненты nextjs","получение данных nextjs","интерактивность nextjs","react nextjs","nextjs учебник","ИИ Агенты для nextjs"],"ar":["أفضل الممارسات ل nextjs","تطوير تطبيقات nextjs","مكونات خادم nextjs","مكونات عميل nextjs","fetching البيانات nextjs","التفاعل nextjs","react nextjs","دليل nextjs","أدوات الذكاء الاصطناعي ل nextjs"]}},"owner":"kayistandhere","repo":"Career-Gap-Architect","repoPath":"kayistandhere/Career-Gap-Architect","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.514Z","topics":[],"category":"community","skillMd":{"name":"nextjs-best-practices","description":"Next.js App Router principles. Server Components, data fetching, routing patterns.","bodyPreview":"# Next.js Best Practices\n\n> Principles for Next.js App Router development.\n\n---\n\n## 1. Server vs Client Components\n\n### Decision Tree\n\n```\nDoes it need...?\n│\n├── useState, useEffect, event handlers\n│   └── Client Component (''use client'')\n│\n├── Direct data fetching, no interactivity\n│   └── Server Component (default)\n│\n└── Both? \n    └── Split: Server parent + Client child\n```\n\n### By Default\n\n| Type | Use |\n|------|-----|\n| **Server** | Data fetching, layout, static content |\n| **Client** | Form","body":"# Next.js Best Practices\n\n> Principles for Next.js App Router development.\n\n---\n\n## 1. Server vs Client Components\n\n### Decision Tree\n\n```\nDoes it need...?\n│\n├── useState, useEffect, event handlers\n│   └── Client Component (''use client'')\n│\n├── Direct data fetching, no interactivity\n│   └── Server Component (default)\n│\n└── Both? \n    └── Split: Server parent + Client child\n```\n\n### By Default\n\n| Type | Use |\n|------|-----|\n| **Server** | Data fetching, layout, static content |\n| **Client** | Forms, buttons, interactive UI |\n\n---\n\n## 2. Data Fetching Patterns\n\n### Fetch Strategy\n\n| Pattern | Use |\n|---------|-----|\n| **Default** | Static (cached at build) |\n| **Revalidate** | ISR (time-based refresh) |\n| **No-store** | Dynamic (every request) |\n\n### Data Flow\n\n| Source | Pattern |\n|--------|---------|\n| Database | Server Component fetch |\n| API | fetch with caching |\n| User input | Client state + server action |\n\n---\n\n## 3. Routing Principles\n\n### File Conventions\n\n| File | Purpose |\n|------|---------|\n| `page.tsx` | Route UI |\n| `layout.tsx` | Shared layout |\n| `loading.tsx` | Loading state |\n| `error.tsx` | Error boundary |\n| `not-found.tsx` | 404 page |\n\n### Route Organization\n\n| Pattern | Use |\n|---------|-----|\n| Route groups `(name)` | Organize without URL |\n| Parallel routes `@slot` | Multiple same-level pages |\n| Intercepting `(.)` | Modal overlays |\n\n---\n\n## 4. API Routes\n\n### Route Handlers\n\n| Method | Use |\n|--------|-----|\n| GET | Read data |\n| POST | Create data |\n| PUT/PATCH | Update data |\n| DELETE | Remove data |\n\n### Best Practices\n\n- Validate input with Zod\n- Return proper status codes\n- Handle errors gracefully\n- Use Edge runtime when possible\n\n---\n\n## 5. Performance Principles\n\n### Image Optimization\n\n- Use next/image component\n- Set priority for above-fold\n- Provide blur placeholder\n- Use responsive sizes\n\n### Bundle Optimization\n\n- Dynamic imports for heavy components\n- Route-based code splitting (automatic)\n- Analyze with bundle analyzer\n\n---\n\n## 6. Metadata\n\n### Static vs Dynamic\n\n| Type | Use |\n|------|-----|\n| Static export | Fixed metadata |\n| generateMetadata | Dynamic per-route |\n\n### Essential Tags\n\n- title (50-60 chars)\n- description (150-160 chars)\n- Open Graph images\n- Canonical URL\n\n---\n\n## 7. Caching Strategy\n\n### Cache Layers\n\n| Layer | Control |\n|-------|---------|\n| Request | fetch options |\n| Data | revalidate/tags |\n| Full route | route config |\n\n### Revalidation\n\n| Method | Use |\n|--------|-----|\n| Time-based | `revalidate: 60` |\n| On-demand | `revalidatePath/Tag` |\n| No cache | `no-store` |\n\n---\n\n## 8. Server Actions\n\n### Use Cases\n\n- Form submissions\n- Data mutations\n- Revalidation triggers\n\n### Best Practices\n\n- Mark with ''use server''\n- Validate all inputs\n- Return typed responses\n- Handle errors\n\n---\n\n## 9. Anti-Patterns\n\n| ❌ Don''t | ✅ Do |\n|----------|-------|\n| ''use client'' everywhere | Server by default |\n| Fetch in client components | Fetch in server |\n| Skip loading states | Use loading.tsx |\n| Ignore error boundaries | Use error.tsx |\n| Large client bundles | Dynamic imports |\n\n---\n\n## 10. Project Structure\n\n```\napp/\n├── (marketing)/     # Route group\n│   └── page.tsx\n├── (dashboard)/\n│   ├── layout.tsx   # Dashboard layout\n│   └── page.tsx\n├── api/\n│   └── [resource]/\n│       └── route.ts\n└── components/\n    └── ui/\n```\n\n---\n\n> **Remember:** Server Components are the default for a reason. Start there, add client only when needed.\n"},"lastSynced":"2026-03-07T01:59:28.051Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing optimized Next.js App Router development and Server vs Client Component decision-making.","zh":"非常适合需要优化 Next.js App Router 开发和 Server vs Client 组件决策的前端代理。","ja":"Next.js の App Router 開発と Server vs Client コンポーネントの意思決定を最適化する必要があるフロントエンド エージェントに最適です。","ko":"Next.js App Router 개발과 Server vs Client 컴포넌트 결정에 최적화를 필요로 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan un desarrollo de Next.js App Router optimizado y toma de decisiones de componente Servidor vs Cliente.","fr":"Parfait pour les agents Frontend qui nécessitent un développement de Next.js App Router optimisé et une prise de décision de composant Serveur vs Client.","de":"Perfekt für Frontend-Agents, die eine optimierte Next.js App Router-Entwicklung und eine Entscheidungsfindung für Server- und Client-Komponenten benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de desenvolvimento de App Router do Next.js otimizado e tomada de decisão entre Componentes de Servidor e Cliente.","ru":"Идеально подходит для фронтенд-агентов, которым требуется оптимизированное развитие маршрутизатора приложения Next.js и принятие решений по серверным и клиентским компонентам.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تطوير مُحسّن لطريق التطبيق Next.js و اتخاذ القرارات بين مكونات الخادم و العميل."},"recommendation":{"en":"Empowers agents to optimize Next.js application performance by applying best practices for Server and Client Components, including decision trees for direct data fetching and interactivity using ''use client'' and Server Component defaults.","zh":"通过应用 Server 和 Client 组件的最佳实践，包括使用 ''use client'' 和 Server 组件默认值的决策树直接获取数据和交互性，赋予代理优化 Next.js 应用程序性能的能力。","ja":"''use client'' と Server コンポーネントのデフォルト値を使用した直接データ取得とインタラクティブ性のための意思決定ツリーを含む Server と Client コンポーネントのベストプラクティスを適用することで、Next.js アプリケーションのパフォーマンスを最適化するエージェントを可能にします。","ko":"''use client''와 Server 컴포넌트 기본값을 사용한 직접 데이터 가져오기와 상호작용을 위한 의사결정 트리를 포함하여 Server와 Client 컴포넌트에 대한 모범 사례를 적용하여 Next.js 애플리케이션의 성능을 최적화하는 에이전트를 가능하게 합니다.","es":"Habilita a los agentes a optimizar el rendimiento de la aplicación Next.js aplicando las mejores prácticas para los componentes Servidor y Cliente, incluyendo árboles de decisión para la recuperación directa de datos y la interactividad utilizando ''use client'' y valores predeterminados de componentes del servidor.","fr":"Permet aux agents d''optimiser les performances de l''application Next.js en appliquant les meilleures pratiques pour les composants Serveur et Client, y compris des arbres de décision pour la récupération directe de données et l''interactivité en utilisant ''use client'' et les valeurs par défaut des composants du serveur.","de":"Ermöglich es den Agenten, die Leistung der Next.js-Anwendung zu optimieren, indem sie die besten Praktiken für Server- und Client-Komponenten anwenden, einschließlich Entscheidungsbäume für die direkte Datenabfrage und Interaktivität unter Verwendung von ''use client'' und Server-Komponenten-Standardwerten.","pt":"Habilita os agentes a otimizar o desempenho do aplicativo Next.js aplicando as melhores práticas para Componentes de Servidor e Cliente, incluindo árvores de decisão para busca direta de dados e interatividade usando ''use client'' e padrões de Componentes de Servidor.","ru":"Позволяет агентам оптимизировать производительность приложения Next.js, применяя лучшие практики для серверных и клиентских компонентов, включая деревья решений для прямого извлечения данных и интерактивности с использованием ''use client'' и стандартов серверных компонентов.","ar":"تمكّن الوكلاء من تحسين أداء تطبيق Next.js عن طريق تطبيق أفضل الممارسات لمكونات الخادم و العميل، بما في ذلك أشجار القرار لاسترجاع البيانات المباشر و التفاعل باستخدام ''use client'' و الإعدادات الافتراضية لمكونات الخادم."},"useCases":{"en":["Optimizing Server vs Client Component decisions","Implementing efficient data fetching strategies","Improving application performance with split Server and Client components"],"zh":["优化 Server vs Client 组件决策","实施高效的数据获取策略","通过分离 Server 和 Client 组件来提高应用程序性能"],"ja":["Server vs Client コンポーネントの意思決定を最適化する","効率的なデータ取得戦略を実装する","分離された Server と Client コンポーネントを使用してアプリケーションのパフォーマンスを向上させる"],"ko":["Server vs Client 컴포넌트의 결정 최적화","효율적인 데이터 가져오기 전략 구현","분리된 Server와 Client 컴포넌트를 사용하여 애플리케이션 성능 향상"],"es":["Optimizar las decisiones de componente Servidor vs Cliente","Implementar estrategias de recuperación de datos eficientes","Mejorar el rendimiento de la aplicación con componentes Servidor y Cliente divididos"],"fr":["Optimiser les décisions de composant Serveur vs Client","Mettre en œuvre des stratégies d''extraction de données efficaces","Améliorer les performances de l''application avec des composants Serveur et Client séparés"],"de":["Optimieren der Entscheidungen für Server- und Client-Komponenten","Implementieren effizienter Datenabfragestrategien","Verbessern der Anwendungsleistung mit getrennten Server- und Client-Komponenten"],"pt":["Otimizar decisões de Componentes de Servidor vs Cliente","Implementar estratégias de busca de dados eficientes","Melhorar o desempenho do aplicativo com componentes de Servidor e Cliente divididos"],"ru":["Оптимизировать решения по серверным и клиентским компонентам","Реализовывать эффективные стратегии извлечения данных","Улучшать производительность приложения с разделенными серверными и клиентскими компонентами"],"ar":["تحسين قرارات مكونات الخادم و العميل","تنفيذ استراتيجيات استرجاع البيانات الفعالة","تحسين أداء التطبيق مع مكونات الخادم و العميل المنقسمة"]},"limitations":{"en":["Requires Next.js environment","Limited to App Router development"],"zh":["需要 Next.js 环境","仅限于 App Router 开发"],"ja":["Next.js 環境が必要","App Router 開発に限定される"],"ko":["Next.js 환경이 필요","App Router 개발에만 제한"],"es":["Requiere un entorno Next.js","Limitado al desarrollo de App Router"],"fr":["Nécessite un environnement Next.js","Limité au développement d''App Router"],"de":["Benötigt eine Next.js-Umgebung","Begrenzt auf die Entwicklung von App Router"],"pt":["Requer ambiente Next.js","Limitado ao desenvolvimento do App Router"],"ru":["Требует среды Next.js","Ограничен разработкой маршрутизатора приложения"],"ar":["يتطلب بيئة Next.js","محدود بتطوير مسار التطبيق"]},"version":4},"contentHash":"50bf04377ef5686f02884153c4115168ef2ec21b481bdac732c27389e4f3d3ef","qualityScore":42}');
