INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ahtavarasmus/lightfriend/lightfriend-add-frontend-page', 'lightfriend-add-frontend-page', 'ahtavarasmus', 'lightfriend', 'community', 'lightfriend-add-frontend-page ahtavarasmus lightfriend community The lightfriend-add-frontend-page skill helps developers add new pages to the Lightfriend Yew WebAssembly frontend, benefiting dumphone users. It guides through creating page components, route enums, and navigation links. Lightfriend 添加前端页面是一种 AI 助手，帮助开发者创建新的前端页面，包括页面组件、路由枚举变体和路由处理函数 Lightfriend フロントエンドページ追加は、開発者が新しいフロントエンドページを作成することを支援する AI エージェントです - ページコンポーネント、ルート列挙型バリアント、ルートハンドラー関数 Lightfriend 프론트엔드 페이지 추가는 개발자가 새로운 프론트엔드 페이지를 생성하는 것을 지원하는 AI 도구입니다 - 페이지 컴포넌트, 라우트 열거형 변수, 라우트 핸들러 함수 Lightfriend es una herramienta de AI que permite agregar páginas frontend personalizadas. Sigue nuestra guía para configurar y mejorar la experiencia del usuario. Lightfriend est un outil d''IA qui permet d''ajouter des pages frontend personnalisées. Suivez notre guide pour configurer et améliorer l''expérience utilisateur. Lightfriend ist ein KI-Tool, das das Hinzufügen von personalisierten Frontend-Seiten ermöglicht. Folgen Sie unserer Anleitung, um die Konfiguration durchzuführen und die Benutzererfahrung zu verbessern. O skill lightfriend-add-frontend-page é um guia para adicionar uma nova página ao frontend do Lightfriend. Ele aborda a criação de componentes de página e rotas Навык lightfriend-add-frontend-page является руководством для добавления новой страницы в frontend Lightfriend. Он охватывает создание компонентов страниц и маршрутов المهارة lightfriend-add-frontend-page هي دليل لإضافة صفحة جديدة إلى واجهة المستخدم الأمامية للightfriend. وهي تتناول إنشاء مكونات الصفحة وروابط التنقل how to use lightfriend-add-frontend-page lightfriend-add-frontend-page setup guide Yew WebAssembly frontend development adding new pages to Lightfriend lightfriend-add-frontend-page alternative lightfriend-add-frontend-page vs other AI assistants Lightfriend 添加前端页面 AI 助手 前端页面创建 Yew WebAssembly 路由枚举变体 路由处理函数 Creates page components in frontend/src/pages/ Adds route enum variants in main.rs Handles routes in switch functions Supports navigation link creation Utilizes Yew and gloo_net::http::Request for frontend development lightfriend-add-frontend-page is a skill that assists in adding new frontend pages to the Lightfriend Yew WebAssembly application, including page components, routes, and navigation links.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Duit-Foundation/flutter_duit/duit-maintainer', 'community', 'Duit-Foundation', 'flutter_duit', 'Duit-Foundation/flutter_duit', 'duit-maintainer', 56, 4, 41, '2026-02-26T16:16:39Z', '2026-03-06T06:35:05.220Z', '33aca70967c733c385ea6c6a30c97c3f51e58e75929e187b52e8f94684a53398', '{"id":"Duit-Foundation/flutter_duit/duit-maintainer","name":"duit-maintainer","description":{"en":"The duit-maintainer skill provides a server-driven UI framework for Flutter, enabling developers to create consistent and reusable UI components. It benefits Flutter developers working with UI toolkits.","zh":"Duit Maintainer 是一个 Flutter 服务器驱动 UI 框架，用于创建一致的 UI 组件","ja":"Duit Maintainer は、Flutter サーバー駆動 UI フレームワークを使用して一貫性のある UI コンポーネントを作成するために使用されます","ko":"Duit Maintainer는 일관된 UI 구성 요소를 생성하기 위해 사용되는 Flutter 서버 드리븐 UI 프레임워크입니다","es":"Duit Maintainer es un kit de herramientas de interfaz de usuario para Flutter que permite la creación de interfaces de usuario personalizadas","fr":"Duit Maintainer est un kit d''outils d''interface utilisateur pour Flutter qui permet de créer des interfaces utilisateur personnalisées","de":"Duit Maintainer ist ein Benutzeroberflächen-Toolkit für Flutter, das die Erstellung von benutzerdefinierten Benutzeroberflächen ermöglicht","pt":"O Duit Maintainer é um toolkit de UI para Flutter que permite criar interfaces de usuário personalizadas. Aprenda a configurá-lo para melhorar seus projetos.","ru":"Duit Maintainer - это набор инструментов для создания интерфейсов пользователя для Flutter. Узнайте, как настроить его для улучшения своих проектов ИИ Агентов.","ar":"دويت مينتينر هو أداة واجهة مستخدم ل Flutter التي تمكنك من إنشاء واجهات مستخدم مخصصة. تعلم كيفية إعدادها لتحسين مشاريعك."},"seo":{"title":{"en":"duit-maintainer: Flutter UI Toolkit Setup Guide | AI Agen...","zh":"Duit Maintainer 设置指南 - Flutter 服务器驱动 UI 框架","ja":"Duit Maintainer セットアップガイド - Flutter サーバー駆動 UI フレームワーク","ko":"Duit Maintainer 설정 가이드 - Flutter 서버 드리븐 UI 프레임워크","es":"Configuración de Duit Maintainer: Guía de Implementación ...","fr":"Guide de Configuration de Duit Maintainer pour Flutter","de":"Duit Maintainer Einrichtung: Leitfaden für Flutter-Entwic...","pt":"Guia de Configuração do Duit Maintainer para Desenvolvedores","ru":"Настройка Duit Maintainer: Руководство для Разработчиков ...","ar":"دليل إعداد دويت مينتينرสำหร لمطوّرين"},"description":{"en":"Discover how to implement server-driven UI with duit-maintainer, a Flutter UI toolkit. Learn how to create new widgets and follow best practices for consiste...","zh":"了解 Duit Maintainer 的技术细节和最佳实践，提高 Flutter 服务器驱动 UI 框架的开发效率","ja":"Duit Maintainer の技術的詳細とベストプラクティスを学び、Flutter サーバー駆動 UI フレームワークの開発効率を向上させる","ko":"Duit Maintainer의 기술적 세부 사항과 최적의 실践 방법을 알아보고 Flutter 서버 드리븐 UI 프레임워크의 개발 효율성을 향상시키세요","es":"Aprende a configurar Duit Maintainer para Flutter y mejora tu experiencia de desarrollo con este kit de herramientas de interfaz de usuario","fr":"Découvrez comment configurer Duit Maintainer pour Flutter et améliorez votre expérience de développement avec ce kit d''outils d''interface utilisateur","de":"Erfahren Sie, wie Sie Duit Maintainer für Flutter konfigurieren und Ihre Entwicklungserfahrung mit diesem Benutzeroberflächen-Toolkit verbessern","pt":"Aprenda a configurar o Duit Maintainer para criar interfaces de usuário personalizadas com Flutter e Dart. Descubra as melhores práticas e recursos técnicos.","ru":"Узнайте, как настроить Duit Maintainer для создания индивидуальных интерфейсов пользователя с помощью Flutter и Dart. Ознакомьтесь с лучшими практиками и тех...","ar":"تعرف على كيفية إعداد دويت مينتينر لإنشاء واجهات مستخدم مخصصة مع Flutter و Dart. اكتشف أفضل الممارسات والمميزات الفنية لأدوات الذكاء الاصطناعي."},"definition":{"en":"duit-maintainer is a server-driven UI framework for Flutter, providing a consistent implementation pattern for UI widgets and components.","zh":"Duit Maintainer 是一个用于创建一致的 UI 组件的 Flutter 服务器驱动 UI 框架","ja":"Duit Maintainer は、Flutter サーバー駆動 UI フレームワークを使用して一貫性のある UI コンポーネントを作成するツールです","ko":"Duit Maintainer는 일관된 UI 구성 요소를 생성하기 위한 Flutter 서버 드리븐 UI 프레임워크입니다","es":"Duit Maintainer es un kit de herramientas de interfaz de usuario para Flutter que permite la creación de interfaces de usuario personalizadas","fr":"Duit Maintainer est un kit d''outils d''interface utilisateur pour Flutter qui permet de créer des interfaces utilisateur personnalisées","de":"Duit Maintainer ist ein Benutzeroberflächen-Toolkit für Flutter, das die Erstellung von benutzerdefinierten Benutzeroberflächen ermöglicht","pt":"O Duit Maintainer é um toolkit de UI para Flutter que permite criar interfaces de usuário personalizadas com Dart.","ru":"Duit Maintainer - это набор инструментов для создания интерфейсов пользователя для Flutter с помощью Dart и ИИ Агентов.","ar":"دويت مينتينر هو أداة واجهة مستخدم ل Flutter التي تمكنك من إنشاء واجهات مستخدم مخصصة مع Dart وأدوات الذكاء الاصطناعي."},"features":{"en":["Implements widget classes using Dart and Flutter","Creates widget implementation files in lib/src/ui/widgets/","Follows a consistent pattern for widget implementation","Uses ViewAttribute and Widget child properties","Supports server-driven UI framework for Flutter"],"zh":["支持 Dart 和 Flutter","提供一致的 UI 组件创建方式","使用 ViewAttribute 和 Widget 实现","支持服务器驱动 UI 框架"],"ja":["Dart と Flutter をサポート","一貫性のある UI コンポーネントの作成方法を提供","ViewAttribute と Widget を使用して実装","サーバー駆動 UI フレームワークをサポート"],"ko":["Dart와 Flutter를 지원","일관된 UI 구성 요소를 생성하는 방법을 제공","ViewAttribute와 Widget을 사용하여 구현","서버 드리븐 UI 프레임워크를 지원"],"es":["Implementación de widgets personalizados en Dart","Creación de interfaces de usuario personalizadas con Flutter","Uso de ViewAttribute y Widget para la personalización de la interfaz de usuario","Seguimiento de patrones de implementación consistentes en Flutter","Uso de la biblioteca flutter_duit para la creación de interfaces de usuario"],"fr":["Implémentation de widgets personnalisés en Dart","Création d''interfaces utilisateur personnalisées avec Flutter","Utilisation de ViewAttribute et Widget pour la personnalisation de l''interface utilisateur","Suivi de modèles d''implémentation cohérents dans Flutter","Utilisation de la bibliothèque flutter_duit pour la création d''interfaces utilisateur"],"de":["Implementierung von benutzerdefinierten Widgets in Dart","Erstellung von benutzerdefinierten Benutzeroberflächen mit Flutter","Verwendung von ViewAttribute und Widget für die Anpassung der Benutzeroberfläche","Verfolgung von Implementierungsmustern in Flutter","Verwendung der Bibliothek flutter_duit für die Erstellung von Benutzeroberflächen"],"pt":["Criação de interfaces de usuário personalizadas com Flutter","Uso de Dart para desenvolvimento de widgets","Padrões de implementação consistentes para widgets","Criação de arquivos de implementação de widgets em lib/src/ui/widgets/","Uso de ViewAttribute e Widget para personalização de widgets","Integração com o framework Flutter para desenvolvimento de aplicativos móveis"],"ru":["Создание индивидуальных интерфейсов пользователя с помощью Flutter","Использование Dart для разработки виджетов","Последовательные шаблоны реализации для виджетов","Создание файлов реализации виджетов в lib/src/ui/widgets/","Использование ViewAttribute и Widget для настройки виджетов","Интеграция с фреймворком Flutter для разработки мобильных приложений ИИ Агентов"],"ar":["إنشاء واجهات مستخدم مخصصة مع Flutter","استخدام Dart لتنمية Widgets","نماذج تنفيذ متسقة لWidgets","إنشاء ملفات تنفيذ Widgets في lib/src/ui/widgets/","استخدام ViewAttribute و Widget لتخصيص Widgets","التكامل مع إطار Flutter لتنمية تطبيقات الهاتف المحمول بأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use duit-maintainer","duit-maintainer setup guide","flutter ui toolkit","server-driven ui framework","duit-maintainer vs bdui","duit-maintainer install","what is duit-maintainer","duit-maintainer alternative","flutter_duit implementation"],"zh":["Duit Maintainer","Flutter 服务器驱动 UI 框架","Dart","Flutter","UI 组件","服务器驱动 UI","ViewAttribute","Widget"],"ja":["Duit Maintainer","Flutter サーバー駆動 UI フレームワーク","Dart","Flutter","UI コンポーネント","サーバー駆動 UI","ViewAttribute","Widget"],"ko":["Duit Maintainer","Flutter 서버 드리븐 UI 프레임워크","Dart","Flutter","UI 구성 요소","서버 드리븐 UI","ViewAttribute","Widget"],"es":["Duit Maintainer","Flutter","Dart","Interfaz de usuario personalizada","Kit de herramientas de interfaz de usuario","Desarrollo de aplicaciones móviles","Herramientas de desarrollo de Flutter","UIKit para Flutter","Biblioteca flutter_duit"],"fr":["Duit Maintainer","Flutter","Dart","Interface utilisateur personnalisée","Kit d''outils d''interface utilisateur","Développement d''applications mobiles","Outils de développement de Flutter","UIKit pour Flutter","Bibliothèque flutter_duit"],"de":["Duit Maintainer","Flutter","Dart","Benutzeroberfläche anpassen","Benutzeroberflächen-Toolkit","Mobile App-Entwicklung","Flutter-Entwicklungstools","UIKit für Flutter","Bibliothek flutter_duit"],"pt":["Duit Maintainer","Flutter","Dart","UI toolkit","interfaces de usuário personalizadas","desenvolvimento de aplicativos móveis","widgets","ViewAttribute","Widget"],"ru":["Duit Maintainer","Flutter","Dart","ИИ Агенты","набор инструментов для создания интерфейсов пользователя","индивидуальные интерфейсы пользователя","разработка мобильных приложений","виджеты","ViewAttribute","Widget"],"ar":["duit-maintainer","Flutter","Dart","أدوات الذكاء الاصطناعي","واجهة مستخدم مخصصة","تطوير تطبيقات الهاتف المحمول","Widgets","ViewAttribute","Widget","دويت مينتينر"]}},"owner":"Duit-Foundation","repo":"flutter_duit","repoPath":"Duit-Foundation/flutter_duit","stars":56,"forks":4,"updatedAt":"2026-02-26T16:16:39Z","topics":["bdui","dart","flutter","sdui","ui"],"category":"community","skillMd":{"name":"duit-maintainer","description":"Creates new Flutter widgets following Duit framework patterns, writes comprehensive tests, and performs code reviews. Use when adding widgets, reviewing widget implementations, or maintaining the flutter_duit package.","bodyPreview":"# Duit Maintainer\n\n## Quick Start\n\nWhen working on flutter_duit widgets, follow these patterns consistently across all implementations.\n\n## Creating New Widgets\n\n### Step 1: Implement Widget Classes\n\nCreate widget implementation file in `lib/src/ui/widgets/` following this pattern:\n\n```dart\nimport \"package:flutter/material.dart\";\nimport \"package:flutter_duit/flutter_duit.dart\";\n\nclass Duit[WidgetName] extends StatelessWidget {\n  final ViewAttribute attributes;\n  final Widget child;  // or final","body":"# Duit Maintainer\n\n## Quick Start\n\nWhen working on flutter_duit widgets, follow these patterns consistently across all implementations.\n\n## Creating New Widgets\n\n### Step 1: Implement Widget Classes\n\nCreate widget implementation file in `lib/src/ui/widgets/` following this pattern:\n\n```dart\nimport \"package:flutter/material.dart\";\nimport \"package:flutter_duit/flutter_duit.dart\";\n\nclass Duit[WidgetName] extends StatelessWidget {\n  final ViewAttribute attributes;\n  final Widget child;  // or final List<Widget?> children;\n\n  const Duit[WidgetName]({\n    required this.attributes,\n    required this.child,  // or this.children\n    super.key,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final attrs = attributes.payload;\n    return [WidgetName](\n      key: ValueKey(attributes.id),\n      // ... widget-specific properties using attrs methods\n      child: child,  // or children\n    );\n  }\n}\n\nclass DuitControlled[WidgetName] extends StatefulWidget {\n  final UIElementController controller;\n  final Widget child;  // or final List<Widget?> children;\n\n  const DuitControlled[WidgetName]({\n    required this.controller,\n    required this.child,  // or this.children\n    super.key,\n  });\n\n  @override\n  State<DuitControlled[WidgetName]> createState() =>\n      _DuitControlled[WidgetName]State();\n}\n\nclass _DuitControlled[WidgetName]State extends State<DuitControlled[WidgetName]>\n    with ViewControllerChangeListener {\n  @override\n  void initState() {\n    attachStateToController(widget.controller);\n    super.initState();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return [WidgetName](\n      key: ValueKey(widget.controller.id),\n      // ... widget-specific properties using attributes\n      child: widget.child,  // or widget.children\n    );\n  }\n}\n```\n\n**Key Patterns:**\n\n- Always create both Duit[WidgetName] (non-controlled) and DuitControlled[WidgetName] (controlled)\n- Controlled widgets must extend StatefulWidget and mix in ViewControllerChangeListener\n- The ViewControllerChangeListener mixin provides the `late DuitDataSource attributes` property, allowing direct access to `attributes.getBool()`, `attributes.getDouble()`, etc. in controlled widget state\n- Call `attachStateToController(widget.controller)` in initState\n- Use `ValueKey(attributes.id)` for non-controlled, `ValueKey(widget.controller.id)` for controlled\n- Access attributes via `attributes.payload` in non-controlled widgets\n- Access attributes via `attributes` (provided by ViewControllerChangeListener mixin) in controlled widgets\n- **Themes are applied automatically via ViewAttribute.from() in widget_from_element.dart** - themes are merged during ViewAttribute creation before reaching the widget implementation\n- Widget implementation code does NOT need to handle theme application explicitly - attributes received already have theme data merged\n\n### Step 2: Register Widget Type\n\nAdd to `lib/src/ui/element_type.dart`:\n\n1. Add enum value:\n\n```dart\n[widgetName](\n  name: \"[WidgetName]\",\n  isControlledByDefault: false,  // or true for interactive widgets\n  childRelation: 0,  // 0=none, 1=single, 2=multiple, 3=component, 4=fragment\n),\n```\n\n1. Add to lookup table (at end of file):\n\n```dart\n  \"[WidgetName]\": ElementType.[widgetName],\n```\n\n**Child Relations:**\n\n- 0: Leaf widgets (Text, Image, TextField)\n- 1: Single child wrapper (Container, Padding, Center)\n- 2: Multiple children (Row, Column, Stack, Visibility)\n- 3: Component content\n- 4: Fragment content\n\n### Step 3: Create Build Function\n\nAdd to `lib/src/ui/widget_from_element.dart`:\n\n```dart\nWidget _build[WidgetName](ElementPropertyView model) {\n  return switch (model.controlled) {\n    true => DuitControlled[WidgetName](\n        controller: model.viewController,\n        child: _buildWidget(model.child),  // or children\n      ),\n    false => Duit[WidgetName](\n        attributes: model.attributes,\n        child: _buildWidget(model.child),  // or children\n      ),\n  };\n}\n```\n\nFor multi-child widgets with nullable children:\n\n```dart\nWidget _build[WidgetName](ElementPropertyView model) {\n  final children = _mapToNullableWidgetList(model);\n  return switch (model.controlled) {\n    true => DuitControlled[WidgetName](\n        controller: model.viewController,\n        children: children,\n      ),\n    false => Duit[WidgetName](\n        attributes: model.attributes,\n        children: children,\n      ),\n  };\n}\n```\n\n### Step 4: Add to Build Function Lookup\n\nAdd to `lib/src/ui/build_fn_lookup.dart`:\n\n```dart\n  ElementType.[widgetName]: _build[WidgetName],\n```\n\n### Step 5: Export Widget\n\nAdd to `lib/src/ui/widgets/index.dart`:\n\n```dart\nexport \"[widget_name].dart\";\n```\n\n### Step 6: Use AnimatedAttributes Mixin (for animatable properties)\n\nIf the widget has properties of types that support animation (e.g., width/height, Offset, and other types implementing `.lerp`), apply the `AnimatedAttributes` mixin.\n\nThe `AnimatedAttributes` mixin provides the `mergeWithDataSource` method that merges the widget''s attributes with animated properties from the `DuitAnimationContext` if animation is active.\n\n**When to use AnimatedAttributes:**\n\nApply this mixin when the widget has animatable properties such as:\n\n- Numeric values: `width`, `height`, `opacity`, `scale`\n- Position/offset: `Offset`, `Size`\n- Colors and other interpolatable types\n\n**Implementation pattern:**\n\n```dart\nimport \"package:flutter_duit/flutter_duit.dart\";\nimport \"package:flutter_duit/src/animations/animated_props.dart\";\n\nclass Duit[WidgetName] extends StatelessWidget with AnimatedAttributes {\n  final ViewAttribute attributes;\n  final Widget child;\n\n  const Duit[WidgetName]({\n    required this.attributes,\n    required this.child,\n    super.key,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final attrs = mergeWithDataSource(context, attributes.payload);\n    return [WidgetName](\n      key: ValueKey(attributes.id),\n      // ... widget-specific properties using attrs methods\n      // Properties will use animated values if animation is active\n      width: attrs.getDouble(key: \"width\"),\n      height: attrs.getDouble(key: \"height\"),\n      child: child,\n    );\n  }\n}\n```\n\nFor controlled widgets:\n\n```dart\nclass _DuitControlled[WidgetName]State extends State<DuitControlled[WidgetName]>\n    with ViewControllerChangeListener {\n  // ... existing code ...\n\n  @override\n  Widget build(BuildContext context) {\n    final attrs = widget.mergeWithDataSource(context, attributes);\n    return [WidgetName](\n      key: ValueKey(widget.controller.id),\n      // ... widget-specific properties\n      width: attrs.getDouble(key: \"width\"),\n      height: attrs.getDouble(key: \"height\"),\n      child: widget.child,\n    );\n  }\n}\n```\n\n**How mergeWithDataSource works:**\n\nThe method checks for the following conditions:\n\n1. If the dataSource has a parentBuilderId\n2. If a DuitAnimationContext exists in the widget tree\n3. If the animation context''s parentId matches the dataSource''s parentBuilderId\n4. If there are affected properties to animate\n\nIf all conditions are met, it merges the animated values from the animation context streams with the current dataSource, allowing animated values to override static ones.\n\n**Key points:**\n\n- Apply `AnimatedAttributes` mixin to both non-controlled and controlled widget classes\n- For non-controlled widgets: call `mergeWithDataSource(context, attributes.payload)`\n- For controlled widgets: call `widget.mergeWithDataSource(context, attributes)` (attributes provided by ViewControllerChangeListener)\n- Use the merged attributes to extract all animatable properties\n- The mixin gracefully handles cases where no animation is active (returns original dataSource)\n\n## Working with Themes\n\n### Theme Overview\n\nDuit framework provides a theming system that allows you to define reusable styling for widgets. Themes are defined globally and applied automatically when widgets specify a `theme` attribute in their JSON definition.\n\n### How Themes Work\n\n1. **Theme Definition**: Themes are defined in a JSON structure and processed by `DuitThemePreprocessor`\n2. **Theme Tokens**: Each widget type has an associated `ThemeToken` class that defines which attributes can be themed\n3. **Theme Application**: When a widget specifies `theme: \"theme_name\"`, the theme data is merged with the widget''s attributes during `ViewAttribute.from()` creation\n4. **Excluded Fields**: Each ThemeToken has a list of excluded fields that should NOT be themed (e.g., callbacks, data, structural properties)\n\n### Theme System Components\n\n#### Theme Tokens\n\nTheme tokens are defined in `lib/src/ui/theme/tokens.dart`. Each token type excludes specific fields that should not be part of the theme:\n\n- **TextThemeToken**: Excludes `data` (the text content itself)\n- **ImageThemeToken**: Excludes `src`, `byteData` (image source data)\n- **AttendedWidgetThemeToken**: Excludes `value` (for Checkbox, Switch, etc.)\n- **RadioThemeToken**: Excludes animation-related properties\n- **SliderThemeToken**: Excludes callback properties (`onChanged`, `onChangeStart`, `onChangeEnd`)\n- **ImplicitAnimatableThemeToken**: Excludes `onEnd` callback\n- **ExcludeGestureCallbacksThemeToken**: Excludes all gesture callbacks (`onTap`, `onDoubleTap`, etc.)\n- **ExcludeChildThemeToken**: Excludes child subviews (`title`, `actions`, `body`, etc. for AppBar/Scaffold)\n- **DynamicChildHolderThemeToken**: Excludes `childObjects`, `constructor`\n- **AnimatedPropOwnerThemeToken**: Excludes animation-related properties\n- **DefaultThemeToken**: No exclusions (for widgets that can be fully themed)\n\n#### Theme Preprocessor\n\nThe `DuitThemePreprocessor` class (`lib/src/ui/theme/preprocessor.dart`) handles theme token creation. It maps widget types to appropriate theme tokens:\n\n```dart\nfinal class DuitThemePreprocessor extends ThemePreprocessor {\n  const DuitThemePreprocessor({\n    super.customWidgetTokenizer,\n    super.overrideWidgetTokenizer,\n  });\n\n  @override\n  ThemeToken createToken(String widgetType, Map<String, dynamic> themeData) {\n    final type = ElementType.valueOrNull(widgetType);\n    return switch (type) {\n      ElementType.text => TextThemeToken(themeData),\n      ElementType.image => ImageThemeToken(themeData),\n      ElementType.checkbox || ElementType.switch_ || ElementType.textField || ElementType.meta =>\n        AttendedWidgetThemeToken(themeData, widgetType),\n      // ... more mappings\n      _ => customWidgetTokenizer?.call(widgetType, themeData) ?? const UnknownThemeToken(),\n    };\n  }\n}\n```\n\n### Theme Initialization\n\nThemes are initialized at application startup:\n\n```dart\nimport ''package:duit_kernel/duit_kernel.dart'';\nimport ''package:flutter_duit/src/ui/theme/preprocessor.dart'';\n\n// Define your themes\nfinal themePreprocessor = const DuitThemePreprocessor().tokenize({\n  \"primary_text\": {\n    \"type\": \"Text\",\n    \"data\": {\n      \"style\": {\n        \"fontSize\": 16.0,\n        \"fontWeight\": \"w600\",\n        \"color\": \"#333333\",\n      },\n      \"textAlign\": \"left\",\n    },\n  },\n  \"secondary_text\": {\n    \"type\": \"Text\",\n    \"data\": {\n      \"style\": {\n        \"fontSize\": 14.0,\n        \"color\": \"#666666\",\n      },\n    },\n  },\n  \"primary_button\": {\n    \"type\": \"ElevatedButton\",\n    \"data\": {\n      \"style\": {\n        \"backgroundColor\": \"#2196F3\",\n        \"foregroundColor\": \"#FFFFFF\",\n        \"padding\": {\"all\": 16.0},\n      },\n    },\n  },\n});\n\n// Initialize Duit with themes\nawait DuitRegistry.initialize(\n  theme: themePreprocessor,\n);\n```\n\n### Using Themes in Widget JSON\n\nTo apply a theme to a widget, use the `theme` attribute:\n\n```json\n{\n  \"type\": \"Text\",\n  \"id\": \"title\",\n  \"controlled\": false,\n  \"theme\": \"primary_text\",\n  \"attributes\": {\n    \"data\": \"Hello World\"\n  }\n}\n```\n\nThe theme will be merged with the widget''s attributes. If both theme and attributes specify the same property, the behavior depends on `overrideRule`:\n\n- `themeOverlay` (default): Widget attributes take precedence\n- `themePriority`: Theme values take precedence\n\n```json\n{\n  \"type\": \"Text\",\n  \"id\": \"title\",\n  \"controlled\": false,\n  \"theme\": \"primary_text\",\n  \"overrideRule\": \"themePriority\",\n  \"attributes\": {\n    \"data\": \"Hello World\",\n    \"textAlign\": \"center\"  // This would be overridden by theme if themePriority\n  }\n}\n```\n\n### Custom Theme Tokens\n\nFor custom widget types, you can create custom theme tokens:\n\n```dart\nfinal class CustomWidgetThemeToken extends ThemeToken {\n  CustomWidgetThemeToken(Map<String, dynamic> data)\n      : super(\n          const {}, // No excluded fields - allow all to be themed\n          data,\n          \"CustomWidget\",\n        );\n}\n```\n\nThen provide it to the preprocessor:\n\n```dart\nfinal preprocessor = DuitThemePreprocessor(\n  customWidgetTokenizer: (type, themeData) {\n    switch (type) {\n      case \"CustomWidget\":\n        return CustomWidgetThemeToken(themeData);\n      default:\n        return null;\n    }\n  },\n);\n```\n\nOr override existing widget tokenization:\n\n```dart\nfinal preprocessor = DuitThemePreprocessor(\n  overrideWidgetTokenizer: (type, themeData) {\n    switch (type) {\n      case \"Text\":\n        return CustomTextThemeToken(themeData);  // Override default TextThemeToken\n      default:\n        return null;  // Use default tokenization\n    }\n  },\n);\n```\n\n### Theme Token Selection Guide\n\nWhen implementing a new widget, select the appropriate theme token type based on the widget''s characteristics:\n\n| Widget Type | Theme Token | When to Use |\n|-------------|-------------|-------------|\n| Text widgets | `TextThemeToken` | Text content should be excluded from theme |\n| Image widgets | `ImageThemeToken` | Image source (src, byteData) should be excluded |\n| Interactive widgets with value (Checkbox, Switch, etc.) | `AttendedWidgetThemeToken` | `value` field should be excluded |\n| Radio buttons | `RadioThemeToken` | Animation properties excluded |\n| Sliders | `SliderThemeToken` | Callbacks (`onChanged`, etc.) excluded |\n| Implicit animations | `ImplicitAnimatableThemeToken` | `onEnd` callback excluded |\n| Gesture handlers | `ExcludeGestureCallbacksThemeToken` | All gesture callbacks excluded |\n| Layout widgets with children (AppBar, Scaffold) | `ExcludeChildThemeToken` | Child subviews excluded |\n| Lists/Grids | `DynamicChildHolderThemeToken` | `childObjects` excluded |\n| Containers with animatable properties | `AnimatedPropOwnerThemeToken` | Animation properties excluded |\n| Simple widgets | `DefaultThemeToken` | No exclusions needed |\n\n### Important Notes for Widget Implementation\n\n**Widget implementations do NOT need to handle themes explicitly.** The theme merging happens in `ViewAttribute.from()` during widget tree construction. Your widget code receives attributes that already have theme data merged:\n\n```dart\n// In widget_from_element.dart - themes are applied here automatically\nWidget _buildText(ElementPropertyView model) {\n  // model.attributes already has theme data merged\n  return switch (model.controlled) {\n    true => DuitControlledText(controller: model.viewController),\n    false => DuitText(attributes: model.attributes),\n  };\n}\n\n// In your widget implementation - just use attributes directly\n@override\nWidget build(BuildContext context) {\n  final attrs = attributes.payload;  // or mergeWithDataSource for animated props\n  return Text(\n    attrs.getString(key: \"data\"),  // Theme already merged into attributes\n    style: attrs.textStyle(),\n  );\n}\n```\n\n### Theme Testing\n\nWhen testing widgets that support themes:\n\n1. Initialize the registry with theme preprocessor in `setUpAll`\n2. Create tests that verify theme attributes are applied\n3. Test override rules (`themeOverlay` vs `themePriority`)\n\n```dart\nimport \"package:duit_kernel/duit_kernel.dart\";\nimport \"package:flutter_duit/flutter_duit.dart\";\nimport \"package:flutter_test/flutter_test.dart\";\n\nvoid main() {\n  setUpAll(() async {\n    final proc = const DuitThemePreprocessor().tokenize({\n      \"text_theme\": {\n        \"type\": \"Text\",\n        \"data\": {\n          \"style\": {\n            \"fontSize\": 24.0,\n            \"color\": \"#FF0000\",\n          },\n        },\n      },\n    });\n    await DuitRegistry.initialize(theme: proc);\n  });\n\n  testWidgets(\"must apply theme attributes\", (tester) async {\n    await tester.pumpWidget(\n      Directionality(\n        textDirection: TextDirection.ltr,\n        child: DuitViewHost.withDriver(\n          driver: XDriver.static({\n            \"type\": \"Text\",\n            \"id\": \"text_1\",\n            \"theme\": \"text_theme\",\n            \"attributes\": {\"data\": \"Themed Text\"},\n          }),\n        ),\n      ),\n    );\n\n    final textWidget = tester.widget<Text>(find.byKey(const ValueKey(\"text_1\")));\n    expect(textWidget.style?.fontSize, equals(24.0));\n    expect(textWidget.style?.color, equals(const Color(0xFFFF0000)));\n  });\n}\n```\n\n## Writing Tests\n\n### Test File Pattern\n\nCreate test file in `test/` following this structure:\n\n```dart\nimport \"package:flutter/material.dart\";\nimport \"package:flutter_duit/flutter_duit.dart\";\nimport \"package:flutter_test/flutter_test.dart\";\n\nimport \"utils.dart\";\n\nMap<String, dynamic> _createWidget([bool isControlled = false]) {\n  return {\n    \"type\": \"[WidgetName]\",\n    \"id\": \"[widget_name]_test\",\n    \"controlled\": isControlled,\n    \"attributes\": {\n      // required attributes\n    },\n    \"child\": {  // or \"children\": [...]\n      \"type\": \"Container\",\n      \"id\": \"con\",\n      \"controlled\": false,\n      \"attributes\": {\"color\": \"#DCDCDC\", \"width\": 50, \"height\": 50},\n    },\n  };\n}\n\nvoid main() {\n  group(\"Duit[WidgetName] widget tests\", () {\n    testWidgets(\"check widget\", (tester) async {\n      await tester.pumpWidget(\n        Directionality(\n          textDirection: TextDirection.ltr,\n          child: DuitViewHost.withDriver(\n            driver: XDriver.static(\n              _createWidget(),\n            ),\n          ),\n        ),\n      );\n      await tester.pumpAndSettle();\n\n      final widget = find.byKey(const ValueKey(\"[widget_name]_test\"));\n      expect(widget, findsOneWidget);\n    });\n\n    testWidgets(\n      \"must update attributes\",\n      (tester) async {\n        final driver = XDriver.static(\n          _createWidget(true),\n        );\n\n        await pumpDriver(tester, driver.asInternalDriver);\n\n        final widget = find.byKey(const ValueKey(\"[widget_name]_test\"));\n        expect(widget, findsOneWidget);\n\n        // Verify initial state\n        final initialWidget = tester.widget<[WidgetName]>(widget);\n        expect(initialWidget.property, expectedValue);\n\n        await driver.asInternalDriver.updateAttributes(\n          \"[widget_name]_test\",\n          {\n            \"property\": newValue,\n          },\n        );\n\n        await tester.pumpAndSettle();\n\n        // Verify updated state\n        final updatedWidget = tester.widget<[WidgetName]>(widget);\n        expect(updatedWidget.property, newValue);\n      },\n    );\n  });\n}\n```\n\n**Test Guidelines:**\n\n- Always use `XDriver.static` for widget tests\n- Create helper function `_createWidget([bool isControlled = false])`\n- Test both non-controlled and controlled versions\n- Use `find.byKey(const ValueKey(\"...\"))` to locate widgets\n- For controlled widgets, test `updateAttributes` functionality\n- Use `pumpDriver(tester, driver.asInternalDriver)` for controlled widget tests\n- Import `utils.dart` for helper functions like `pumpDriver`\n\n## Attribute Access Patterns\n\nWhen accessing attributes in widgets:\n\n```dart\nfinal attrs = attributes.payload;  // or use attributes directly in controlled widgets\n\n// Double values\nwidth: attrs.tryGetDouble(key: \"width\")\nheight: attrs.getDouble(key: \"height\")  // throws if missing\nattrs.getDouble(key: \"value\", defaultValue: 0.0)\n\n// Boolean values\nvisible: attrs.getBool(\"visible\", defaultValue: true)\n\n// String values\ntitle: attrs.getString(key: \"title\")\n\n// Color values\ncolor: attrs.tryParseColor(key: \"color\")\ndecoration: attrs.decoration()\n\n// EdgeInsets values\npadding: attrs.edgeInsets()\nmargin: attrs.edgeInsets(key: \"margin\")\n\n// Alignment values\nalignment: attrs.alignment()\n\n// BoxConstraints values\nconstraints: attrs.boxConstraints()\n```\n\n## Code Review Checklist\n\nWhen reviewing widget implementations:\n\n- [ ] Both Duit[WidgetName] and DuitControlled[WidgetName] classes exist\n- [ ] Controlled widget extends StatefulWidget and mixes ViewControllerChangeListener\n- [ ] Controlled widget state uses `attributes` property directly (provided by ViewControllerChangeListener mixin)\n- [ ] `attachStateToController` called in initState\n- [ ] Correct key usage: ValueKey(attributes.id) or ValueKey(widget.controller.id)\n- [ ] ElementType enum value added with correct childRelation\n- [ ] _stringToTypeLookupTable entry added\n- [ ] _build[WidgetName] function exists in widget_from_element.dart\n- [ ] Build function added to _buildFnLookup\n- [ ] Widget exported in widgets/index.dart\n- [ ] AnimatedAttributes mixin applied if widget has animatable properties (width, height, Offset, etc.)\n- [ ] mergeWithDataSource used to get merged attributes in widgets with AnimatedAttributes\n- [ ] Tests exist for both controlled and non-controlled versions\n- [ ] Tests use XDriver.static\n- [ ] Tests verify attribute updates for controlled widgets\n- [ ] Attribute access uses proper methods (tryGetDouble, getBool, etc.)\n- [ ] Default values provided where appropriate\n\n### Theme Support Checklist (REQUIRED for ALL widgets)\n\n- [ ] Widget type is added to `DuitThemePreprocessor.createToken()` in `lib/src/ui/theme/preprocessor.dart`\n- [ ] Appropriate theme token class is selected and instantiated for the widget type\n- [ ] Theme token correctly excludes fields that should NOT be themed (callbacks, data, structural properties)\n- [ ] Tests verify theme application for the widget (theme data merged with attributes)\n- [ ] Tests cover both `themeOverlay` and `themePriority` override rules if applicable\n- [ ] Widget implementation does NOT explicitly handle theme application (themes are applied automatically via ViewAttribute.from())\n- [ ] If widget has special theme requirements, custom theme token is documented in implementation comments\n\n## Widget Type Decision Flow\n\nDetermine child relation:\n\n```\nWidget has no children → childRelation: 0\nWidget has one child → childRelation: 1\nWidget has multiple children → childRelation: 2\nWidget is component → childRelation: 3\nWidget is fragment → childRelation: 4\n```\n\nDetermine isControlledByDefault:\n\n```\nUser interaction required (Button, TextField, etc.) → true\nState management needed (Animation, etc.) → true\nStatic wrapper only → false\n```\n\n## Common Mistakes to Avoid\n\n1. **Missing controlled version**: Always create both Duit[WidgetName] and DuitControlled[WidgetName]\n2. **Wrong key type**: Use `ValueKey` not just `Key`\n3. **Forgetting attachStateToController**: Must call this in initState for controlled widgets\n4. **Wrong childRelation**: Check widget signature for single vs multiple children\n5. **Missing tests**: Every widget must have tests covering both versions\n6. **Not testing updates**: Controlled widgets must test attribute updates\n7. **Hard-coded values**: Always use attrs methods to extract values from JSON\n8. **Missing AnimatedAttributes for animatable properties**: If a widget has properties that support animation (width, height, Offset, etc.), always apply the AnimatedAttributes mixin and use mergeWithDataSource to merge animated values\n"},"lastSynced":"2026-03-06T06:35:05.220Z","agentAnalysis":{"suitability":{"en":"Perfect for Flutter Agents needing consistent and reusable UI components.","zh":"非常适合需要一致且可重用 UI 组件的 Flutter 代理。","ja":"一貫性と再利用性のある UI コンポーネントが必要な Flutter エージェントに最適です。","ko":"일관성 있고 재사용 가능한 UI 컴포넌트가 필요한 Flutter 에이전트에 적합합니다.","es":"Perfecto para agentes de Flutter que necesitan componentes de interfaz de usuario consistentes y reutilizables.","fr":"Parfait pour les agents Flutter ayant besoin de composants d''interface utilisateur cohérents et réutilisables.","de":"Perfekt für Flutter-Agents, die konsistente und wiederverwendbare Benutzeroberflächenkomponenten benötigen.","pt":"Perfeito para Agentes Flutter que necessitam de componentes de UI consistentes e reutilizáveis.","ru":"Идеально подходит для агентов Flutter, которым требуются последовательные и многократно используемые компоненты интерфейса пользователя.","ar":"مثالي للوكلاء Flutter الذين يحتاجون إلى مكونات واجهة مستخدم متسقة وقابلة لإعادة الاستخدام."},"recommendation":{"en":"Empowers agents to generate consistent UI components using Flutter and Dart, providing a server-driven UI framework with reusable widgets and ViewAttribute implementation.","zh":"赋予代理使用 Flutter 和 Dart 生成一致的 UI 组件，提供一个服务驱动的 UI 框架，具有可重用的小部件和 ViewAttribute 实现。","ja":"エージェントが Flutter と Dart を使用して一貫性のある UI コンポーネントを生成できるようにし、再利用可能なウィジェットと ViewAttribute の実装を備えたサーバー駆動の UI フレームワークを提供します。","ko":"에이전트가 Flutter와 Dart를 사용하여 일관된 UI 컴포넌트를 생성할 수 있도록 하며, 재사용 가능한 위젯과 ViewAttribute 구현을 갖춘 서버 주도 UI 프레임워크를 제공합니다.","es":"Habilita a los agentes para generar componentes de interfaz de usuario coherentes utilizando Flutter y Dart, proporcionando un marco de interfaz de usuario basado en servidor con widgets reutilizables y implementación de ViewAttribute.","fr":"Permet aux agents de générer des composants d''interface utilisateur cohérents en utilisant Flutter et Dart, en fournissant un cadre d''interface utilisateur piloté par le serveur avec des widgets réutilisables et une implémentation de ViewAttribute.","de":"Ermächtigt Agenten, konsistente Benutzeroberflächenkomponenten mit Flutter und Dart zu generieren und bietet ein serverseitiges Benutzeroberflächenframework mit wiederverwendbaren Widgets und ViewAttribute-Implementierung.","pt":"Habilita os agentes a gerar componentes de UI consistentes usando Flutter e Dart, fornecendo um framework de UI orientado a servidor com widgets reutilizáveis e implementação de ViewAttribute.","ru":"Наделяет агентов возможностью генерировать последовательные компоненты интерфейса пользователя с помощью Flutter и Dart, предоставляя серверно-ориентированный фреймворк интерфейса пользователя с многократно используемыми виджетами и реализацией ViewAttribute.","ar":"يمكّن الوكلاء من生成 مكونات واجهة مستخدم متسقة باستخدام Flutter و Dart، مع توفير إطار عمل واجهة مستخدم محور الخادم مع أدوات قابلة لإعادة الاستخدام وتنفيذ سمة العرض."},"useCases":{"en":["Creating new widgets with consistent patterns","Implementing widget classes with ViewAttribute and child widgets","Maintaining consistent UI across flutter_duit widgets"],"zh":["使用一致的模式创建新的小部件","使用 ViewAttribute 和子小部件实现小部件类","在 flutter_duit 小部件中保持一致的 UI"],"ja":["一貫性のあるパターンを使用して新しいウィジェットを作成する","ViewAttribute と子ウィジェットを使用してウィジェット クラスを実装する","flutter_duit ウィジェット全体で一貫性のある UI を維持する"],"ko":["일관된 패턴을 사용하여 새로운 위젯을 생성하는 것","ViewAttribute와 자식 위젯을 사용하여 위젯 클래스를 구현하는 것","flutter_duit 위젯에서 일관된 UI를 유지하는 것"],"es":["Crear nuevos widgets con patrones coherentes","Implementar clases de widgets con ViewAttribute y widgets secundarios","Mantener una interfaz de usuario coherente en los widgets flutter_duit"],"fr":["Créer de nouveaux widgets avec des modèles cohérents","Implémenter des classes de widgets avec ViewAttribute et des widgets enfants","Maintenir une interface utilisateur cohérente sur les widgets flutter_duit"],"de":["Erstellen von neuen Widgets mit konsistenten Mustern","Implementieren von Widget-Klassen mit ViewAttribute und Kind-Widgets","Beibehalten einer konsistenten Benutzeroberfläche in flutter_duit-Widgets"],"pt":["Criar novos widgets com padrões consistentes","Implementar classes de widgets com ViewAttribute e widgets filho","Manter uma interface do usuário consistente em todo o flutter_duit widgets"],"ru":["Создание новых виджетов с последовательными шаблонами","Реализация классов виджетов с ViewAttribute и дочерними виджетами","Поддержание последовательного интерфейса пользователя на всех виджетах flutter_duit"],"ar":["إنشاء أدوات جديدة مع أنماط متسقة","تنفيذ فئات الأدوات مع سمة العرض والأدوات الفرعية","الحفاظ على واجهة مستخدم متسقة في جميع أدوات flutter_duit"]},"limitations":{"en":["Requires knowledge of Flutter and Dart","Limited to Flutter development environment"],"zh":["需要了解 Flutter 和 Dart","仅限 Flutter 开发环境"],"ja":["Flutter と Dart の知識が必要","Flutter 開発環境のみに限定される"],"ko":["Flutter와 Dart에 대한 지식이 필요함","Flutter 개발 환경에만 제한됨"],"es":["Requiere conocimiento de Flutter y Dart","Limitado al entorno de desarrollo de Flutter"],"fr":["Nécessite des connaissances en Flutter et Dart","Limité à l''environnement de développement Flutter"],"de":["Benötigt Kenntnisse von Flutter und Dart","Begrenzt auf die Flutter-Entwicklungsumgebung"],"pt":["Requer conhecimento de Flutter e Dart","Limitado ao ambiente de desenvolvimento do Flutter"],"ru":["Требует знания Flutter и Dart","Ограничен только средой разработки Flutter"],"ar":["يتطلب معرفة Flutter و Dart","محدود بيئة تطوير Flutter فقط"]},"version":4},"contentHash":"33aca70967c733c385ea6c6a30c97c3f51e58e75929e187b52e8f94684a53398","qualityScore":41}');
