INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Duit-Foundation/flutter_duit/duit-maintainer', 'duit-maintainer', 'Duit-Foundation', 'flutter_duit', 'community', 'duit-maintainer Duit-Foundation flutter_duit community bdui dart flutter sdui ui The duit-maintainer skill provides a server-driven UI framework for Flutter, enabling developers to create consistent and reusable UI components. It benefits Flutter developers working with UI toolkits. Duit Maintainer 是一个 Flutter 服务器驱动 UI 框架，用于创建一致的 UI 组件 Duit Maintainer は、Flutter サーバー駆動 UI フレームワークを使用して一貫性のある UI コンポーネントを作成するために使用されます Duit Maintainer는 일관된 UI 구성 요소를 생성하기 위해 사용되는 Flutter 서버 드리븐 UI 프레임워크입니다 Duit Maintainer es un kit de herramientas de interfaz de usuario para Flutter que permite la creación de interfaces de usuario personalizadas Duit Maintainer est un kit d''outils d''interface utilisateur pour Flutter qui permet de créer des interfaces utilisateur personnalisées Duit Maintainer ist ein Benutzeroberflächen-Toolkit für Flutter, das die Erstellung von benutzerdefinierten Benutzeroberflächen ermöglicht O Duit Maintainer é um toolkit de UI para Flutter que permite criar interfaces de usuário personalizadas. Aprenda a configurá-lo para melhorar seus projetos. Duit Maintainer - это набор инструментов для создания интерфейсов пользователя для Flutter. Узнайте, как настроить его для улучшения своих проектов ИИ Агентов. دويت مينتينر هو أداة واجهة مستخدم ل Flutter التي تمكنك من إنشاء واجهات مستخدم مخصصة. تعلم كيفية إعدادها لتحسين مشاريعك. how to use duit-maintainer duit-maintainer setup guide flutter ui toolkit server-driven ui framework duit-maintainer vs bdui duit-maintainer install what is duit-maintainer duit-maintainer alternative flutter_duit implementation Duit Maintainer Flutter 服务器驱动 UI 框架 Dart Flutter UI 组件 服务器驱动 UI ViewAttribute Widget Implements widget classes using Dart and Flutter Creates widget implementation files in lib/src/ui/widgets/ Follows a consistent pattern for widget implementation Uses ViewAttribute and Widget child properties Supports server-driven UI framework for Flutter duit-maintainer is a server-driven UI framework for Flutter, providing a consistent implementation pattern for UI widgets and components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Chia-Network/cadt/cadt-testing', 'community', 'Chia-Network', 'cadt', 'Chia-Network/cadt', 'cadt-testing', 39, 14, 41, '2026-03-01T22:07:49Z', '2026-03-06T06:37:28.250Z', '68345155bfa2b661522bb83f62a35609b203a78ab50c7eff3bc40064ebd7db17', '{"id":"Chia-Network/cadt/cadt-testing","name":"cadt-testing","description":{"en":"The cadt-testing skill enables developers to run integration tests for Climate Action Data Trust using in-memory SQLite and simulator. It benefits developers working with Chia blockchain and cadt-testing protocols.","zh":"CADT 测试是一个 Climate Action Data Trust 项目，用于测试和验证数据。它支持集成测试和模拟模式","ja":"CADT テストは Climate Action Data Trust プロジェクトで、データをテストおよび検証するために使用されます。インテグレーションテストとシミュレーションモードをサポートしています","ko":"CADT 테스트는 Climate Action Data Trust 프로젝트에서 데이터를 테스트하고 검증하는 데 사용됩니다. 통합 테스트와 시뮬레이션 모드를 지원합니다","es":"cadt-testing es una herramienta de prueba para Climate Action Data Trust, que permite a los desarrolladores probar la integración con Chia Blockchain de forma segura","fr":"cadt-testing est un outil de test pour Climate Action Data Trust, qui permet aux développeurs de tester l''intégration avec Chia Blockchain de manière sécurisée","de":"cadt-testing ist ein Testtool für Climate Action Data Trust, das es Entwicklern ermöglicht, die Integration mit Chia Blockchain sicher zu testen","pt":"O CADT Testing é uma ferramenta para simulações de integração com o Chia Blockchain. Execute testes em paralelo com o npm","ru":"Тестирование CADT - это инструмент для интеграционных симуляций с Chia Blockchain. Запускайте параллельные тесты с помощью npm","ar":"اختبار CADT هو أداة لمحاكاة التكامل مع تشيا بلوكشين. قم بتشغيل الاختبارات الموازية مع npm"},"seo":{"title":{"en":"cadt-testing: Setup Guide for Climate Action Data Trust |...","zh":"CADT 测试设置指南 - Climate Action Data Trust","ja":"CADT テストベストプラクティス - Climate Action Data Trust AIエージェント","ko":"CADT 테스트 가이드 - Climate Action Data Trust","es":"Guía de configuración de cadt-testing para desarrolladores","fr":"Guide de configuration de cadt-testing pour les développeurs","de":"Einrichtungsleitfaden für cadt-testing-Entwickler","pt":"Guia de Configuração do CADT Testing com Chia Blockchain","ru":"Настройка тестирования CADT с помощью ИИ Агентов и Chia B...","ar":"دليل إعداد اختبار CADT مع تشيا بلوكشين"},"description":{"en":"Learn how to integrate cadt-testing with Chia blockchain and run parallel integration tests with ease. Get started now and streamline your testing process!","zh":"了解 CADT 测试的技术细节，包括集成测试、模拟模式和 Chia 区块链集成","ja":"CADT テストのテクニカルな詳細を学びましょう。シミュレーションモード、インテグレーションテスト、Chia ブロックチェーンの統合など","ko":"CADT 테스트의 기술적 세부 정보를 알아보세요. 통합 테스트, 시뮬레이션 모드, Chia 블록체인 통합 등","es":"Aprende a configurar y probar cadt-testing con nuestra guía paso a paso para desarrolladores, incluyendo integración con Chia Blockchain","fr":"Découvrez comment configurer et tester cadt-testing avec notre guide étape par étape pour les développeurs, y compris l''intégration avec Chia Blockchain","de":"Erfahren Sie, wie Sie cadt-testing konfigurieren und testen können, mit unserer Schritt-für-Schritt-Anleitung für Entwickler, einschließlich Integration mit ...","pt":"Aprenda a configurar o CADT Testing com o Chia Blockchain para simulações de integração e testes em paralelo","ru":"Узнайте, как настроить тестирование CADT с помощью Chia Blockchain для интеграционных симуляций и параллельных тестов","ar":"تعرف على كيفية إعداد اختبار CADT مع تشيا بلوكشين لتحقيق التمثيلات التكاملية والاختبارات الموازية"},"definition":{"en":"cadt-testing is a skill that facilitates Climate Action Data Trust testing using node-environment rules and parallel test execution via npm commands.","zh":"CADT 测试是 Climate Action Data Trust 的一个组成部分，用于测试和验证数据的正确性","ja":"CADT テストは Climate Action Data Trust の一部で、データの正確性をテストおよび検証するために使用されます","ko":"CADT 테스트는 Climate Action Data Trust의 일부로서 데이터의 정확성을 테스트하고 검증하는 데 사용됩니다","es":"cadt-testing es una herramienta de prueba para Climate Action Data Trust que utiliza SQLite y simulator para probar la integración","fr":"cadt-testing est un outil de test pour Climate Action Data Trust qui utilise SQLite et un simulateur pour tester l''intégration","de":"cadt-testing ist ein Testtool für Climate Action Data Trust, das SQLite und einen Simulator verwendet, um die Integration zu testen","pt":"O que é CADT Testing? Uma ferramenta de simulação de integração para o Chia Blockchain","ru":"Что такое тестирование CADT? Инструмент для интеграционных симуляций для Chia Blockchain","ar":"ما هو اختبار CADT؟ أداة لمحاكاة التكامل لتشيا بلوكشين"},"features":{"en":["Runs integration tests in simulation mode using in-memory SQLite","Executes parallel tests for v1 and v2 using npm run commands","Utilizes isolated databases via TEST_RUN_ID environment variable","Supports Chia blockchain integration","Employs node-environment rules for test execution","Uses CW_PORT environment variable for port management"],"zh":["支持集成测试","模拟模式下运行","不需要 CADT 服务器、Chia 或数据层","使用 in-memory SQLite 数据库","支持并行运行多个测试用例"],"ja":["インテグレーションテストをサポート","シミュレーションモードで実行","CADT サーバー、Chia、またはデータレイヤーは必要ありません","インメモリSQLite データベースを使用","複数のテストケースを並行して実行可能"],"ko":["통합 테스트 지원","시뮬레이션 모드에서 실행","CADT 서버, Chia 또는 데이터 레이어 필요 없음","인메모리 SQLite 데이터베이스 사용","여러 테스트 케이스를 병렬로 실행 가능"],"es":["Integración con Chia Blockchain","Uso de SQLite para pruebas en memoria","Simulador para pruebas de integración","Compatibilidad con Node.js","Soporte para pruebas paralelas con npm run test:v1 y npm run test:v2"],"fr":["Intégration avec Chia Blockchain","Utilisation de SQLite pour les tests en mémoire","Simulateur pour les tests d''intégration","Compatibilité avec Node.js","Prise en charge des tests parallèles avec npm run test:v1 et npm run test:v2"],"de":["Integration mit Chia Blockchain","Verwendung von SQLite für Speichertests","Simulator für Integrationstests","Kompatibilität mit Node.js","Unterstützung für parallele Tests mit npm run test:v1 und npm run test:v2"],"pt":["Simulações de integração com o Chia Blockchain","Testes em paralelo com o npm","Utilização do SQLite em memória","Suporte a v1 e v2","Isolamento de bancos de dados via TEST_RUN_ID","Utilização do CW_PORT para comunicação"],"ru":["Интеграционные симуляции с Chia Blockchain","Параллельные тесты с помощью npm","Использование SQLite в памяти","Поддержка v1 и v2","Изоляция баз данных через TEST_RUN_ID","Использование CW_PORT для связи"],"ar":["محاكاة التكامل مع تشيا بلوكشين","الاختبارات الموازية مع npm","استخدام SQLite في الذاكرة","دعم v1 و v2","عزل قواعد البيانات عبر TEST_RUN_ID","استخدام CW_PORT للاتصال"]},"keywords":{"en":["how to use cadt-testing","cadt-testing setup guide","cadt-testing and Chia blockchain","cadt-testing alternative","cadt-testing vs blockchain testing tools","install cadt-testing","cadt-testing tutorial","what is cadt-testing","cadt-testing best practices"],"zh":["CADT 测试","Climate Action Data Trust","集成测试","模拟模式","Chia 区块链","in-memory SQLite","CADT 服务器","数据层"],"ja":["CADT テスト","Climate Action Data Trust","インテグレーションテスト","シミュレーションモード","Chia ブロックチェーン","インメモリSQLite","CADT サーバー","データレイヤー","AIエージェント"],"ko":["CADT 테스트","Climate Action Data Trust","통합 테스트","시뮬레이션 모드","Chia 블록체인","인메모리 SQLite","CADT 서버","데이터 레이어"],"es":["cadt-testing","Climate Action Data Trust","Chia Blockchain","pruebas de integración","SQLite","simulador","Node.js","desarrollo de software","herramientas de prueba"],"fr":["cadt-testing","Climate Action Data Trust","Chia Blockchain","tests d''intégration","SQLite","simulateur","Node.js","développement de logiciels","outils de test"],"de":["cadt-testing","Climate Action Data Trust","Chia Blockchain","Integrationstests","SQLite","Simulator","Node.js","Softwareentwicklung","Testtools"],"pt":["cadt testing","chia blockchain","simulação de integração","testes em paralelo","npm","sqlite","v1","v2","TEST_RUN_ID","CW_PORT"],"ru":["тестирование cadt","chia blockchain","интеграционные симуляции","параллельные тесты","npm","sqlite","v1","v2","TEST_RUN_ID","CW_PORT"],"ar":["اختبار cadt","تشيا بلوكشين","محاكاة التكامل","الاختبارات الموازية","npm","sqlite","v1","v2","TEST_RUN_ID","CW_PORT"]}},"owner":"Chia-Network","repo":"cadt","repoPath":"Chia-Network/cadt","stars":39,"forks":14,"updatedAt":"2026-03-01T22:07:49Z","topics":["chia-blockchain"],"category":"community","skillMd":{"name":"cadt-testing","description":"Run CADT integration tests, live API tests, and test data cleanup. Use when the user asks to run integration tests, run v1 or v2 tests, run live API tests, or delete test data.","bodyPreview":"# CADT Testing\n\nPrefix all commands with `fnm use &&` per the `node-environment` rule.\n\n## Integration Tests (Simulation Mode)\n\nIn-memory SQLite with simulator. No CADT server, Chia, or datalayer required.\n\n### \"Run the integration tests\" = run both v1 and v2 in parallel\n\n```bash\nnpm run test:v1 &\nnpm run test:v2 &\nwait\n```\n\nV1 and V2 use different ports (31310 and 31311 via `CW_PORT` env var) and isolated\ndatabases (via `TEST_RUN_ID`), so they run safely in parallel. Do **not** use the\ncombined","body":"# CADT Testing\n\nPrefix all commands with `fnm use &&` per the `node-environment` rule.\n\n## Integration Tests (Simulation Mode)\n\nIn-memory SQLite with simulator. No CADT server, Chia, or datalayer required.\n\n### \"Run the integration tests\" = run both v1 and v2 in parallel\n\n```bash\nnpm run test:v1 &\nnpm run test:v2 &\nwait\n```\n\nV1 and V2 use different ports (31310 and 31311 via `CW_PORT` env var) and isolated\ndatabases (via `TEST_RUN_ID`), so they run safely in parallel. Do **not** use the\ncombined `npm test` script — it runs all specs in one process, causing v1/v2 interference.\n\n| Command | Port | Test files |\n|---------|------|-----------|\n| `npm run test:v1` | 31310 | `tests/integration/**/*.spec.js`, `tests/resources/**/*.spec.js` |\n| `npm run test:v2` | 31311 | `tests/v2/integration/**/*.spec.js` |\n\n### How they work\n\n- `run-tests.sh` generates a unique `TEST_RUN_ID`, creates isolated SQLite DBs in `tests/test-dbs/`, cleans up on exit\n- Environment: `NODE_ENV=test`, `USE_SIMULATOR=true`, `CW_PORT=<port>`\n- Port isolation: `CW_PORT` env var overrides `APP.CW_PORT` in config-loader.js\n- Timeout: 300s per test\n\n## Live API Tests\n\nRun against a real CADT server with actual Chia datalayer.\n\n### Prerequisites\n\n- CADT server running on port 31310\n- Chia node + datalayer running and synced\n- Home organization created\n- Empty database for POST phases (or `SKIP_EMPTY_CHECK=true`)\n- Config at `~/.chia/mainnet/cadt/config.yaml`\n- Optional: MySQL mirror DB for mirror verification\n\n### \"Run the v2 live API test\" = data-short\n\n```bash\nnpm run test:v2:live:data:short\n```\n\nRuns `tests/v2/live-api/data-short.js`:\n1. Validate request failures (bad data rejected)\n2. POST all test records, batch commit\n3. Validate child record failures\n4. PUT all records, batch commit\n5. DELETE all records, batch commit\n\nAfter each commit, verifies records in DB (and optionally MySQL mirror).\n\n### All live API commands\n\n| Command | Purpose |\n|---------|---------|\n| `npm run test:v2:live:data:short` | V2 short mode: batch commit per phase |\n| `npm run test:v2:live:data:extended` | V2 extended mode: commit per endpoint |\n| `npm run test:v1:live:data:short` | V1 short mode |\n| `npm run test:v2:live:organization:create` | Create V2 home organization |\n| `npm run test:v1:live:organization:create` | Create V1 home organization |\n| `npm run test:v1:live:organization:upgrade` | Upgrade V1 org to V2 |\n| `npm run test:v2:live:organization:delete` | Delete V2 organization |\n\n### Test modes\n\n- **Short** (`TEST_MODE=short`): Batch all POSTs/PUTs/DELETEs with one commit per phase. Faster.\n- **Extended** (`TEST_MODE=extended`): Each test file commits individually. More thorough.\n\n## Delete Test Data\n\nIf user specifies a version, run that version. If unspecified, run both:\n\n```bash\nnpm run test:v1:delete-test-data\nnpm run test:v2:delete-test-data\n```\n\n| Command | Behavior |\n|---------|----------|\n| `npm run test:v1:delete-test-data` | Deletes records with `TEST-` prefix from V1 projects and units |\n| `npm run test:v2:delete-test-data` | Deletes all records from 20 V2 data tables (children first) |\n\nBoth require a running CADT server. Timeout: 600s.\n\nV2 delete flow: clear staging -> GET all -> stage DELETEs -> commit -> wait for staging empty -> verify.\n"},"lastSynced":"2026-03-06T06:37:28.250Z","agentAnalysis":{"suitability":{"en":"Ideal for Blockchain Agents working with Chia blockchain and cadt-testing protocols, needing advanced integration testing capabilities.","zh":"适用于使用Chia区块链和cadt-testing协议的区块链代理，需要高级集成测试能力。","ja":"Chiaブロックチェーンとcadt-testingプロトコルを使用するブロックチェーンエージェントに適しています。高度な統合テスト機能が必要です。","ko":"Chia 블록체인 및 cadt-testing 프로토콜을 사용하는 블록체인 에이전트에 적합합니다. 고급 통합 테스트 기능이 필요합니다.","es":"Ideal para Agentes de Blockchain que trabajan con la cadena de bloques Chia y los protocolos de prueba cadt, que necesitan capacidades de prueba de integración avanzadas.","fr":"Idéal pour les agents de blockchain travaillant avec la blockchain Chia et les protocoles de test cadt, ayant besoin de capacités de test d''intégration avancées.","de":"Ideal für Blockchain-Agenten, die mit der Chia-Blockchain und den cadt-Testprotokollen arbeiten und erweiterte Integrationstestfunktionen benötigen.","pt":"Ideal para Agentes de Blockchain que trabalham com a blockchain Chia e protocolos de teste cadt, necessitando de capacidades avançadas de teste de integração.","ru":"Идеально подходит для агентов блокчейна, работающих с блокчейном Chia и протоколами тестирования cadt, требующими продвинутых возможностей интеграционного тестирования.","ar":"مثالية للوكلاء بلوكشين الذين يعملون مع بلوكشين Chia وبروتوكولات اختبار cadt، وهم في حاجة إلى قدرات متقدمة لاختبار التكامل."},"recommendation":{"en":"Empowers agents to run comprehensive integration tests for Climate Action Data Trust using in-memory SQLite and simulator, leveraging npm scripts and environment variables like CW_PORT and TEST_RUN_ID, to ensure seamless testing of v1 and v2 protocols in parallel.","zh":"赋予代理在内存SQLite和模拟器中运行针对Climate Action Data Trust的综合集成测试的能力，利用npm脚本和环境变量如CW_PORT和TEST_RUN_ID，以确保v1和v2协议的无缝测试。","ja":"エージェントがClimate Action Data Trustのための包括的な統合テストを、内蔵SQLiteとシミュレーターで実行できるようにします。npmスクリプトとCW_PORTやTEST_RUN_IDなどの環境変数を利用して、v1とv2プロトコルの並列テストを可能にします。","ko":"에이전트가 Climate Action Data Trust를 위한 포괄적인 통합 테스트를 내存 SQLite와 시뮬레이터에서 실행할 수 있도록 합니다. npm 스크립트와 CW_PORT 및 TEST_RUN_ID와 같은 환경 변수를 활용하여 v1 및 v2 프로토콜의 병렬 테스트를 보장합니다.","es":"Habilita a los agentes a ejecutar pruebas de integración completas para Climate Action Data Trust utilizando SQLite en memoria y simulador, aprovechando scripts npm y variables de entorno como CW_PORT y TEST_RUN_ID, para garantizar una prueba sin problemas de los protocolos v1 y v2 en paralelo.","fr":"Permet aux agents d''exécuter des tests d''intégration complets pour Climate Action Data Trust en utilisant SQLite en mémoire et simulateur, en exploitant les scripts npm et les variables d''environnement comme CW_PORT et TEST_RUN_ID, pour assurer des tests sans problème des protocoles v1 et v2 en parallèle.","de":"Ermächtigt die Agenten, umfassende Integrationstests für Climate Action Data Trust durchzuführen, indem sie SQLite im Speicher und Simulator verwenden, npm-Skripte und Umgebungsvariablen wie CW_PORT und TEST_RUN_ID nutzend, um eine reibungslose Testung der Protokolle v1 und v2 in Parallelverarbeitung zu gewährleisten.","pt":"Habilita os agentes a executar testes de integração abrangentes para Climate Action Data Trust usando SQLite em memória e simulador, aproveitando scripts npm e variáveis de ambiente como CW_PORT e TEST_RUN_ID, para garantir testes sem problemas dos protocolos v1 e v2 em paralelo.","ru":"Наделяет агентов возможностью запускать комплексные интеграционные тесты для Climate Action Data Trust с использованием SQLite в памяти и симулятора, используя скрипты npm и переменные среды, такие как CW_PORT и TEST_RUN_ID, для обеспечения бесперебойного тестирования протоколов v1 и v2 параллельно.","ar":"تمكّن الوكلاء من تشغيل اختبارات تكامل شاملة لClimate Action Data Trust باستخدام SQLite في الذاكرة ومحاكي، واستخدام سكريبتات npm ومتغيرات البيئة مثل CW_PORT و TEST_RUN_ID، لضمان اختبارات بدون مشاكل لبروتوكولات v1 و v2 بالتوازي."},"useCases":{"en":["Running integration tests in simulation mode","Testing cadt-testing protocols with in-memory SQLite","Debugging Chia blockchain integrations using isolated databases"],"zh":["在模拟模式下运行集成测试","使用内存SQLite测试cadt-testing协议","使用隔离数据库调试Chia区块链集成"],"ja":["シミュレーションモードで統合テストを実行する","内蔵SQLiteを使用してcadt-testingプロトコルをテストする","分離データベースを使用してChiaブロックチェーン統合をデバッグする"],"ko":["시뮬레이션 모드에서 통합 테스트를 실행하는 것","내存 SQLite를 사용하여 cadt-testing 프로토콜을 테스트하는 것","분리된 데이터베이스를 사용하여 Chia 블록체인 통합을 디버깅하는 것"],"es":["Ejecutar pruebas de integración en modo de simulación","Probar protocolos de prueba cadt con SQLite en memoria","Depurar integraciones de blockchain Chia utilizando bases de datos aisladas"],"fr":["Exécuter des tests d''intégration en mode de simulation","Tester les protocoles de test cadt avec SQLite en mémoire","Déboguer les intégrations de blockchain Chia en utilisant des bases de données isolées"],"de":["Integrationstests im Simulationsmodus ausführen","cadt-Testprotokolle mit SQLite im Speicher testen","Chia-Blockchain-Integrationen mithilfe isolierter Datenbanken debuggen"],"pt":["Execução de testes de integração no modo de simulação","Teste de protocolos de teste cadt com SQLite em memória","Depuração de integrações de blockchain Chia usando bancos de dados isolados"],"ru":["Запуск интеграционных тестов в режиме симуляции","Тестирование протоколов тестирования cadt с использованием SQLite в памяти","Отладка интеграций блокчейна Chia с использованием изолированных баз данных"],"ar":["تشغيل اختبارات التكامل في وضع المحاكاة","اختبار بروتوكولات اختبار cadt باستخدام SQLite في الذاكرة","تصحيح أخطاء تكاملات بلوكشين Chia باستخدام قواعد بيانات معزولة"]},"limitations":{"en":["Requires npm environment","Specific to Climate Action Data Trust and Chia blockchain","Uses in-memory SQLite, may not reflect production database performance"],"zh":["需要npm环境","特定于Climate Action Data Trust和Chia区块链","使用内存SQLite，可能不能反映生产数据库性能"],"ja":["npm環境が必要","Climate Action Data TrustとChiaブロックチェーンに特有","内蔵SQLiteを使用しているため、生産環境のデータベース性能と一致しない可能性がある"],"ko":["npm 환경이 필요합니다","Climate Action Data Trust 및 Chia 블록체인에 특정됩니다","내存 SQLite를 사용하므로 프로덕션 데이터베이스 성능을 반영하지 않을 수 있습니다"],"es":["Requiere entorno npm","Específico para Climate Action Data Trust y blockchain Chia","Utiliza SQLite en memoria, puede que no refleje el rendimiento de la base de datos de producción"],"fr":["Nécessite un environnement npm","Spécifique à Climate Action Data Trust et à la blockchain Chia","Utilise SQLite en mémoire, peut ne pas refléter les performances de la base de données de production"],"de":["Benötigt npm-Umgebung","Spezifisch für Climate Action Data Trust und Chia-Blockchain","Verwendet SQLite im Speicher, kann die Leistung der Produktionsdatenbank nicht widerspiegeln"],"pt":["Exige ambiente npm","Específico para Climate Action Data Trust e blockchain Chia","Utiliza SQLite em memória, pode não refletir o desempenho do banco de dados de produção"],"ru":["Требует среды npm","Специфичен для Climate Action Data Trust и блокчейна Chia","Использует SQLite в памяти, может не отражать производительность базы данных производства"],"ar":["يتطلب بيئة npm","محدد لClimate Action Data Trust وبلوكشين Chia","يستخدم SQLite في الذاكرة، قد لا يعكس أداء قاعدة البيانات الإنتاجية"]},"version":4},"contentHash":"68345155bfa2b661522bb83f62a35609b203a78ab50c7eff3bc40064ebd7db17","qualityScore":41}');
