INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Chia-Network/cadt/cadt-testing', 'cadt-testing', 'Chia-Network', 'cadt', 'community', 'cadt-testing Chia-Network cadt community chia-blockchain The cadt-testing skill enables developers to run integration tests for Climate Action Data Trust using in-memory SQLite and simulator. It benefits developers working with Chia blockchain and cadt-testing protocols. CADT 测试是一个 Climate Action Data Trust 项目，用于测试和验证数据。它支持集成测试和模拟模式 CADT テストは Climate Action Data Trust プロジェクトで、データをテストおよび検証するために使用されます。インテグレーションテストとシミュレーションモードをサポートしています CADT 테스트는 Climate Action Data Trust 프로젝트에서 데이터를 테스트하고 검증하는 데 사용됩니다. 통합 테스트와 시뮬레이션 모드를 지원합니다 cadt-testing es una herramienta de prueba para Climate Action Data Trust, que permite a los desarrolladores probar la integración con Chia Blockchain de forma segura cadt-testing est un outil de test pour Climate Action Data Trust, qui permet aux développeurs de tester l''intégration avec Chia Blockchain de manière sécurisée cadt-testing ist ein Testtool für Climate Action Data Trust, das es Entwicklern ermöglicht, die Integration mit Chia Blockchain sicher zu testen O CADT Testing é uma ferramenta para simulações de integração com o Chia Blockchain. Execute testes em paralelo com o npm Тестирование CADT - это инструмент для интеграционных симуляций с Chia Blockchain. Запускайте параллельные тесты с помощью npm اختبار CADT هو أداة لمحاكاة التكامل مع تشيا بلوكشين. قم بتشغيل الاختبارات الموازية مع npm how to use cadt-testing cadt-testing setup guide cadt-testing and Chia blockchain cadt-testing alternative cadt-testing vs blockchain testing tools install cadt-testing cadt-testing tutorial what is cadt-testing cadt-testing best practices CADT 测试 Climate Action Data Trust 集成测试 模拟模式 Chia 区块链 in-memory SQLite CADT 服务器 数据层 Runs integration tests in simulation mode using in-memory SQLite Executes parallel tests for v1 and v2 using npm run commands Utilizes isolated databases via TEST_RUN_ID environment variable Supports Chia blockchain integration Employs node-environment rules for test execution Uses CW_PORT environment variable for port management cadt-testing is a skill that facilitates Climate Action Data Trust testing using node-environment rules and parallel test execution via npm commands.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaredpalmer/agentik/code-reviewer', 'community', 'jaredpalmer', 'agentik', 'jaredpalmer/agentik', 'code-reviewer', 17, 1, 41, '2026-02-22T15:53:09Z', '2026-03-06T06:42:26.063Z', '6b868599d2daabc3287ffe20a03350f4a51fccc029a80541a37bd823d047b364', '{"id":"jaredpalmer/agentik/code-reviewer","name":"code-reviewer","description":{"en":"The code-reviewer skill provides AI-driven code reviews for developers, helping them ensure high-quality code after implementing new features or refactoring existing ones.","zh":"代码审查工具是 Composable AI 代理运行时的一部分，用于审查 TypeScript 代码和 git diff","ja":"コードレビューツールは Composable AI エージェントランタイムの一部であり，TypeScript コードと git diff をレビューするために使用","ko":"코드 리뷰 도구는 Composable AI 에이전트 런타임의 일부로서 TypeScript 코드와 git diff를 리뷰하는 데 사용","es":"Code Reviewer es un runtime de agente de IA componible que ayuda a los desarrolladores a revisar su código de manera eficiente","fr":"Code Reviewer est un runtime d''agent d''IA composable qui aide les développeurs à examiner leur code de manière efficace","de":"Code Reviewer ist ein komponierbarer KI-Agents-Runtime, der Entwicklern hilft, ihren Code effizient zu überprüfen","pt":"O Code Reviewer é uma ferramenta de revisão de código baseada em AI que ajuda a melhorar a qualidade do código e a produtividade dos desenvolvedores","ru":"ИИ Агент Code Reviewer - это инструмент проверки кода, основанный на ИИ, который помогает улучшить качество кода и производительность разработчиков","ar":"مدقق الشفرة هو أداة مراجعة الشفرة القائمة على الذكاء الاصطناعي التي تساعد على تحسين جودة الشفرة وزيادة إنتاجية المطورين"},"seo":{"title":{"en":"code-reviewer: AI-Powered Code Review Setup Guide | AI Ag...","zh":"代码审查工具：Composable AI 代理运行时设置指南","ja":"コードレビューツール：Composable AI エージェントランタイムのベストプラクティス","ko":"코드 리뷰 도구: Composable AI 에이전트 런타임 설정 가이드","es":"Guía de configuración de Code Reviewer para Agentes de IA","fr":"Guide de mise en place de Code Reviewer pour Outils d''IA","de":"Einrichtungsleitfaden für Code Reviewer in KI-Agents","pt":"Guia de Configuração do Code Reviewer: Ferramentas de Rev...","ru":"Настройка ИИ Агента Code Reviewer: Руководство для Разраб...","ar":"دليل إعداد مدقق الشفرة: أدوات مراجعة الشفرة للمطورين"},"description":{"en":"Get expert code reviews with code-reviewer! Learn how to use this AI agent to optimize your coding workflow and improve code quality. Try it now!","zh":"使用代码审查工具提高代码质量，Composable AI 代理运行时提供代码审查功能，支持 TypeScript 和 git diff","ja":"コードレビューツールを使用してコード品質を向上させる，Composable AI エージェントランタイムはコードレビュー機能を提供，TypeScript と git diff をサポート","ko":"코드 리뷰 도구를 사용하여 코드 품질을 향상시키는 방법，Composable AI 에이전트 런타임은 코드 리뷰 기능을 제공하며 TypeScript와 git diff를 지원","es":"Aprende a utilizar Code Reviewer para revisar tu código de manera eficiente con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment utiliser Code Reviewer pour examiner votre code de manière efficace avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie Code Reviewer verwenden, um Ihren Code effizient zu überprüfen, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a configurar o Code Reviewer, uma ferramenta de revisão de código baseada em AI, para melhorar a qualidade do seu código e aumentar a produtividade","ru":"Узнайте, как настроить ИИ Агент Code Reviewer, инструмент проверки кода, чтобы улучшить качество вашего кода и повысить производительность","ar":"تعرف على كيفية إعداد مدقق الشفرة، أداة مراجعة الشفرة القائمة على الذكاء الاصطناعي، لتحسين جودة شفرتك وزيادة الإنتاجية"},"definition":{"en":"code-reviewer is a composable AI agent runtime that assists developers in reviewing code changes, such as new features or utility functions, before creating pull requests.","zh":"代码审查工具是一种 Composable AI 代理运行时，用于自动审查代码质量","ja":"コードレビューツールは Composable AI エージェントランタイムの一種であり，コード品質を自動でレビューする","ko":"코드 리뷰 도구는 Composable AI 에이전트 런타임의 일종으로서 코드 품질을 자동으로 리뷰","es":"Code Reviewer es un agente de IA que ayuda a los desarrolladores a revisar su código después de implementar una característica o función","fr":"Code Reviewer est un outil d''IA qui aide les développeurs à examiner leur code après avoir implémenté une fonctionnalité ou une fonction","de":"Code Reviewer ist ein KI-Agents, der Entwicklern hilft, ihren Code nach der Implementierung einer Funktion oder eines Features zu überprüfen","pt":"O Code Reviewer é uma ferramenta de revisão de código que utiliza AI para analisar e melhorar a qualidade do código","ru":"ИИ Агент Code Reviewer - это инструмент проверки кода, который использует ИИ для анализа и улучшения качества кода","ar":"مدقق الشفرة هو أداة مراجعة الشفرة التي تستخدم الذكاء الاصطناعي لتحليل و تحسين جودة الشفرة"},"features":{"en":["Reviews TypeScript files for new features and logical code chunks","Supports focused review of specific file sets via git diff","Assists in checking code quality before finalizing pull requests","Provides feedback on utility functions and refactored code","Integrates with existing Git workflows for seamless code review"],"zh":["支持 TypeScript 代码审查","集成 git diff 功能","提供代码质量审查报告","支持多种代码审查场景","与 Composable AI 代理运行时集成"],"ja":["TypeScript コードレビューをサポート","git diff 機能を統合","コード品質レビュー報告書を提供","複数のコードレビューシナリオをサポート","Composable AI エージェントランタイムと統合"],"ko":["TypeScript 코드 리뷰를 지원","git diff 기능을 통합","코드 품질 리뷰 보고서를 제공","다양한 코드 리뷰 시나리오를 지원","Composable AI 에이전트 런타임과 통합"],"es":["Revisión de código después de implementar una característica o función","Soporte para TypeScript y otros lenguajes de programación","Integración con git diff para revisar cambios específicos","Revisión enfocada de un conjunto específico de archivos","Compatibilidad con la creación de solicitudes de extracción"],"fr":["Examen de code après avoir implémenté une fonctionnalité ou une fonction","Prise en charge de TypeScript et d''autres langages de programmation","Intégration avec git diff pour examiner les modifications spécifiques","Examen ciblé d''un ensemble spécifique de fichiers","Compatibilité avec la création de demandes d''extraction"],"de":["Code-Überprüfung nach der Implementierung einer Funktion oder eines Features","Unterstützung für TypeScript und andere Programmiersprachen","Integration mit git diff zur Überprüfung spezifischer Änderungen","Fokussierte Überprüfung eines bestimmten Satzes von Dateien","Kompatibilität mit der Erstellung von Pull-Requests"],"pt":["Análise de código baseada em AI","Revisão de código personalizada","Integração com Git","Suporte a múltiplos idiomas de programação","Revisão de código em tempo real"],"ru":["Анализ кода на основе ИИ","Персональная проверка кода","Интеграция с Git","Поддержка нескольких языков программирования","Проверка кода в реальном времени"],"ar":["تحليل الشفرة القائم على الذكاء الاصطناعي","مراجعة الشفرة المخصصة","التكامل مع Git","دعم لغات البرمجة المتعددة","مراجعة الشفرة في الوقت الفعلي"]},"keywords":{"en":["how to use code-reviewer","code-reviewer alternative","code-reviewer setup guide","what is code-reviewer","code-reviewer vs human review","code-reviewer install for AI agents","code-reviewer for TypeScript development","AI-powered code review tools"],"zh":["代码审查工具","Composable AI 代理运行时","TypeScript 代码审查","git diff","代码质量审查","AI 代码审查","代码审查报告","代码审查场景"],"ja":["コードレビューツール","Composable AI エージェントランタイム","TypeScript コードレビュー","git diff","コード品質レビュー","AI コードレビュー","コードレビューレポート","コードレビューシナリオ"],"ko":["코드 리뷰 도구","Composable AI 에이전트 런타임","TypeScript 코드 리뷰","git diff","코드 품질 리뷰","AI 코드 리뷰","코드 리뷰 보고서","코드 리뷰 시나리오"],"es":["Code Reviewer","Agentes de IA","Herramientas de IA","Revisión de código","Desarrollo de software","Integración con git","TypeScript","Solicitudes de extracción"],"fr":["Code Reviewer","Outils d''IA","Agents d''IA","Examen de code","Développement de logiciels","Intégration avec git","TypeScript","Demandes d''extraction"],"de":["Code Reviewer","KI-Agents","KI-Tools","Code-Überprüfung","Software-Entwicklung","Integration mit git","TypeScript","Pull-Requests"],"pt":["code reviewer","ferramentas de revisão de código","ai para desenvolvedores","revisão de código personalizada","integração com git","desenvolvimento de software","qualidade de código","produtividade de desenvolvedores"],"ru":["ИИ Агент Code Reviewer","инструменты проверки кода","ИИ для разработчиков","персональная проверка кода","интеграция с git","разработка программного обеспечения","качество кода","производительность разработчиков"],"ar":["مدقق الشفرة","أدوات مراجعة الشفرة","الذكاء الاصطناعي للمطورين","مراجعة الشفرة المخصصة","التكامل مع Git","تطوير البرمجيات","جودة الشفرة","إنتاجية المطورين"]}},"owner":"jaredpalmer","repo":"agentik","repoPath":"jaredpalmer/agentik","stars":17,"forks":1,"updatedAt":"2026-02-22T15:53:09Z","topics":["agents","ai","ai-sdk"],"category":"community","skillMd":{"name":"code-reviewer","description":"Review code for adherence to project guidelines, style guides, and best practices. Use after writing or modifying code, especially before committing changes or creating pull requests.","bodyPreview":"# Code Reviewer Skill\n\n## When to Use This Skill\n\n- After implementing a feature or logical chunk of code.\n- After writing a utility function or refactor.\n- Before creating or finalizing a pull request.\n- When you need a focused review of a specific set of files (default: `git diff`).\n\n## Examples\n\n**Context:** The user has just implemented a new feature with several TypeScript files.\n**User:** \"I''ve added the new authentication feature. Can you check if everything looks good?\"\n**Assistant:** \"I","body":"# Code Reviewer Skill\n\n## When to Use This Skill\n\n- After implementing a feature or logical chunk of code.\n- After writing a utility function or refactor.\n- Before creating or finalizing a pull request.\n- When you need a focused review of a specific set of files (default: `git diff`).\n\n## Examples\n\n**Context:** The user has just implemented a new feature with several TypeScript files.\n**User:** \"I''ve added the new authentication feature. Can you check if everything looks good?\"\n**Assistant:** \"I''ll use the code-reviewer skill to review your recent changes.\"\n\n**Context:** The assistant has just written a new utility function.\n**User:** \"Please create a function to validate email addresses\"\n**Assistant:** \"Here''s the email validation function. Now I''ll use the code-reviewer skill to review this implementation.\"\n\n**Context:** The user is about to create a PR.\n**User:** \"I think I''m ready to create a PR for this feature\"\n**Assistant:** \"Before creating the PR, I''ll use the code-reviewer skill to ensure all code meets our standards.\"\n\nYou are an expert code reviewer specializing in modern software development across multiple languages and frameworks. Your primary responsibility is to review code against project guidelines in AGENTS.md with high precision to minimize false positives.\n\n## Review Scope\n\nBy default, review unstaged changes from `git diff`. The user may specify different files or scope to review.\n\n## Core Review Responsibilities\n\n**Project Guidelines Compliance**: Verify adherence to explicit project rules (typically in AGENTS.md or equivalent) including import patterns, framework conventions, language-specific style, function declarations, error handling, logging, testing practices, platform compatibility, and naming conventions.\n\n**Bug Detection**: Identify actual bugs that will impact functionality - logic errors, null/undefined handling, race conditions, memory leaks, security vulnerabilities, and performance problems.\n\n**Code Quality**: Evaluate significant issues like code duplication, missing critical error handling, accessibility problems, and inadequate test coverage.\n\n## Issue Confidence Scoring\n\nRate each issue from 0-100:\n\n- **0-25**: Likely false positive or pre-existing issue\n- **26-50**: Minor nitpick not explicitly in AGENTS.md\n- **51-75**: Valid but low-impact issue\n- **76-90**: Important issue requiring attention\n- **91-100**: Critical bug or explicit AGENTS.md violation\n\n**Only report issues with confidence ≥ 80**\n\n## Output Format\n\nStart by listing what you''re reviewing. For each high-confidence issue provide:\n\n- Clear description and confidence score\n- File path and line number\n- Specific AGENTS.md rule or bug explanation\n- Concrete fix suggestion\n\nGroup issues by severity (Critical: 90-100, Important: 80-89).\n\nIf no high-confidence issues exist, confirm the code meets standards with a brief summary.\n\nBe thorough but filter aggressively - quality over quantity. Focus on issues that truly matter.\n"},"lastSynced":"2026-03-06T06:42:26.063Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated code review and analysis for TypeScript and other programming languages.","zh":"非常适合需要自动化代码审查和分析TypeScript和其他编程语言的Developer Agents。","ja":"TypeScriptおよびその他のプログラミング言語の自動コードレビューと分析が必要なDeveloper Agentsに最適です。","ko":"TypeScript 및 기타 프로그래밍 언어에 대한 자동화된 코드 리뷰 및 분석이 필요한 Developer Agents에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan revisión y análisis de código automatizados para TypeScript y otros lenguajes de programación.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une revue et d''une analyse de code automatisées pour TypeScript et d''autres langages de programmation.","de":"Perfekt für Entwickleragenten, die eine automatisierte Code-Überprüfung und -Analyse für TypeScript und andere Programmiersprachen benötigen.","pt":"Perfeito para Agentes de Desenvolvedores que precisam de revisão e análise de código automatizadas para TypeScript e outras linguagens de programação.","ru":"Идеально подходит для агентов-разработчиков, которым необходима автоматизированная проверка и анализ кода для TypeScript и других языков программирования.","ar":"مثالي لعميل المطور الذي يحتاج إلى مراجعة و تحليل الكود التلقائي للغة TypeScript وأي لغة برمجة أخرى."},"recommendation":{"en":"Empowers agents to perform thorough code reviews using git diff, ensuring high-quality code after implementing new features or refactoring existing ones, and supporting developers in creating focused reviews of specific sets of files.","zh":"赋予代理商使用git diff进行彻底的代码审查的能力，确保在实施新功能或重构现有功能后代码的高质量，并支持开发人员创建特定文件集的专注审查。","ja":"git diffを使用した徹底的なコードレビューを行うエージェントの能力を提供し、新機能の実装や既存の機能のリファクタリング後に高品質のコードを確保し、開発者が特定のファイルセットの集中レビューを作成することをサポートします。","ko":"git diff를 사용하여 철저한 코드 리뷰를 수행하는 에이전트의 능력을 제공하여 새로운 기능을 구현하거나 기존 기능을 리팩토링한 후에 높은 품질의 코드를 보장하고 개발자가 특정 파일 세트에 대한 집중 리뷰를 생성하는 것을 지원합니다.","es":"Habilita a los agentes a realizar revisiones de código exhaustivas utilizando git diff, asegurando un código de alta calidad después de implementar nuevas características o refactorizar las existentes, y apoyando a los desarrolladores en la creación de revisiones enfocadas de conjuntos específicos de archivos.","fr":"Permet aux agents d''effectuer des revues de code approfondies en utilisant git diff, garantissant un code de haute qualité après la mise en œuvre de nouvelles fonctionnalités ou le refactoring de celles existantes, et aidant les développeurs à créer des revues ciblées de jeux de fichiers spécifiques.","de":"Ermächtigt die Agenten, gründliche Code-Reviews unter Verwendung von git diff durchzuführen, um einen hochwertigen Code nach der Implementierung neuer Funktionen oder dem Refactoring bestehender sicherzustellen und die Entwickler bei der Erstellung fokussierter Reviews bestimmter Dateisätze zu unterstützen.","pt":"Habilita os agentes a realizar revisões de código abrangentes usando git diff, garantindo um código de alta qualidade após a implementação de novos recursos ou reestruturação de recursos existentes, e apoiando os desenvolvedores na criação de revisões focadas de conjuntos específicos de arquivos.","ru":"Наделяет агентов возможностью проводить тщательные проверки кода с помощью git diff, обеспечивая высокое качество кода после реализации новых функ