INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jaredpalmer/agentik/code-reviewer', 'code-reviewer', 'jaredpalmer', 'agentik', 'community', 'code-reviewer jaredpalmer agentik community agents ai ai-sdk The code-reviewer skill provides AI-driven code reviews for developers, helping them ensure high-quality code after implementing new features or refactoring existing ones. 代码审查工具是 Composable AI 代理运行时的一部分，用于审查 TypeScript 代码和 git diff コードレビューツールは Composable AI エージェントランタイムの一部であり，TypeScript コードと git diff をレビューするために使用 코드 리뷰 도구는 Composable AI 에이전트 런타임의 일부로서 TypeScript 코드와 git diff를 리뷰하는 데 사용 Code Reviewer es un runtime de agente de IA componible que ayuda a los desarrolladores a revisar su código de manera eficiente Code Reviewer est un runtime d''agent d''IA composable qui aide les développeurs à examiner leur code de manière efficace Code Reviewer ist ein komponierbarer KI-Agents-Runtime, der Entwicklern hilft, ihren Code effizient zu überprüfen O Code Reviewer é uma ferramenta de revisão de código baseada em AI que ajuda a melhorar a qualidade do código e a produtividade dos desenvolvedores ИИ Агент Code Reviewer - это инструмент проверки кода, основанный на ИИ, который помогает улучшить качество кода и производительность разработчиков مدقق الشفرة هو أداة مراجعة الشفرة القائمة على الذكاء الاصطناعي التي تساعد على تحسين جودة الشفرة وزيادة إنتاجية المطورين how to use code-reviewer code-reviewer alternative code-reviewer setup guide what is code-reviewer code-reviewer vs human review code-reviewer install for AI agents code-reviewer for TypeScript development AI-powered code review tools 代码审查工具 Composable AI 代理运行时 TypeScript 代码审查 git diff 代码质量审查 AI 代码审查 代码审查报告 代码审查场景 Reviews TypeScript files for new features and logical code chunks Supports focused review of specific file sets via git diff Assists in checking code quality before finalizing pull requests Provides feedback on utility functions and refactored code Integrates with existing Git workflows for seamless code review code-reviewer is a composable AI agent runtime that assists developers in reviewing code changes, such as new features or utility functions, before creating pull requests.');
